// plugins/notices.ts — Couche de documentation (spec §3.9).
// Complète les fiches en « notice » (texte long, un clic) et en documentation
// de paramètres, de façon centralisée. Appliqué à l'enregistrement via
// `avecDoc(def)` : n'écrase jamais une doc déjà présente sur la fiche.
import type { FicheAudio } from "../audio/types-domaine";

type Bilingue = { fr: string; en: string };

// Notice par identifiant de composant.
const NOTICES: Record<string, Bilingue> = {
  // ── Entrées ──
  "entree-audio": { fr: "Charge un fichier audio (WAV, MP3, FLAC, OGG…) depuis l'inspecteur et le décode en signal exploitable par les autres blocs.", en: "Loads an audio file (WAV, MP3, FLAC, OGG…) from the inspector and decodes it into a signal usable by other blocks." },
  "entree-image": { fr: "Charge un fichier image (PNG, JPEG…) depuis l'inspecteur et le transmet sur sa sortie 'Image'. La sortie image alimente l'affichage, la sonification ou l'export.", en: "Loads an image file (PNG, JPEG…) from the inspector and passes it on its 'Image' output. The image output feeds display, sonification or export." },
  "lecteur-svg": { fr: "Charge un fichier SVG depuis l'inspecteur et le rasterise en image PNG aux dimensions choisies. La sortie 'Image' peut être branchée sur un Rendu image, un Pixeltone ou un Export image.", en: "Loads an SVG file from the inspector and rasterizes it to a PNG image at the chosen dimensions. The 'Image' output can be connected to an Image Renderer, a Pixeltone, or an Image Export." },
  "enregistreur-audio": { fr: "Enregistre depuis le microphone ou l'entrée ligne. Le périphérique se choisit dans la liste, et l'enregistrement se lance et s'arrête par ses boutons : le son capté devient la source audio du bloc.", en: "Records from the microphone or line input. The device is chosen from the list, and recording starts and stops from its buttons: the captured sound becomes the block's audio source." },
  "capture-systeme-audio": { fr: "Capture le son du système (ce qui sort des haut-parleurs). Au lancement, Windows ouvre une boîte de dialogue de partage d'écran : sélectionnez l'écran ou la fenêtre, et assurez-vous que « Partager l'audio » est coché. Le son de n'importe quelle application (navigateur, lecteur, jeu) est alors capturé. Le bouton Arrêter met fin à la capture.", en: "Captures system audio (what comes out of the speakers). On start, Windows opens a screen share dialog: select the screen or window, and make sure « Share audio » is checked. Audio from any application (browser, player, game) is then captured. The Stop button ends the capture." },
  "capture-midi": { fr: "Enregistre une performance jouée sur un clavier ou contrôleur MIDI branché en USB. Le périphérique se choisit dans la liste, et les boutons Enregistrer et Arrêter bornent le jeu : les notes jouées deviennent un fichier MIDI, synthétisé en audio et transmis tel quel sur la sortie MIDI (chaînable à un Transposeur, un Quantifieur ou un Arpégiateur). Nécessite l'autorisation MIDI du navigateur/système au premier lancement.", en: "Records a performance played on a USB-connected MIDI keyboard or controller. The device is chosen from the list, and the Record and Stop buttons bound the playing: the played notes become a MIDI file, synthesized to audio and passed through as-is on the MIDI output (chainable to a Transposer, Quantizer or Arpeggiator). Requires the browser/system MIDI permission on first use." },
  "explorateur-musique": { fr: "Parcourt un dossier de musiques du projet et charge le fichier choisi comme source audio (Electron).", en: "Browses a project music folder and loads the chosen file as an audio source (Electron)." },
  "lecteur-midi": { fr: "Charge un fichier MIDI depuis l'inspecteur et le synthétise en audio (FM ou SoundFont). Le fichier MIDI est aussi transmis sur la sortie MIDI, ce qui permet de le brancher sur un Transposeur/Quantiseur, un Arpégiateur ou une Sortie MIDI.", en: "Loads a MIDI file from the inspector and synthesizes it to audio (FM or SoundFont). The MIDI file is also passed on the MIDI output, allowing it to be connected to a Transposer/Quantizer, an Arpeggiator or a MIDI Output." },
  // ── Générateurs ──
  "generateur-accords": { fr: "Génère une progression d'accords à partir de la clé, la gamme et le genre. Chaque accord est arpégé sur trois octaves.", en: "Generates a chord progression from the key, scale and genre. Each chord is arpeggiated across three octaves." },
  "melodie-aleatoire": { fr: "Compose une mélodie aléatoire dans la clé et la gamme choisies, sur le nombre de mesures indiqué. Sortie audio + sortie MIDI pour chaîner vers d'autres nodes MIDI.", en: "Composes a random melody in the chosen key and scale, over the given number of bars. Audio output + MIDI output for chaining to other MIDI nodes." },
  "generateur-fractal": { fr: "Construit une pièce par récursion d'un motif d'intervalles sur plusieurs niveaux de profondeur, produisant une structure auto-similaire. Sortie audio + sortie MIDI pour chaîner vers d'autres nodes MIDI.", en: "Builds a piece by recursively applying an interval motif over several depth levels, producing a self-similar structure. Audio output + MIDI output for chaining to other MIDI nodes." },
  "mappeur-mandelbrot": { fr: "Parcourt une vue de l'ensemble de Mandelbrot et fait de chaque point une note. Pour chaque point c de la vue, le composant itère z = z² + c et compte les itérations avant que z ne s'échappe : quelques-unes loin de l'ensemble, des centaines tout près de son bord. Ce nombre donne la hauteur, sur une échelle logarithmique répartie sur deux octaves de la gamme choisie (la sensibilité élargit ou resserre cette plage) ; plus un point est proche du bord, plus il sonne aigu et fort.\n\nLes points de l'ensemble lui-même, qui ne s'échappent jamais, sont le noir de l'image : ils se taisent, et le bord de la fractale fait alors le rythme, ou tiennent la tonique une octave plus bas.\n\nTrois modes. Escape time : la hauteur suit les itérations. Dwell : la durée des notes les suit aussi, et les points du bord s'attardent. Octave : l'octave vient de la hauteur du point dans l'image, le degré des itérations, et la vue est parcourue colonne par colonne.\n\nLe centre et le zoom choisissent la région : la vue entière donne une mélodie symétrique, puisque l'ensemble l'est de part et d'autre de l'axe réel ; un zoom sur le bord, là où la fractale se ramifie, donne des lignes plus agitées. À graine égale, les mêmes points. Sortie audio et MIDI.", en: "Scans a view of the Mandelbrot set and turns each point into a note. For each point c of the view, the node iterates z = z² + c and counts the iterations before z escapes: a few far from the set, hundreds right by its edge. That number sets the pitch, on a logarithmic scale spread over two octaves of the chosen scale (the sensitivity widens or narrows this range); the closer a point is to the edge, the higher and louder it sounds.\n\nThe points of the set itself, which never escape, are the black of the image: they fall silent, and the edge of the fractal then makes the rhythm, or they hold the tonic an octave lower.\n\nThree modes. Escape time: the pitch follows the iterations. Dwell: the note lengths follow them too, and the points of the edge linger. Octave: the octave comes from the point's height in the image, the degree from the iterations, and the view is scanned column by column.\n\nThe centre and zoom choose the region: the whole view gives a symmetric melody, since the set is symmetric about the real axis; a zoom on the edge, where the fractal branches, gives more agitated lines. Same seed, same points. Audio and MIDI output." },
  "arpege-koch": { fr: "Trois voix jouent trois niveaux du même flocon de Koch. Chacune part d'un côté du triangle formé par l'accord — de la fondamentale à la tierce, de la tierce à la quinte, de la quinte à l'octave — et le subdivise selon la règle de Koch : l'intervalle est coupé en trois, et le tiers central remplacé par un pic, dont chaque sous-segment reçoit à son tour un pic trois fois plus petit. Les hauteurs obtenues sont ramenées sur la gamme choisie.\n\nLa première voix est subdivisée à la profondeur demandée et joue en doubles-croches ; la deuxième, un niveau de moins, quatre fois plus lente ; la troisième, deux niveaux de moins, seize fois plus lente. Les trois achèvent ensemble un cycle de 4^profondeur doubles-croches : on entend le motif, sa réduction et sa réduction de réduction à la fois, dans une polyrythmie 1 : 4 : 16.\n\nLa hauteur est celle du premier pic, en demi-tons ; un pic plus petit qu'un degré de la gamme se fond dans ses voisins, si bien qu'une grande profondeur demande une grande hauteur. La direction dit de quel côté pointent les pics. Chaque niveau de profondeur quadruple la durée du cycle ; les répétitions enchaînent plusieurs cycles, et la dernière note de chaque voix clôt le tout sur l'accord. L'articulation règle la part de chaque pas qui sonne ; deux notes voisines tombées sur la même hauteur peuvent être liées ou rejouées. Sortie audio et MIDI.", en: "Three voices play three levels of the same Koch snowflake. Each starts from one side of the triangle formed by the chord - root to third, third to fifth, fifth to octave - and subdivides it by the Koch rule: the interval is cut into three, and the middle third replaced by a peak, each sub-segment of which in turn receives a peak three times smaller. The resulting pitches are brought onto the chosen scale.\n\nThe first voice is subdivided at the requested depth and plays in sixteenths; the second, one level less, four times slower; the third, two levels less, sixteen times slower. The three complete together a cycle of 4^depth sixteenths: one hears the pattern, its reduction and the reduction of its reduction at once, in a 1 : 4 : 16 polyrhythm.\n\nThe height is that of the first peak, in semitones; a peak smaller than one scale step melts into its neighbours, so a great depth calls for a great height. The direction says which way the peaks point. Each level of depth multiplies the cycle length by four; the repeats chain several cycles, and the last note of each voice closes the whole on the chord. The articulation sets how much of each step sounds; two neighbouring notes landing on the same pitch can be tied or replayed. Audio and MIDI output." },
  "spectrogramme-fractal": { fr: "Génère un spectrogramme dont le motif est un bruit fractal (somme d'octaves de bruit pseudo-aléatoire). L'image représente le temps horizontal et la fréquence verticale ; l'intensité en chaque point détermine l'amplitude spectrale. Le son est resynthétisé par transformée de Fourier inverse à court terme avec recouvrement et fenêtre de Hann. Sortie image + sortie audio.", en: "Generates a spectrogram whose pattern is fractal noise (sum of octaves of pseudo-random noise). The image represents time horizontally and frequency vertically; the intensity at each point determines the spectral amplitude. The sound is resynthesized by short-term inverse Fourier transform with overlap-add and a Hann window. Image output + audio output." },
  "attracteur-ifs": { fr: "Rend un attracteur chaotique ou un système de fonctions itérées (IFS) en image ET en son. Chaque point est calculé par itération d'équations non linéaires (Lorenz, Rössler, Hénon, Ikeda) ou de transformations affines (Barnsley, Sierpiński). La densité de points détermine la couleur de l'image. La trajectoire est aussi sonifiée : x contrôle la fréquence du canal gauche, y celle du canal droit, z l'amplitude. Sortie image + sortie audio.", en: "Renders a chaotic attractor or iterated function system (IFS) as image and sound. Each point is computed by iterating nonlinear equations (Lorenz, Rössler, Henon, Ikeda) or affine transformations (Barnsley, Sierpinski). Point density determines the image color. The trajectory is also sonified: x controls the left-channel frequency, y the right-channel frequency, z the amplitude. Image output + audio output." },
  "boite-rythmes": { fr: "Génère une piste rythmique à partir d'un patron (Rock, Funk, House…), avec réglage du volume de chaque percussion. Une seconde sortie donne le même rythme en MIDI, sur le canal 10 des percussions et aux numéros du General MIDI (36 grosse caisse, 38 caisse claire, 42 charley fermé…) : le même rythme se rejoue ainsi avec d'autres sons. Le volume de chaque percussion y devient une vélocité, un fichier MIDI n'ayant pas de volume.", en: "Generates a drum track from a pattern (Rock, Funk, House…), with per-drum volume control. A second output gives the same rhythm as MIDI, on percussion channel 10 and at the General MIDI numbers (36 kick, 38 snare, 42 closed hi-hat…): the same rhythm can thus be played with other sounds. Each drum's volume becomes a velocity there, since a MIDI file has no volume." },
  "rythme-cantor": { fr: "Génère une groove rythmique auto-similaire par récursion de Cantor sur une grille de 64 pas par mesure. À chaque niveau de profondeur, la partie centrale (ou gauche/droite/aléatoire) de chaque intervalle restant est retirée. Les pas survivants déclenchent des percussions : en mode « Tous », kick = niveaux 0, 3, 6…, caisse claire = niveaux 1, 4…, charley = niveaux 2, 5…, créant ainsi une texture rythmique fractale. Une seconde sortie donne le même rythme en MIDI, sur le canal 10 des percussions et aux numéros du General MIDI (36 grosse caisse, 38 caisse claire, 42 charley fermé…) : le même rythme se rejoue ainsi avec d'autres sons. Le swing et le volume y sont conservés, le volume devenant la vélocité des frappes.", en: "Generates a self-similar rhythmic groove by Cantor recursion on a 64-step grid per bar. At each depth level, the central (or left/right/random) part of each remaining interval is removed. Surviving steps trigger drums: in 'All' mode, kick = levels 0, 3, 6…, snare = levels 1, 4…, hi-hat = levels 2, 5…, creating a fractal rhythmic texture. A second output gives the same rhythm as MIDI, on percussion channel 10 and at the General MIDI numbers (36 kick, 38 snare, 42 closed hi-hat…): the same rhythm can thus be played with other sounds. Swing and volume are kept there, the volume becoming the velocity of the hits." },
  "documentation-graphe": { fr: "Documente le graphe où il est posé, et non le catalogue en général, que components.md couvre. Ce composant-ci répond à un autre besoin, celui de confier un graphe à quelqu'un — un collègue, ou un agent qui doit bâtir une application dessus. Il lit le graphe entier, relève pour chaque composant ses valeurs réglées et non ses valeurs par défaut, retrouve son câblage port par port, calcule l'ordre dans lequel le moteur les exécute, et rassemble la notice de chaque composant employé — une fois par composant, quel que soit le nombre d'exemplaires.\n\nDeux textes sortent du même relevé, parce que deux publics ne lisent pas la même chose. La sortie « Documentation » est du Markdown dense, dans l'ordre utile à un agent : le graphe d'abord, les notices ensuite, et le JSON du graphe pour finir, qui suffit à le reconstruire. La sortie « Site » est une page HTML autonome — sommaire à gauche, tableaux de paramètres, et un schéma du graphe dessiné aux positions réelles des composants, de sorte que celui qui lit la page reconnaisse ce qu'il a sous les yeux dans l'application.\n\nQuatre choses valent d'être sues. Le composant n'a aucune entrée : il n'a rien à recevoir, et sa place dans le graphe n'a pas d'importance. Il documente le graphe tel qu'il est composé, méta-composants non dépliés et boucles non déroulées, parce que personne ne reconnaîtrait son travail dans des copies de boucle numérotées. Il signale ce qui empêcherait le graphe de tourner — une entrée obligatoire laissée libre, un composant inconnu du registre, un cycle.\n\nEt il n'écrit rien sur le disque tant qu'aucun dossier de sortie n'est donné. Une limite, enfin, et elle est dite plutôt que contournée : la documentation d'un composant est sa notice, ses ports et ses paramètres, pas son code source — l'application livrée ne contient pas ses sources, et promettre le code serait promettre ce qu'on ne peut pas tenir.", en: "Documents the graph it sits in, rather than the catalogue in general, which components.md covers. This node answers another need, that of handing a graph over to someone — a colleague, or an agent that has to build an application on it. It reads the whole graph, records each node's set values rather than its defaults, recovers its wiring port by port, computes the order in which the engine runs them, and gathers the notice of every component used — once per component, however many instances there are.\n\nTwo texts come out of the same survey, because two audiences do not read the same thing. The « Documentation » output is dense Markdown, in the order useful to an agent: the graph first, the notices next, and the graph's JSON last, which is enough to rebuild it. The « Site » output is a self-contained HTML page — contents on the left, parameter tables, and a diagram of the graph drawn at the nodes' real positions, so that whoever reads the page recognises what they have in front of them in the application.\n\nFour things are worth knowing. The node has no input: it has nothing to receive, and where it sits does not matter. It documents the graph as it is composed, meta-components unexpanded and loops unrolled, because nobody would recognise their work in numbered loop copies. It flags what would stop the graph from running — a required input left free, a component unknown to the registry, a cycle. And it writes nothing to disk until an output folder is given.\n\nOne limit, finally, stated rather than worked around: a component's documentation is its notice, its ports and its parameters, not its source code — the shipped application does not contain its sources, and promising the code would be promising what cannot be delivered." },
  "clavier-apprentissage": { fr: "Montre un fichier MIDI joué sur un clavier de quatre-vingt-huit touches, une couleur par main, en même temps qu'il le fait entendre. Le composant ne se joue pas : il montre — voir où se posent les doigts pendant qu'on écoute. L'animation suit l'élément audio et rien d'autre : une horloge à part dériverait au bout de quelques secondes, et un clavier en avance d'un temps sur ce qu'on entend ne montre plus rien. Les deux mains sont attribuées par la même fonction qui juge la jouabilité,  Reste la question que pose tout fichier qu'on n'a pas écrit soi-même : est-il seulement jouable sur un clavier ?\n\nLa réponse se scinde en deux. Quatre empêchements se décident, sans arbitraire : une note hors des 88 touches ne peut pas être affichée ; le canal 10 du MIDI porte des instruments de percussion et non des hauteurs, les poser sur un clavier n'aurait pas de sens ; plus de dix notes ensemble, c'est plus de dix doigts ; et surtout un accord doit pouvoir se partager entre deux mains — deux mains ne se croisent pas, il n'y a donc que n+1 partages possibles et le composant les essaie tous, chaque côté devant tenir dans cinq doigts et dans l'écart réglé.\n\nTrois choses ne se décident pas, et le composant rend des chiffres plutôt qu'un verdict : la vitesse — mesurée par main, faute de quoi deux mains alternées donneraient un débit deux fois trop rapide —, le plus grand saut rapporté au temps donné pour le faire, et les notes tenues sous d'autres, qui demandent la pédale ou un changement de doigt. Le composant ne refuse aucun fichier. Il montre ce qu'il peut et nomme ce qu'il ne peut pas, dans sa sortie Conformité.\n\nL'adaptation existe — replier les octaves, écarter la percussion — mais elle se demande explicitement, une adaptation silencieuse changeant la musique sans le dire. Le canal, enfin : un morceau de piano tient sur un canal, un fichier d'orchestre en a seize, et les montrer tous rend le clavier illisible. Le réglage « Canal » choisit, et « Automatique » prend le canal le plus fourni en évitant la percussion — sur un fichier d'orchestre, le plus chargé est souvent la batterie.\n\nLa sortie MIDI est ce qui est montré et entendu, canal et adaptation compris, et non l'entrée recopiée : la vue la relit pour allumer les touches, et les deux ne peuvent donc pas diverger.", en: "Shows a MIDI file played on an eighty-eight-key keyboard, one colour per hand, while playing it back. It is the reverse of the « Melody Keyboard », which is played with the mouse and records: this one watches, and it is made for learning — seeing where the fingers land while you listen. The animation follows the audio element and nothing else: a separate clock would drift within seconds, and a keyboard a beat ahead of what you hear teaches nobody anything.\n\nThe two hands are assigned by the very function that judges playability, and that is what no ordinary MIDI player shows. Then comes the question any file you did not write yourself raises: is it even playable on a keyboard? The answer splits in two, and that is the node's whole work. Four impossibilities can be decided, with no arbitrariness: a note outside the 88 keys cannot be displayed; MIDI channel 10 carries percussion instruments rather than pitches, and putting them on a keyboard would be a lie; more than ten notes at once is more than ten fingers; and above all a chord must be splittable between two hands — two hands do not cross, so there are only n+1 possible splits and the node tries them all, each side having to fit within five fingers and the configured span.\n\nThree things cannot be decided, and the node gives figures rather than a verdict: speed — measured per hand, failing which two alternating hands would yield a rate twice too fast —, the largest jump relative to the time available for it, and notes held under others, which call for the pedal or a finger substitution. The node refuses nothing: one learns on real repertoire, not on certified files. It shows what it can and names what it cannot, in its Conformance output.\n\nAdaptation exists — folding octaves, dropping percussion — but it must be asked for: a silent adaptation would lie about the music, a chosen one is an arrangement. One last point, which comes before all the rest: a piano piece fits on one channel, an orchestral file has sixteen, and showing them all makes the keyboard unreadable. The « Channel » setting picks, and « Automatic » takes the busiest channel while avoiding percussion — in an orchestral file the busiest is often the drums.\n\nThe MIDI output is what is shown and heard, channel and adaptation included, rather than the input copied: the view reads it back to light the keys, so the two cannot diverge." },
  "vitesse-midi": { fr: "Joue un fichier MIDI plus lentement ou plus vite. Et sur du MIDI il est exact la ou l'audio ne fait qu'approcher : rien n'est reechantillonne, les hauteurs ne bougent pas d'un centieme de ton, et aucun artefact n'apparait a quatre fois plus lent. Trois facons de dire la meme chose, parce qu'on ne pense pas dans la meme unite selon ce qu'on fait : un facteur quand on sait ce qu'on veut — 0,5 joue deux fois plus lentement, 2 deux fois plus vite —, un pourcentage quand on tatonne, un tempo cible quand on cale un morceau sur un autre, le composant lisant alors le tempo du fichier et faisant la division lui-meme.\n\nDeux points valent d'etre connus. Le MIDI de sortie n'est pas reencode : seul son tempo est reecrit, ce qui laisse les positions en tics intactes, si bien que canaux, changements de programme, controleurs, pedale et noms de pistes traversent l'operation sans une egratignure — un reencodage depuis les seules hauteurs aurait aplati un piano a deux mains sur un canal unique. C'est aussi ce qui garde la notation juste : une noire reste une noire et c'est le tempo qui change, la ou un etirement naif doublerait toutes les valeurs de note et rendrait la partition illisible.\n\nEnsuite, une duree ne se divise pas indefiniment : a huit fois plus vite, une double croche tombe sous cinq millisecondes et n'est plus une note mais un clic. Un plancher reglable l'en empeche, et le nombre de notes concernees est annonce ; il ne vaut que pour l'audio rendu ici, le MIDI de sortie gardant ses durees exactes. Un fichier a tempo variable garde son relief, chaque changement etant etire ; le composant le signale, parce que le tempo qu'il annonce n'est alors que le premier.", en: "Plays a MIDI file slower or faster. And on MIDI it is exact where audio can only approximate: nothing is resampled, pitches do not move by a hundredth of a tone, and no artefact appears at four times slower. Three ways of saying the same thing, because one does not think in the same unit depending on the task: a factor when you know what you want — 0.5 plays twice as slow, 2 twice as fast —, a percentage when feeling your way, a target tempo when matching one piece to another, the node then reading the file's tempo and doing the division itself.\n\nTwo points are worth knowing. The MIDI output is not re-encoded: only its tempo is rewritten, which leaves the tick positions untouched, so channels, program changes, controllers, pedal and track names go through without a scratch — re-encoding from pitches alone would have flattened a two-handed piano part onto a single channel. That is also what keeps the notation right: a quarter note stays a quarter note and the tempo changes, where a naive stretch would double every note value and make the score unreadable.\n\nThen, a duration cannot be divided indefinitely: at eight times faster a sixteenth note falls below five milliseconds and is no longer a note but a click. An adjustable floor prevents it, and the number of notes concerned is announced; it only applies to the audio rendered here, the MIDI output keeping its exact durations. A file with a variable tempo keeps its relief, every change being stretched; the node says so, because the tempo it announces is then only the first." },
  "separation-harmonique-percussive": { fr: "Separe un son en deux : ce qui tient et ce qui claque. D'apres Derry Fitzgerald, « Harmonic/Percussive Separation using Median Filtering », 13e conference internationale sur les effets audionumeriques (DAFx-10), Graz, 2010 — arrow.tudublin.ie/argcon/67. L'idee tient en deux phrases, et c'est ce qui la rend belle. Sur un spectrogramme, une note tenue est une ligne horizontale — meme bande de frequence, beaucoup de trames — et une percussion une ligne verticale — meme instant, toutes les frequences d'un coup.\n\nUn filtre median le long du temps efface donc ce qui est bref et garde ce qui dure ; le meme filtre le long des frequences fait exactement l'inverse. Deux passages, deux masques, deux sons. Ce n'est pas le Separateur IA, et les deux ne servent pas a la meme chose : celui-la cherche des instruments — voix, batterie, basse — avec un modele de plusieurs dizaines de megaoctets ; celui-ci ne cherche rien, n'a aucun modele, tourne en quelques secondes et fonctionne sur n'importe quelle matiere, y compris celle qu'aucun reseau n'a jamais vue.\n\nIl sert la ou l'autre n'a rien a dire : reverberer les tenues sans noyer les attaques, compresser les attaques sans pomper sur les tenues, remplacer une batterie en gardant l'harmonie, ou simplement regarder de quoi un son est fait — le message annonce la part percussive. La propriete a laquelle on tient : les deux masques sont complementaires, leur somme vaut un en tout point. Les deux sorties remises bout a bout redonnent donc le son de depart, echantillon pour echantillon — rien ne se perd et rien ne s'invente entre elles, ce qu'un masque permet et qu'une resynthese ne permettrait pas.\n\nC'est ce qui autorise a dire qu'on a separe plutot que transforme. Les trois reglages se lisent ensemble : la fenetre decide de ce qu'on peut distinguer, les deux longueurs de filtre de ce qui compte comme « qui dure » et « qui est large », et le partage de la fermete du verdict sur la matiere ambigue.", en: "Splits a sound in two: what sustains and what strikes. After Derry Fitzgerald, « Harmonic/Percussive Separation using Median Filtering », 13th International Conference on Digital Audio Effects (DAFx-10), Graz, 2010 — arrow.tudublin.ie/argcon/67. The idea fits in two sentences. On a spectrogram, a sustained note is a horizontal line — same frequency band, many frames — and a percussive hit a vertical line — same instant, every frequency at once. A median filter along time therefore erases what is brief and keeps what lasts; the same filter along frequency does exactly the opposite.\n\nTwo passes, two masks, two sounds. This is not the AI Separator, and the two serve different purposes: that one looks for instruments — voice, drums, bass — with a model of several tens of megabytes; this one looks for nothing, has no model, runs in seconds and works on any material, including material no network has ever seen. It serves where the other has nothing to say: reverberating sustains without drowning attacks, compressing attacks without pumping on sustains, replacing a drum part while keeping the harmony, or simply looking at what a sound is made of — the message states the percussive share.\n\nThe property that matters: the two masks are complementary, their sum is one at every point. The two outputs added back together therefore give the original sound, sample for sample — nothing is lost and nothing is invented between them, which a mask allows and a resynthesis would not. It is what licenses saying that one has separated rather than transformed. The three settings read together: the window decides what can be distinguished, the two filter lengths what counts as « lasting » and « wide », and the split how firm the verdict is on ambiguous material." },
  "decaleur-frequence": { fr: "Ajoute le meme nombre de hertz a toutes les frequences. D'apres Scott Wardle, « A Hilbert-Transformer Frequency Shifter for Audio », DAFx-98 ; l'original est analogique, decrit par Harald Bode et Robert Moog dans « A High-Accuracy Frequency Shifter for Professional Audio Applications », Journal of the Audio Engineering Society, 1972. Le decalage de frequence n'est ni une modulation en anneau ni une transposition. Le transpositeur multiplie les frequences : 200-400-600 monte d'une octave donne 400-800-1200, les rapports sont gardes, le son reste harmonique et l'on entend une note plus haute.\n\nLe modulateur en anneau rend les deux bandes laterales a la fois, somme et difference. Le decaleur, lui, additionne, et une seule bande laterale : 200-400-600 decale de 50 donne 250-450-650. Les rapports ne sont plus entiers, l'harmonicite est detruite, et c'est pourquoi une note devient cloche, barre de metal, chose inouie — tout en gardant son enveloppe et son rythme intacts. Quelques hertz suffisent a faire battre un son sans le denaturer ; au-dela de la centaine, on quitte franchement la hauteur de depart.\n\nTechniquement, on forme le signal analytique — le signal et sa transformee de Hilbert, qui est le meme signal dephase de quatre-vingt-dix degres a toutes les frequences — puis on le fait tourner dans le plan complexe a la vitesse voulue. Un decalage negatif donne l'autre bande laterale sans qu'on ait a le demander. Un defaut inherent : vers le bas, les partiels qui passeraient sous zero hertz se replient autour de zero et remontent. Descendre un partiel de 200 Hz de 300 Hz ne donne pas moins 100 mais 100, de l'autre cote.\n\nCe n'est pas un bogue, c'est ce que fait une bande laterale unique, et c'est une part de son caractere — mais cela explique qu'un grand decalage vers le bas sur une basse rende autre chose qu'une basse plus grave. L'ecart stereo, enfin, decale le canal droit de quelques dixiemes de hertz de plus : les deux canaux derivent lentement l'un par rapport a l'autre et le son s'elargit, sans le dephasage destructeur d'un retard.", en: "Adds the same number of hertz to every frequency. After Scott Wardle, « A Hilbert-Transformer Frequency Shifter for Audio », DAFx-98; the original is analogue, described by Harald Bode and Robert Moog in « A High-Accuracy Frequency Shifter for Professional Audio Applications », Journal of the Audio Engineering Society, 1972. The pitch shifter multiplies frequencies: 200-400-600 raised an octave gives 400-800-1200, the ratios are kept, the sound stays harmonic and one hears a higher note.\n\nThe ring modulator returns both sidebands at once, sum and difference. The shifter adds, and a single sideband: 200-400-600 shifted by 50 gives 250-450-650. The ratios are no longer whole numbers, harmonicity is destroyed, and that is why a note becomes a bell, a metal bar, an unheard-of thing — while keeping its envelope and its rhythm intact. A few hertz are enough to make a sound beat without disfiguring it; beyond a hundred, the original pitch is frankly left behind.\n\nTechnically, the analytic signal is formed — the signal and its Hilbert transform, which is the same signal shifted ninety degrees at every frequency — then rotated in the complex plane at the wanted speed. A negative shift gives the other sideband without having to ask for it. One inherent flaw, better known than suffered: downwards, partials that would pass below zero hertz fold around zero and come back up. Lowering a 200 Hz partial by 300 Hz does not give minus 100 but 100, on the other side.\n\nThis is not a bug, it is what a single sideband does, and it is part of its character — but it explains why a large downward shift on a bass gives something other than a lower bass. The stereo offset, finally, shifts the right channel by a few tenths of a hertz more: the two channels drift slowly apart and the sound widens, without the destructive phasing of a delay." },
  "texture-statistique": { fr: "Engendre une texture neuve qui a les statistiques d'un son donne. D'apres Josh H. McDermott et Eero P. Simoncelli, « Sound Texture Perception via Statistics of the Auditory Periphery: Evidence from Sound Synthesis », Neuron 71(5), 2011. La these de l'article, et c'est elle qu'on met en oeuvre : une texture — pluie, feu, foule, applaudissements — se reconnait a des statistiques moyennees dans le temps, mesurees sur une decomposition du son telle que l'oreille la fait.\n\nDeux enregistrements de pluie n'ont aucun echantillon en commun ; ce qu'ils partagent, ce sont ces nombres-la. D'ou le procede : mesurer les statistiques d'un son, puis fabriquer un bruit neuf qui les respecte. En regard du gel et du mosaiquage : le gel granulaire boucle un grain, la mosaique de corpus recopie des grains, et l'oreille finit toujours par entendre la boucle. Ici rien n'est recopie — la sortie ne contient aucun echantillon de l'entree, et elle peut durer indefiniment sans se repeter.\n\nLa duree demandee n'a donc aucun rapport avec celle du modele : cinq secondes de pluie en produisent deux minutes. Ce qui est impose, et ce qui ne l'est pas, car la part honnete importe ici. Impose : la distribution complete de l'enveloppe de chaque bande — donc sa moyenne, sa variance, son asymetrie, son aplatissement et tous les moments suivants, obtenus par transport de rang plutot que par ajustement des quatre premiers — et les correlations entre bandes.\n\nL'article montre que les premieres seules ne suffisent pas et que ce sont les secondes qui font basculer le resultat vers quelque chose de reconnaissable ; l'ecart statistique au modele passe de 40 % a 31 % quand on impose les correlations. Non impose : les correlations de modulation C1 et C2 de l'article, qui demandent un second banc de filtres sur les enveloppes — leur absence s'entend surtout sur les textures tres rythmees, ou la regularite se perd.\n\nEnfin l'article boucle analyse et synthese par descente de gradient, la ou ce composant impose les statistiques dans le domaine des enveloppes par projections alternees puis reconstruit une fois : deux ordres de grandeur plus vite, et l'ecart restant est affiche plutot que taise. Chaque canal recoit sa propre graine, si bien que les deux cotes partagent les statistiques sans partager un echantillon — la texture est large d'elle-meme, ce qu'aucun elargisseur ne donne.", en: "Generates a new texture having the statistics of a given sound. After Josh H. McDermott and Eero P. Simoncelli, « Sound Texture Perception via Statistics of the Auditory Periphery: Evidence from Sound Synthesis », Neuron 71(5), 2011. The paper's thesis, which is what is implemented here: a texture — rain, fire, crowd, applause — is recognised by time-averaged statistics, measured on a decomposition of the sound such as the ear performs. Two recordings of rain share no sample; what they share are those numbers.\n\nHence the procedure: measure a sound's statistics, then build a new noise that respects them. In regard of freezing and mosaicing: granular freeze loops a grain, corpus mosaicing copies grains, and the ear always ends up hearing the loop. Here nothing is copied — the output contains no sample of the input, and it can last indefinitely without repeating. The requested duration therefore bears no relation to the model's: five seconds of rain produce two minutes.\n\nWhat is imposed, and what is not, because the honest part matters here. Imposed: the complete distribution of each band's envelope — hence its mean, variance, skewness, kurtosis and every following moment, obtained by rank transport rather than by fitting the first four — and the correlations between bands. The paper shows that the former alone do not suffice and that the latter are what tip the result towards something recognisable; the statistical distance to the model falls from 40 % to 31 % when the correlations are imposed.\n\nNot imposed: the paper's C1 and C2 modulation correlations, which require a second filterbank on the envelopes — their absence is heard mostly on very rhythmic textures, where regularity is lost. Finally the paper loops analysis and synthesis by gradient descent, where this node imposes the statistics in the envelope domain by alternating projections and then reconstructs once: two orders of magnitude faster, and the remaining distance is displayed rather than hidden.\n\nOne last detail that matters: each channel gets its own seed, so both sides share the statistics without sharing a sample — the texture is wide of itself, which no stereo widener gives." },
  "frontiere-note": { fr: "Porte la note jouée dans une chaîne d'instrument. C'est la frontière : tout ce qui est branché entre ce composant et « Fin d'instrument » est la recette de l'instrument, et le moteur la recopie une fois par note du clavier avant de l'exécuter, en injectant la note dans chaque copie. Rien n'est transposé : chaque note est calculée à sa hauteur, ce qui est la différence entre un synthétiseur et un échantillonneur. Seul — sans fin en aval —, le composant rend la note réglée dans l'inspecteur : de quoi écouter et régler l'instrument à une hauteur avant de le décliner sur les quatre-vingt-huit touches. Trois sorties, et aucune ne remplace les deux autres. Audio : une excitation à la fréquence de la note — dent de scie pour donner du grain à un filtre, impulsion pour exciter un résonateur comme une corde pincée, bruit pour un son soufflé ou une percussion. MIDI : un fichier d'une seule note, pour les composants qui jouent des notes eux-mêmes — instrument Csound, modèles physiques, SoundFont, synthétiseur de batterie. Courbe : la hauteur normalisée sur l'étendue du clavier, en échelle logarithmique, pour piloter un paramètre avec la note — un filtre qui s'ouvre vers l'aigu, par exemple. N'offrir que la première aurait fermé les deux autres familles d'instruments.", en: "Carries the played note into an instrument chain. This is the boundary: everything wired between this node and « Instrument End » is the instrument's recipe, and the engine copies it once per keyboard note before execution, injecting the note into each copy. Nothing is transposed: each note is computed at its own pitch, which is the difference between a synthesiser and a sampler. On its own — with no end downstream — the node renders the note set in the inspector: enough to listen to and tune the instrument at one pitch before spreading it across the eighty-eight keys. Three outputs, and none replaces the other two. Audio: an excitation at the note's frequency — sawtooth to give a filter something to bite on, impulse to excite a resonator like a plucked string, noise for a breathy sound or a percussion. MIDI: a one-note file, for the nodes that play notes themselves — Csound instrument, physical models, SoundFont, drum synth. Curve: the pitch normalised over the keyboard range, on a logarithmic scale, to drive a parameter with the note — a filter opening toward the treble, for instance. Offering only the first would have shut out the other two families of instruments." },
  "instrument-fin": { fr: "Referme une chaîne d'instrument et rassemble les rendus de toutes les notes en une banque de clavier, jouable par « Sampler multi-zones » et exportable en SFZ. Le moteur a déjà fait le travail : avant l'exécution, il a recopié la chaîne comprise entre « Note d'instrument » et ce composant une fois par note, et chaque copie dépose ici son rendu, dans l'ordre des notes. Ce composant ne fait donc que poser les bornes des zones et les boucles. En quoi cela diffère d'« Étaler sur le clavier » : là-bas, un son enregistré est transposé vers chaque zone, et un son transposé de quatre octaves reste un son transposé de quatre octaves. Ici la recette est rejouée à chaque hauteur : il n'y a aucun artefact de transposition, et la largeur de zone ne dégrade pas le son de la racine — elle décide seulement de combien de demi-tons les touches voisines seront rééchantillonnées à la lecture. Le coût est l'autre face : la chaîne est exécutée une fois par note, soit dix-huit fois à ±2 demi-tons sur 88 touches. Le dépliage refuse au-delà de soixante-quatre notes, et le dit, plutôt que de lancer des centaines de rendus. Les copies sont indépendantes — un instrument ne chaîne pas ses notes, contrairement à une boucle de graphe. Ce qui sort de la chaîne ailleurs que par ce composant ne sort qu'une fois, depuis la copie de la note la plus grave.", en: "Closes an instrument chain and gathers every note's render into a keyboard bank, playable by « Multi-Zone Sampler » and exportable as SFZ. The engine has already done the work: before execution it copied the chain between « Instrument Note » and this node once per note, and each copy deposits its render here, in note order. This node therefore only sets the zone bounds and the loops. How this differs from « Spread across keyboard »: there, a recorded sound is transposed to each zone, and a sound transposed by four octaves remains a sound transposed by four octaves. Here the recipe is replayed at each pitch: there is no transposition artefact at all, and the zone width does not degrade the root's sound — it only decides by how many semitones neighbouring keys will be resampled at playback. The cost is the other side: the chain runs once per note, so eighteen times at ±2 semitones over 88 keys. The unrolling refuses beyond sixty-four notes, and says so, rather than launching hundreds of renders. The copies are independent — an instrument does not chain its notes, unlike a graph loop. Whatever leaves the chain other than through this node leaves only once, from the lowest note's copy." },
  "repartiteur-midi": { fr: "Coupe un fichier MIDI en parties, une par instrument, pour qu'un arrangement complet puisse être joué par plusieurs banques d'échantillons — la mélodie par l'une, les accords par une autre, la basse par une troisième, la batterie par un kit. C'était le chaînon manquant : « Sampler multi-zones » joue un MIDI avec une banque, si bien qu'un fichier à quatre canaux envoyait ses quatre parties dans le même instrument — un piano qui joue aussi la grosse caisse, deux octaves trop haut.\n\nLes notes portaient leur canal depuis toujours, rien ne s'en servait. Ce que ce composant garantit, et qu'on n'obtient pas avec quatre séquenceurs séparés : les parties sortent du même fichier, donc du même tempo et de la même origine des temps — il n'y a rien à synchroniser, et un changement de tempo les suit toutes. Le canal 10 est à part : le General MIDI le réserve aux percussions, où le numéro de note ne désigne pas une hauteur mais un instrument — 36 grosse caisse, 38 caisse claire, 42 charley.\n\nIl part donc toujours sur la sortie Batterie, qui demande une banque d'un autre genre, un kit, où une touche est un son et non une hauteur. Trois modes. Automatique : le composant inventorie le fichier et répartit seul, dans l'ordre des canaux. Par canaux : vous écrivez les canaux de chaque partie, comptés de 1 à 16 comme sur un appareil, avec les plages (« 1-3 ») et les listes (« 1,4 »). Par pistes : les mêmes cases désignent des numéros de pistes, ce qu'il faut pour les fichiers dont les voix partagent un canal — un logiciel de notation écrit souvent les quatre voix d'un chœur sur le canal 1, séparées par pistes ; le tempo est alors conservé dans chaque partie même quand la piste qui le portait n'en fait pas partie.\n\nLa sortie « Reste » existe pour qu'aucune note ne disparaisse en silence : tout canal ou piste qui joue et qui n'a été assigné à aucune partie s'y retrouve, et le message du composant le nomme. Ce message dit d'ailleurs où est passé quoi, avec le compte de notes de chaque partie : une partie muette parce qu'elle n'a rien reçu ne se confond alors pas avec un sampler mal réglé.", en: "Splits a MIDI file into parts, one per instrument, so that a full arrangement can be played by several sample banks — the melody by one, the chords by another, the bass by a third, the drums by a kit. This was the missing link: « Multi-Zone Sampler » plays a MIDI file with one bank, so a four-channel file sent all four parts into the same instrument — a piano playing the kick drum too, two octaves too high. Notes have always carried their channel; nothing used it.\n\nWhat this node guarantees, and what four separate sequencers do not: the parts come from the same file, hence the same tempo and the same time origin — there is nothing to synchronise, and a tempo change follows all of them. Channel 10 is special: General MIDI reserves it for percussion, where the note number means an instrument rather than a pitch — 36 kick, 38 snare, 42 hi-hat. It therefore always goes to the Drums output, which needs a different kind of bank, a kit, where a key is a sound and not a pitch.\n\nThree modes. Automatic: the node inventories the file and splits on its own, in channel order. By channels: you write each part's channels, counted from 1 to 16 as on a device, with ranges (« 1-3 ») and lists (« 1,4 »). By tracks: the same boxes mean track numbers, which is what files whose voices share a channel need — a notation program often writes a choir's four voices on channel 1, separated by tracks; the tempo is then kept in every part even when the track that carried it is not one of them.\n\nThe « Rest » output exists so that no note vanishes silently: any channel or track that plays and was assigned to no part ends up there, and the node's message names it. That message also says what went where, with each part's note count: a part that is silent because it received nothing is then not mistaken for a badly set sampler." },
  "banque-sfz": { fr: "Charge une banque d'échantillons SFZ et la met à disposition du graphe, sans clavier. Le composant amène un .sfz du disque et le rend disponible comme banque, sans passer par un clavier. La batterie est intégrée : le kit, source par défaut de ce composant, est fait de huit sons aux notes du General MIDI — 36 grosse caisse, 38 caisse claire, 39 clap, 42 charley fermé, 45 tom grave, 46 charley ouvert, 49 crash, 50 tom aigu. Ces sons sont ceux du séquenceur de batterie avancé, rendus en fichiers et embarqués dans l'application au même titre que le SoundFont par défaut : trois cent soixante-dix kilo-octets, aucun échantillon tiers, aucun téléchargement, et le composant donne une batterie jouable sans qu'on règle quoi que ce soit.\n\nLe type de banque est ce qui rend la batterie juste, et c'est la différence la plus importante de ce composant. Une banque de hauteurs cherche toujours la zone la plus proche : mesuré sur un vrai kit lu de cette façon, la touche 37 — absente du General MIDI — jouait la grosse caisse un demi-ton plus haut, et la touche 60 le crash à une octave et demie au-dessus. Un kit ne transpose rien et laisse muette une touche sans son. Le fichier le dit lui-même — des régions d'une seule touche, ou un « pitch_keytrack=0 » —, et le mode automatique le détecte ; imposer l'un ou l'autre reste possible, y compris pour obtenir exprès un kit transposé.\n\nLes couches de vélocité sont conservées. Un piano échantillonné sérieusement a trois à huit enregistrements par touche — joué doucement, le marteau effleure la corde ; joué fort, il claque —, et ce n'est pas une affaire de niveau : un échantillon forte baissé de vingt décibels reste un échantillon forte. Chaque couche devient une zone avec sa plage de vélocité, et le message annonce leur nombre. Si le fichier déclare « amp_veltrack », il est suivi : à zéro, la vélocité ne choisit que la couche et ne touche plus au niveau, ce qui évite le double effet qui rendait les notes jouées piano presque inaudibles.\n\nL'aperçu fait entendre chaque son l'un après l'autre — une note par touche, et non une par zone —, puis, quand il y a des couches, un escalier de nuances sur une seule touche, de la plus douce à la plus forte : c'est la seule façon d'entendre ce que les couches apportent sans brancher ni clavier ni MIDI.", en: "Loads an SFZ sample bank and hands it to the graph, with no keyboard. The node brings a .sfz from disk and offers it as a bank, without going through a keyboard. The drums are built in: the kit, this node's default source, holds eight sounds on General MIDI notes — 36 kick, 38 snare, 39 clap, 42 closed hi-hat, 45 low tom, 46 open hi-hat, 49 crash, 50 high tom. Those sounds are the advanced drum sequencer's own, rendered to files and bundled with the application just like the default SoundFont: three hundred and seventy kilobytes, no third-party samples, no download, and the node gives a playable drum kit with nothing to set.\n\nThe bank type is what makes the drums right, and it is this node's most important distinction. A pitched bank always looks for the nearest zone: measured on a real kit read that way, key 37 — absent from General MIDI — played the kick a semitone higher, and key 60 played the crash an octave and a half up. A kit transposes nothing and leaves a key with no sound silent. The file says so itself — single-key regions, or a « pitch_keytrack=0 » — and automatic mode detects it; forcing either remains possible, including to get a deliberately transposed kit.\n\nVelocity layers are kept. A seriously sampled piano has three to eight recordings per key — played softly the hammer brushes the string, played hard it slams — and that is not a matter of level: a forte sample turned down twenty decibels remains a forte sample. Each layer becomes a zone with its velocity range, and the message reports how many there are. If the file declares « amp_veltrack », it is honoured: at zero, velocity only picks the layer and no longer touches the level, which avoids the double effect that made notes played piano nearly inaudible.\n\nThe preview plays each sound one after another — one note per key, not one per zone — then, when there are layers, a staircase of dynamics on a single key, from softest to loudest: the only way to hear what the layers bring without wiring a keyboard or a MIDI file." },
  "clavier-sfz": { fr: "Un clavier de quatre-vingt-huit touches, jouable à la souris ou au clavier de l'ordinateur, qui fait sonner une banque d'échantillons. Ce composant lit un .sfz au niveau du composant, et l'instrument peut donc différer d'un composant à l'autre dans un même graphe. Deux sources, et c'est là le double intérêt. Le fichier : le bouton 📂 désigne un .sfz, ses échantillons sont lus à côté, et le chemin est retenu dans le graphe. L'entrée banque : « Étaler sur le clavier » ou « Fin d'instrument » branchés directement, sans passer par le disque ; il faut alors avoir lancé le graphe une fois pour que le clavier ait de quoi jouer.\n\nCe qu'on joue s'enregistre, et le composant rend trois choses : l'audio de la séquence, son MIDI, et la banque elle-même, qu'on peut donc enchaîner vers « Export SFZ » ou « Sampler multi-zones ». Les rapports de lecture sont ceux du rendu : la même fonction sert au jeu en direct et à l'audio du graphe, si bien que ce qu'on entend en s'écoutant est ce qui sortira. Ce qui est lu du format : les régions, l'héritage des opcodes par <global>, <master> et <group>, les noms de notes comme les nombres, default_path, les boucles de maintien, tune, volume et transpose.\n\nCe qui ne l'est pas est dit dans le message du composant plutôt que deviné : les opcodes ignorés sont comptés et nommés, les échantillons introuvables aussi, et les couches de vélocité sont gardées : une touche peut porter trois à huit enregistrements — piano, mezzo, forte —, et c'est la vélocité jouée qui choisit lequel sonne. Au clavier, la vélocité vient du rythme de frappe : jouer vite fait sonner la couche forte. Un #include est signalé et non suivi.", en: "An eighty-eight-key keyboard, playable with the mouse or the computer keyboard, that sounds a sample bank. This node reads a .sfz at node level, and the instrument may differ from one node to the next within a single graph. Two sources, and that is the double point. The file: the 📂 button picks a .sfz, its samples are read beside it, and the path is kept in the graph — enough to check what you have just exported, or to play a bank from elsewhere.\n\nThe bank input: « Spread Across Keyboard » or « Instrument End » wired straight in, with no disk round trip; the graph must then have been run once for the keyboard to have something to play. What you play is recorded, and the node outputs three things: the sequence's audio, its MIDI, and the bank itself, which can therefore be chained on to « SFZ Export » or « Multi-Zone Sampler ». The playback ratios are the render's: the same function serves live playing and the graph's audio, so what you hear while listening to yourself is what will come out.\n\nWhat is read from the format: regions, opcode inheritance through <global>, <master> and <group>, note names as well as numbers, default_path, sustain loops, tune, volume and transpose. What is not is stated in the node's message rather than guessed: ignored opcodes are counted and named, missing samples too, and velocity layers are kept: one key may carry three to eight recordings — piano, mezzo, forte — and the played velocity picks which one sounds.\n\nOn the keyboard, velocity comes from the striking rhythm: playing fast brings out the loud layer. An #include is reported, not followed." },
  "export-sfz": { fr: "Écrit une banque de clavier au format SFZ : un fichier texte qui décrit les régions, et les échantillons dans un dossier à côté — un WAV par zone, nommé d'après sa note-racine. SFZ se lit par presque tous les échantillonneurs (Sforzando, LinuxSampler, Bitwig, Renoise, et par conversion la plupart des autres), et c'est un format texte : on peut l'ouvrir, le relire, le corriger à la main. La couverture du clavier se reconstruit à partir des régions écrites : les quatre-vingt-huit touches y sont couvertes une fois chacune. Un SF2 serait un autre chantier : format binaire, avec ses tables et ses générateurs. Trois champs portent tout : « pitch_keycenter » dit à quelle note l'échantillon est juste, « lokey » et « hikey » bornent la zone, et l'échantillonneur en déduit la transposition — au plus la largeur de zone choisie à la construction. Quand la banque a une boucle de maintien, elle est écrite en échantillons avec « loop_mode=loop_sustain » : elle ne tourne alors que pendant que la touche est tenue, exactement comme le fait le sampler multi-zones. Les échantillons sont écrits d'abord, et le fichier SFZ seulement ensuite : si l'un d'eux échouait, un SFZ déjà écrit renverrait vers un fichier absent et l'échantillonneur se tairait sans dire pourquoi. Le composant annonce le nombre d'échantillons écrits et leur poids total. Demande Electron, comme les autres composants d'export.", en: "Writes a keyboard bank as SFZ: a text file describing the regions, and the samples in a folder beside it — one WAV per zone, named after its root note. SFZ is read by almost every sampler (Sforzando, LinuxSampler, Bitwig, Renoise, and by conversion most others), and it is a text format: it can be opened, read back, corrected by hand. That is also what makes it verifiable — the tests read back what the node writes and rebuild the keyboard coverage from the regions, to make sure all eighty-eight keys are covered exactly once. An SF2 would be another undertaking: a binary format with its tables and generators. Three fields carry everything: « pitch_keycenter » says at which note the sample is in tune, « lokey » and « hikey » bound the zone, and the sampler derives the transposition — at most the zone width chosen at build time. When the bank has a sustain loop it is written in samples with « loop_mode=loop_sustain »: it then turns only while the key is held, exactly as the multi-zone sampler does. The samples are written first and the SFZ file only afterwards: were one of them to fail, an already-written SFZ would point at a missing file and the sampler would fall silent without saying why. The node reports how many samples were written and their total size. Requires Electron, like the other export nodes." },
  "banque-clavier": { fr: "Fait d'un son une banque d'échantillons jouable sur les 88 touches. Le problème, en chiffres : un clavier de 88 touches va de La0 (27,5 Hz) à Do8 (4186 Hz), soit un rapport de 152 — sept octaves et une tierce mineure. Un échantillonneur qui rééchantillonne un seul son depuis une seule note de référence lit donc entre 0,105 et 16 fois la vitesse : un son de deux secondes dure dix-neuf secondes en bas du clavier et cent vingt-cinq millisecondes en haut, et une attaque de 5 ms devient 48 ms de bouillie en bas et 0,3 ms de clic en haut. C'est l'effet « écureuil », et aucun réglage ne le rattrape. \n\nLa méthode sépare deux transpositions qu'on confond souvent. Construire la banque : le son est transposé vers chaque racine par un procédé à durée constante, car les intervalles vont jusqu'à quatre octaves. Jouer une note : la zone la plus proche n'est rééchantillonnée que de quelques demi-tons, ce qui est juste à la hauteur par construction et ne change la durée que de 12 % à ±2. La règle des zones vient de la pratique des bibliothèques d'échantillons : ne pas rééchantillonner de plus de deux ou trois demi-tons — la « règle de la tierce mineure ». À ±2, dix-huit ou dix-neuf zones couvrent les 88 touches. Une zone est toujours le son lui-même : la grille des racines est ancrée sur la note d'origine, si bien qu'une zone au moins ne subit aucune transposition. La note d'origine se mesure plutôt que de se déclarer : le suiveur de hauteur la trouve, et elle sera juste. \n\nTrois procédés de transposition, qui ne se valent pas : durée constante (vocodeur de phase), magnétophone (rééchantillonnage, l'effet écureuil quand on le veut), et attaque préservée — le son est séparé en sinus, transitoires et bruit, seuls les deux premiers sont transposés, et les transitoires sont remis tels quels, de sorte que l'attaque ne s'étale pas et ne se met pas à claquer. Le suivi de touche raccourcit les notes vers l'aigu, comme le fait tout instrument : une corde de piano grave tient vingt secondes, une aiguë moins d'une. La boucle de maintien permet à une touche tenue de sonner au-delà de l'échantillon ; son raccord est fondu, sans quoi chaque tour laisserait un clic. La sortie aperçu joue la racine de chaque zone l'une après l'autre. Sur huit touches réparties de La0 à La7, la durée d'une note ne varie que d'un facteur inférieur à 2, là où un échantillon unique l'étalerait de 152, et la hauteur tombe à moins d'un tiers de demi-ton de la note demandée.", en: "Turns one sound into a sample bank playable across the 88 keys. The problem, in figures: an 88-key keyboard runs from A0 (27.5 Hz) to C8 (4186 Hz), a ratio of 152 — seven octaves and a minor third. A sampler that resamples a single sound from a single reference note therefore reads between 0.105 and 16 times speed: a two-second sound lasts nineteen seconds at the bottom of the keyboard and a hundred and twenty-five milliseconds at the top, and a 5 ms attack becomes 48 ms of mush at the bottom and 0.3 ms of click at the top.\n\nThat is the « chipmunk » effect, and no setting makes up for it. The solution separates two transpositions that are often confused. Building the bank: the sound is transposed to each root by a constant-duration method, since the intervals reach four octaves. Playing a note: the nearest zone is resampled by a few semitones only, which is exact in pitch by construction and changes duration by just 12 % at ±2. The zone rule comes from sample-library practice: do not resample by more than two or three semitones — the « minor third rule ».\n\nAt ±2, eighteen or nineteen zones cover the 88 keys. One zone is always the sound itself: the root grid is anchored on the source note, so at least one zone undergoes no transposition at all. The source note is measured rather than declared: the pitch follower finds it, and it will be right. Three transposition methods are offered, and they are not equals: constant duration (phase vocoder), tape (resampling, the chipmunk effect when it is wanted), and attack preserved — the sound is split into sines, transients and noise, only the first two are transposed, and the transients are put back untouched, so the attack neither smears nor turns into a click.\n\nKey tracking shortens notes toward the treble, as every instrument does: a bass piano string rings for twenty seconds, a treble one for less than one. The sustain loop lets a held key sound beyond the sample; its join is crossfaded, failing which each turn would leave a click. The preview output plays each zone's root one after the other: enough to hear the bank without connecting a keyboard. Over eight keys spread from A0 to A7, a note's duration varies by a factor below 2, where a single sample would spread it by 152, and the pitch lands within a third of a semitone of the requested note." },
  "sampler-multizones": { fr: "Joue un fichier MIDI avec une banque de clavier — celle d'« Étaler sur le clavier », celle d'une « Banque SFZ » lue du disque, ou le kit de batterie intégré. Chaque note prend la zone la plus proche et n'est rééchantillonnée que de l'écart qui l'en sépare ; le message annonce l'écart maximal rencontré, et s'il dépasse la largeur de zone, c'est que le MIDI sort du clavier couvert par la banque. Les couches de vélocité sont jouées : si la banque en a, c'est la vélocité de chaque note qui choisit l'enregistrement, et le message dit combien de couches ont été touchées sur le nombre disponible — un MIDI dont toutes les vélocités valent 100 ne réveillera jamais qu'une seule couche, et mieux vaut le voir que le deviner.\n\nAvec un kit, rien de tout cela : une touche est un son, rien n'est transposé, et une touche sans son ne joue rien — le message compte alors les notes muettes, ce qui est la seule façon de voir qu'un fichier de batterie demande des percussions que le kit n'a pas. Quatre réglages font de ce composant une piste d'orchestre, et ils sont ici parce que le mélangeur n'a aucun réglage par piste. Panoramique : place la partie dans l'espace stéréo, en loi cosinus — un son déplacé garde le même niveau perçu en passant par le centre, là où un panoramique linéaire y perd trois décibels.\n\nTransposition : décale les notes reçues, utile pour une basse écrite une octave trop haut ; sur un kit, cela change d'instrument et non de hauteur. Note basse et note haute : les notes en dehors sont ignorées et comptées, ce qui permet de partager un même MIDI entre deux banques — une basse sous le do3, un piano au-dessus — sans toucher au fichier. La plage s'applique aux notes écrites, avant la transposition : ce qu'on lit sur la partition est ce qu'on borne.\n\nLes fréquences d'échantillonnage sont alignées : une zone enregistrée à 48 kHz jouée dans une banque rendue à 44,1 sortait 147 cents trop bas — un demi-ton et demi —, ce qui arrive dès qu'une bibliothèque SFZ mélange deux fréquences. La sortie MIDI reprend les notes telles quelles, pour chaîner d'autres composants.", en: "Plays a MIDI file with a keyboard bank — the one from « Spread Across Keyboard », the one from an « SFZ Bank » read from disk, or the built-in drum kit. Each note takes its nearest zone and is resampled only by the gap between them; the message reports the maximum shift encountered, and if it exceeds the zone width, the MIDI reaches outside the keyboard the bank covers. Velocity layers are played: if the bank has any, each note's velocity picks the recording, and the message says how many layers were used out of those available — a MIDI file whose velocities are all 100 will only ever wake one layer, and better to see it than to guess.\n\nWith a kit, none of that applies: a key is a sound, nothing is transposed, and a key with no sound plays nothing — the message then counts the silent notes, which is the only way to see that a drum file asks for percussion the kit does not have. Four settings turn this node into an orchestra part, and they live here because the mixer has no per-track setting. Pan: places the part in the stereo field, with a cosine law — a moved sound keeps the same perceived level when passing through the centre, where a linear pan would lose three decibels.\n\nTranspose: shifts incoming notes, useful for a bass written an octave too high; on a kit it changes instrument rather than pitch. Lowest key and highest key: notes outside are ignored and counted, which splits one MIDI file between two banks — a bass below C3, a piano above — without touching the file. The range applies to the written notes, before transposition: what you read on the score is what you bound. Sample rates are aligned: a zone recorded at 48 kHz played in a bank rendered at 44.1 came out 147 cents flat — a semitone and a half — which happens as soon as an SFZ library mixes two rates. The MIDI output passes the notes through unchanged, for chaining other nodes." },
  "reverbe-reseau": { fr: "Une réverbération dont le temps de décroissance se règle séparément dans le grave et dans l'aigu. D'après Jean-Marc Jot et Antoine Chaigne, « Digital delay networks for designing artificial reverberators », AES Convention 90, 1991 — le réseau de retards rétroactifs et, surtout, la façon d'y contrôler explicitement le temps de réverbération ; le contrôle exact du RT60 a été repris et précisé par Sebastian J. Schlecht et Emanuël A. P. Habets, DAFx-17. Une décroissance uniforme sur tout le spectre n'est pas\n\nce qu'une salle fait : c'est exactement ce qu'une salle ne fait pas : l'air et les matériaux absorbent l'aigu bien plus vite que le grave, si bien qu'une vraie queue de réverbération s'assombrit en s'éteignant. Sans cela, une réverbération sonne comme un effet et non comme un lieu. \n\nMéthode : huit lignes à retard bouclées les unes sur les autres par une matrice de Hadamard, qui est unitaire — elle conserve l'énergie, donc le réseau ne s'éteindrait jamais de lui-même. C'est l'atténuation placée sur chaque ligne qui décide de la décroissance, et séparer ainsi la diffusion de l'absorption est l'idée de l'article : le RT60 devient réglable sans toucher au reste. Les longueurs de retard sont premières, car deux retards ayant un diviseur commun feraient coïncider leurs échos périodiquement — ce qui s'entend comme une résonance métallique. Le calcul de l'absorption est dérivé et non recopié : une ligne de m échantillons est parcourue fs/m fois par seconde, donc pour perdre 60 dB en T secondes chaque passage doit coûter 60·m/(T·fs) décibels ; un passe-bas d'ordre un sur chaque ligne suffit alors à faire dépendre ce coût de la fréquence, et ses deux coefficients se résolvent exactement. \n\nPar l'intégrale de Schroeder sur la réponse obtenue, bande par bande : pour 2,00 s demandées au grave et 0,50 s à 8 kHz, on lit 1,96 s à 125 Hz, 1,90 à 500 Hz, 1,54 à 2 kHz et 0,58 à 8 kHz ; pour 1,00 s partout, on lit 0,98, 0,98, 1,01, 0,99 et 1,00. La transition entre les deux est graduelle, comme celle d'un filtre d'ordre un, et non une marche. Le composant mesure ce qu'il produit et l'annonce, ce qui donne la salle obtenue en regard de la salle demandée.\n\nDeux précautions. La première : résoudre le filtre à Nyquist est plus simple mais rend le réglage trompeur — on lit 0,73 s à 18 kHz pour 0,50 demandée, l'exactitude tombant à une fréquence que personne n'écoute ; d'où le réglage « Fréquence de l'aigu ». La seconde : demander un aigu plus long que le grave peut être physiquement impossible, le module de la boucle dépassant alors l'unité, et la réponse atteignant 1,2 × 10¹³ au lieu de s'éteindre. Un garde-fou borne l'absorption. Avec 0,5 s au grave et 2 s à l'aigu : la queue reste plate à 0,5 s dans toutes les bandes — la borne mange l'inversion. Ce sens du réglage ne fait donc presque rien.\n\nUne sortie rend la réponse impulsionnelle elle-même, sous forme d'audio. Coût : 20 ms pour deux secondes de son à huit lignes.", en: "A reverb whose decay time is set separately for the low and the high end. After Jean-Marc Jot and Antoine Chaigne, « Digital delay networks for designing artificial reverberators », AES Convention 90, 1991 — the feedback delay network and, above all, the way to control reverberation time explicitly within it; exact RT60 control was taken up and refined by Sebastian J. Schlecht and Emanuel A. P. Habets, DAFx-17. A decay uniform across the spectrum is not what a room does.\n\nConvolution needs a response file; the others — simple, fractal, progressive, velvet — decay at one single rate everywhere. Yet that is exactly what a room does not do: air and materials absorb the high end far faster than the low, so a real reverb tail darkens as it dies. Without that, a reverb sounds like an effect rather than a place. How: eight delay lines looped into one another by a Hadamard matrix, which is unitary — it preserves energy, so the network would never die out by itself.\n\nIt is the attenuation placed on each line that decides the decay, and separating diffusion from absorption in this way is the paper's idea: RT60 becomes adjustable without touching anything else. The delay lengths are prime, since two delays sharing a divisor would make their echoes coincide periodically — heard as a metallic ringing. The absorption calculation is derived rather than copied: a line of m samples is traversed fs/m times per second, so to lose 60 dB in T seconds each pass must cost 60·m/(T·fs) decibels; a first-order lowpass on each line then suffices to make that cost frequency-dependent, and its two coefficients solve exactly.\n\nBy the Schroeder integral on the resulting response, band by band: for 2.00 s requested at the low end and 0.50 s at 8 kHz, one reads 1.96 s at 125 Hz, 1.90 at 500 Hz, 1.54 at 2 kHz and 0.58 at 8 kHz; for 1.00 s everywhere, one reads 0.98, 0.98, 1.01, 0.99 and 1.00. The transition between the two is gradual, like a first-order filter's, not a step. The node measures what it produces and announces it: enough to know whether the room requested is the room obtained, without having to measure it oneself.\n\nTwo precautions found by measuring. The first: solving the filter at Nyquist is simpler but makes the setting misleading — 0.73 s was measured at 18 kHz for 0.50 requested, exactness falling at a frequency nobody listens to; hence the « High reference » setting. The second: asking for a high end longer than the low can be physically impossible, the loop's magnitude then exceeding unity — measured, a response whose peak reached 1.2 × 10^13 instead of dying out.\n\nA safeguard now bounds the absorption. With 0.5 s at the low end and 2 s at the high: the tail stays flat at 0.5 s in every band — the bound eats the inversion. This direction of the setting therefore does almost nothing, and it was better written down than left to be hunted for by ear. One output returns the impulse response itself, to look at or to feed the convolution reverb. Cost: 20 ms for two seconds of sound at eight lines." },
  "phase-pghi": { fr: "Reconstruit un son à partir des seules magnitudes de son spectrogramme, sans itérer. D'après Zdeněk Průša, Peter Balazs et Peter L. Søndergaard, « A Noniterative Method for Reconstruction of Phase from STFT Magnitude », IEEE/ACM Transactions on Audio, Speech and Language Processing 25(5), 2017 — l'algorithme PGHI. Le Griffin-Lim itère — il projette alternativement sur les magnitudes voulues et sur l'ensemble des vrais spectrogrammes, soixante fois, en partant d'une phase tirée au hasard. C'est la méthode de 1984, et elle a deux défauts qu'aucun nombre d'itérations ne corrige : elle part de rien, et elle tombe dans un minimum local qui dépend du hasard initial — deux rendus ne donnent jamais le même son. \n\nL'idée de PGHI : la phase n'est pas indépendante de la magnitude. Pour une fenêtre gaussienne, les deux sont liées exactement — la dérivée de la phase en temps vaut la pulsation plus la dérivée du logarithme de la magnitude en fréquence, divisée par le paramètre de la fenêtre ; et la dérivée de la phase en fréquence vaut l'opposé de la dérivée du logarithme en temps, multipliée par ce même paramètre. Le gradient de la phase se lit donc sur la magnitude, qu'on connaît, et il ne reste qu'à l'intégrer. Le second geste de l'article est ce qui fait la différence avec une intégration naïve : on n'intègre pas dans un ordre arbitraire mais en partant des plus fortes magnitudes, par un tas de priorité, en s'arrêtant là où l'énergie tombe sous la tolérance. La raison est que le gradient est fiable là où il y a de l'énergie et n'a aucun sens là où il n'y en a pas : intégrer à travers une zone vide propagerait du bruit dans tout le reste. D'où le nom : intégration du gradient de phase par tas. Les régions séparées par du vide sont intégrées indépendamment — le composant annonce leur nombre sous le nom d'îlots — ce qui est sans conséquence, seules les différences de phase s'entendant. \n\nEn convergence spectrale, la mesure de l'article : sur un son harmonique, PGHI seul rend −18 dB en 30 ms, dix tours de Griffin-Lim −6 dB en 40 ms, cent tours −21 dB en 350 ms, et PGHI suivi de dix tours −26 dB en 70 ms. Autrement dit : mieux que cent tours, pour un cinquième du temps. Sa limite : sur du bruit, la relation phase-magnitude ne vaut rien, puisqu'il n'y a pas de structure à suivre : −8 dB pour PGHI contre −14 pour dix tours de Griffin-Lim. L'affinage rattrape, et c'est pourquoi le composant affine par défaut. Le composant mesure sa propre reconstruction et l'annonce en décibels.", en: "Rebuilds a sound from its spectrogram magnitudes alone, without iterating. After Zdenek Prusa, Peter Balazs and Peter L. Sondergaard, « A Noniterative Method for Reconstruction of Phase from STFT Magnitude », IEEE/ACM Transactions on Audio, Speech and Language Processing 25(5), 2017 — the PGHI algorithm. Griffin-Lim iterates — it projects alternately onto the wanted magnitudes and onto the set of true spectrograms, sixty times, starting from a randomly drawn phase.\n\nThat is the 1984 method, and it has two faults no number of iterations fixes: it starts from nothing, and it falls into a local minimum that depends on the initial randomness — two renders never give the same sound. Pghi's idea: phase is not independent of magnitude. For a gaussian window the two are linked exactly — the phase's derivative in time equals the angular frequency plus the log-magnitude's derivative in frequency divided by the window's parameter; and the phase's derivative in frequency equals minus the log-magnitude's derivative in time times that same parameter.\n\nThe phase gradient can therefore be read off the magnitude, which is known, and all that remains is to integrate it. The second move in the paper is what separates it from a naive integration: integration does not proceed in an arbitrary order but starting from the strongest magnitudes, through a priority heap, stopping where energy falls below the tolerance. The reason is that the gradient is reliable where there is energy and meaningless where there is none: integrating across an empty region would propagate noise through everything else.\n\nHence the name: phase gradient heap integration. Regions separated by emptiness are integrated independently — the node reports their number as islands — which is of no consequence, only phase differences being audible. As spectral convergence, the paper's measure: on a harmonic sound, PGHI alone gives -18 dB in 30 ms, ten Griffin-Lim passes -6 dB in 40 ms, a hundred passes -21 dB in 350 ms, and PGHI followed by ten passes -26 dB in 70 ms. In other words: better than a hundred passes, for a fifth of the time.\n\nIts limit, stated rather than left to be discovered: on noise the phase-magnitude relation is worth nothing, there being no structure to follow — measured, -8 dB for PGHI against -14 for ten Griffin-Lim passes. Refinement makes up for it, which is why the node refines by default. The node measures its own reconstruction and announces it in decibels: enough to know what the result is worth without having to listen to it." },
  "remplissage-trou": { fr: "Reconstruit un passage manquant en prolongeant la résonance du son de part et d'autre. D'après Amir Adler, Valentin Emiya, Maria G. Jafari, Michael Elad, Rémi Gribonval et Mark D. Plumbley, « Audio Inpainting », IEEE Transactions on Audio, Speech and Language Processing 20(3), 2012, qui a donné son nom au problème ; la méthode employée est celle qui reste la référence pour les trous courts, l'interpolation autorégressive de Janssen, Veldhuis et Vries (1986), revisitée en 2024 par Mokrý et Rajmic sous le nom de « Janssen 2.0 », qui confirme qu'elle tient encore devant les méthodes parcimonieuses et neuronales sur les trous de quelques dizaines de millisecondes. Le trou visé dure de quelques millisecondes à une centaine — un décrochage réseau, une rayure, un blanc à faire disparaître — et se désigne par une zone.\n\nPrincipe : on suppose le son autorégressif, c'est-à-dire que chaque échantillon est à peu près une combinaison linéaire des précédents. C'est ce que fait un instrument, dont la matière impose une résonance. Le problème se mord la queue, puisqu'il faudrait le son pour estimer le modèle et le modèle pour refaire le son ; Janssen tourne la difficulté en alternant : on estime le modèle sur le son courant, trou bouché tant bien que mal, puis on recalcule le trou qui minimise l'erreur de prédiction de ce modèle, et on recommence. Chaque tour améliore les deux, et le calcul s'arrête dès que le trou ne bouge plus.\n\nCe qui fonde la méthode sur une note tenue : une sinusoïde est un processus autorégressif d'ordre deux, exactement — x[n] = 2·cos(ω)·x[n−1] − x[n−2] —, si bien qu'un modèle d'ordre trente porte quinze partielles sans aucune approximation, phases comprises.\n\nAu rapport signal sur distorsion calculé sur le trou seulement, contre une interpolation linéaire : sur un trou de 2 ms, 12 dB pour la ligne droite contre 59 dB ; à 5 ms, −4 contre 65 ; à 10 ms, −3 contre 62 ; à 20 ms, −3 contre 53 ; à 50 ms, −6 contre 41 ; à 100 ms, −6 contre 34. La méthode ne perd donc pas sa supériorité en s'allongeant, elle perd seulement de la précision.\n\nLe coût, en revanche, croît comme la longueur du trou multipliée par le carré de l'ordre : 90 ms de calcul pour un trou de 20 ms, deux secondes et demie pour un trou de 100 ms — d'où le réglage « Trou max », qui laisse les trous démesurés tels quels et le dit. Sur du bruit, il n'y a rien à prédire et la reconstruction ne peut pas être juste ; ce qui est garanti est qu'elle ne diverge pas et reste dans les amplitudes du son. Rien n'est touché en dehors des trous.", en: "Rebuilds a missing passage by continuing the sound's own resonance from both sides. After Amir Adler, Valentin Emiya, Maria G. Jafari, Michael Elad, Remi Gribonval and Mark D. Plumbley, « Audio Inpainting », IEEE Transactions on Audio, Speech and Language Processing 20(3), 2012, which gave the problem its name; the method used is the one that remains the reference for short gaps, the autoregressive interpolation of Janssen, Veldhuis and Vries (1986), revisited in 2024 by Mokry and Rajmic as « Janssen 2.0 », which confirms it still stands up to sparse and neural methods on gaps of a few tens of milliseconds.\n\nThe gap aimed at runs from a few milliseconds to a hundred — a network dropout, a scratch, a blank to make disappear. Yet the Multi-Zone Selector is already there to point at the passage: select it, and the node rebuilds it. The idea: the sound is assumed autoregressive, that is, each sample is roughly a linear combination of the preceding ones. This is not a fancy — it is what an instrument does, its material imposing a resonance. The problem bites its own tail, since the sound would be needed to estimate the model and the model to remake the sound; Janssen sidesteps this by alternating: estimate the model on the current sound, gap filled as best one can, then recompute the gap that minimises this model's prediction error, and start again.\n\nEach pass improves both, and computation stops as soon as the gap stops moving. Why it works so well on a note: a sine is exactly a second-order autoregressive process — x[n] = 2·cos(w)·x[n-1] - x[n-2] — so an order of thirty carries fifteen partials with no approximation at all, phases included. As signal-to-distortion ratio computed on the gap only, against a linear interpolation: on a 2 ms gap, 12 dB for the straight line against 59 dB; at 5 ms, -4 against 65; at 10 ms, -3 against 62; at 20 ms, -3 against 53; at 50 ms, -6 against 41; at 100 ms, -6 against 34.\n\nThe method therefore does not lose its superiority as gaps grow, it only loses precision. The cost, on the other hand, grows as gap length times the square of the order: 90 ms of computation for a 20 ms gap, two and a half seconds for a 100 ms one — hence the « Max gap » setting, which leaves oversized gaps as they are and says so. On noise there is nothing to predict and the reconstruction cannot be right; what is guaranteed is that it does not diverge and stays within the sound's amplitudes. Nothing outside the gaps is touched." },
  "restauration-ecretage": { fr: "Reconstruit les sommets coupés d'un son écrêté. D'après Srđan Kitić, Nancy Bertin et Rémi Gribonval, « Sparsity and cosparsity for audio declipping: a flexible non-convex approach », LVA/ICA 2015 — l'algorithme a-spade ; les mesures suivent le panorama de Pavel Záviška, Pavel Rajmic, Alexey Ozerov et Lucas Rencker, IEEE/ACM TASLP 2021. Baisser le niveau d'un son écrêté ne donne qu'un son écrêté plus bas : l'écrêtage se répare, il ne s'atténue pas.\n\nPrincipe : un échantillon écrêté n'est pas inconnu. On sait qu'il valait au moins le seuil, et on sait que ses voisins non écrêtés sont justes. Le problème est donc un problème inverse sous contraintes — trouver un signal qui laisse les échantillons fiables tels quels, dépasse le seuil là où ça écrêtait, et soit parcimonieux en temps-fréquence, c'est-à-dire ressemble à un son. Sans cette troisième condition, il y aurait une infinité de solutions.\n\nMéthode : on alterne deux gestes — rendre le spectre parcimonieux en ne gardant que les plus fortes raies, puis remettre le signal dans ses contraintes. Aucun des deux ne suffit seul, le premier abîmant les contraintes et le second la parcimonie. La parcimonie démarre serrée et se desserre d'une raie par tour : on cherche d'abord l'explication la plus simple.\n\nPortée, au rapport signal sur distorsion calculé sur les échantillons écrêtés seulement, la mesure du panorama : 8 % d'échantillons coupés donnent +7,5 dB, 14 % +13,5 dB, 24 % +16,8 dB, 41 % +15,3 dB, puis 57 % ne donnent plus que +2,7 dB. Le gain culmine vers un quart d'échantillons coupés et s'effondre au-delà de la moitié : ce qui tient le signal, ce sont les échantillons fiables, et quand ils deviennent minoritaires, il n'y a plus assez de contraintes pour désigner une solution. Itérer davantage ne rattrape rien.\n\nDeux propriétés tenues quoi qu'il arrive, parce que les contraintes sont réimposées après recollement des trames : un échantillon qui n'était pas écrêté ressort exactement ce qu'il était, et un échantillon écrêté ressort toujours au-dessus du seuil. Le son réparé dépasse donc le seuil qui le bornait — c'est le but — et peut sortir de la plage [−1, 1] : la crête est annoncée dans le message, et une normalisation en aval la ramène dans la plage.\n\nSur deux sons de même crête écrêtés à divers seuils, au rapport signal sur distorsion calculé sur les échantillons écrêtés seulement. Sur un son à cinq harmoniques : +25 dB au seuil 0,8, +14 dB à 0,6, +13 dB à 0,5, +3 à +5 dB en dessous. Sur une dent de scie à cent harmoniques : +2 dB à 0,8, mais −10 dB à 0,6 et −5 dB à 0,5, puis de nouveau +1 à +6 dB plus bas. La méthode est fiable sur un son parcimonieux et erratique sur un son dense. La raison n'est pas la densité d'énergie — une dent de scie concentre la sienne dans ses premières raies et passe pour parcimonieuse à toutes les mesures d'énergie essayées. C'est que la reconstruction a un plancher propre à chaque son : refaire l'angle d'une dent de scie à partir de quelques dizaines de raies demande des phases exactes, et le modèle n'y arrive pas. Quand le dégât de l'écrêtage est plus léger que ce plancher, réparer abîme. C'est cohérent avec la littérature, qui rapporte des gains moyens sur des corpus de musique et non une garantie par signal : le résultat se compare à l'original.\n\nDeux garde-fous qui ne sont pas dans l'article : un plafond sur les échantillons reconstruits, parce que l'erreur d'un modèle qui n'explique rien se réfugie dans les échantillons libres — sans lui, la crête atteint trois fois le seuil ; et le résidu, annoncé dans le message, qui est la seule chose que le composant sache dire sur la qualité de sa propre réparation, n'ayant pas l'original pour se comparer. Haut, le modèle n'a pas rendu compte du son.", en: "Rebuilds the clipped peaks of a saturated sound. After Srdan Kitic, Nancy Bertin and Remi Gribonval, « Sparsity and cosparsity for audio declipping: a flexible non-convex approach », LVA/ICA 2015 — the a-spade algorithm; the measurements follow the overview by Pavel Zaviska, Pavel Rajmic, Alexey Ozerov and Lucas Rencker, IEEE/ACM TASLP 2021. Other nodes remove clicks, reduce noise, dereverberate; none repaired a clipped sound — the Normalizer only changes gain, and turning a clipped sound down merely gives a quieter clipped sound.\n\nYet clipping is the commonest fault of amateur recordings, and it can be produced here too: « Loop End C » goes past 1 as soon as three passes of the same sound are stacked. The idea: a clipped sample is not unknown. We know it was at least the threshold, and we know its unclipped neighbours are right. So this is an inverse problem under constraints — find a signal that leaves the reliable samples as they are, goes above the threshold where it clipped, and is sparse in time-frequency, that is, sounds like a sound.\n\nWithout that third condition there would be infinitely many solutions, each uglier than the last. How: two gestures alternate — make the spectrum sparse by keeping only the strongest lines, then put the signal back inside its constraints. Neither suffices alone, the first spoiling the constraints and the second the sparsity. Sparsity starts tight and loosens by one line per pass: the simplest explanation is tried first. What it gives, and where it stops — measured as signal-to-distortion ratio computed on the clipped samples only, the overview's measure: 8 % of samples cut gives +7.5 dB, 14 % +13.5 dB, 24 % +16.8 dB, 41 % +15.3 dB, then 57 % gives only +2.7 dB.\n\nThe gain peaks around a quarter of samples cut and collapses beyond half: what holds the signal is the reliable samples, and once they are in the minority there are no longer enough constraints to single out a solution. Iterating more does not make up for it. Two promises kept whatever happens, because the constraints are reimposed after the frames are joined: a sample that was not clipped comes out exactly as it was, and a clipped sample always comes out above the threshold.\n\nThe repaired sound therefore exceeds the threshold that bounded it — that is the point — and may leave the [-1, 1] range: the peak is announced in the message, and a Normalizer downstream sets that right. What it gives, and where it stops — measured on two sounds of equal peak clipped at various thresholds, as signal-to-distortion ratio computed on the clipped samples only. On a five-harmonic sound: +25 dB at threshold 0.8, +14 dB at 0.6, +13 dB at 0.5, +3 to +5 dB below.\n\nOn a hundred-harmonic sawtooth: +2 dB at 0.8, but -10 dB at 0.6 and -5 dB at 0.5, then +1 to +6 dB again lower down. The method is reliable on a sparse sound and erratic on a dense one. The reason is not energy density — a sawtooth concentrates its own in its first lines and passes for sparse on every energy measure tried. It is that reconstruction has a floor specific to each sound: rebuilding a sawtooth's corner from a few dozen lines takes exact phases, and the model cannot manage it.\n\nWhen the clipping damage is milder than that floor, repairing harms. This is consistent with the literature, which reports average gains over music corpora rather than a per-signal guarantee: compare with the original before keeping the result. Two safeguards that are not in the paper, and are stated as such: a ceiling on reconstructed samples, because the error of a model that explains nothing takes refuge in the free samples — without it the peak ran to three times the threshold; and the residual, announced in the message, which is the only thing the node can say about the quality of its own repair, having no original to compare against. High, the model did not account for the sound." },
  "retard-spectral": { fr: "Retarde le grave plus que l'aigu — ou l'inverse — sans rien couper. D'après Vesa Välimäki, Jonathan S. Abel et Julius O. Smith III, « Spectral Delay Filters », Journal of the Audio Engineering Society 57(7-8), 2009, p. 521-531 ; la réaction et les coefficients variables viennent de Jussi Pekonen et Vesa Välimäki, « Spectral Delay Filters with Feedback and Time-Varying Coefficients », DAFx-09. Un délai ordinaire retarde tout le signal du même temps : il fait varier le montant, jamais sa répartition dans le spectre. Ici le grave peut arriver quatre-vingts millisecondes après l'aigu, et pourtant rien n'est filtré : le son n'est pas coupé, il est étalé.\n\nMéthode : un passe-tout du premier ordre ne change aucune amplitude — d'où son nom — mais retarde chaque fréquence d'un temps différent, donné par τ(ω) = (1 − a²)/(1 + 2a·cos ω + a²) échantillons. Une section ne fait presque rien ; on en met deux cents, et les retards s'additionnent.\n\nÀ 44,1 kHz avec deux cents sections et une dispersion de 0,9 : 85,5 ms de retard à 100 Hz, 73,5 ms à 300 Hz, 30,5 ms à 1 kHz, 2,9 ms à 4 kHz et 0,6 ms à 10 kHz — la théorie annonçait 84,6, 74,0, 30,5, 2,9 et 0,6. Le sens ne demande rien d'autre que le signe du coefficient : la formule échange ses deux bouts avec lui. Les deux sens ne se valent pas : le retard se concentre dans une bosse étroite en fréquence, placée au grave ou à Nyquist selon le signe. Au grave, cette bosse couvre plusieurs octaves audibles — 86 ms à 100 Hz, encore 30 ms à 1 kHz. À l'aigu, elle se loge dans la dernière fraction d'octave sous Nyquist, là où il n'y a presque rien à retarder : 0,3 ms à 10 kHz, 1,4 ms à 16 kHz. « Aigu retardé » est donc un effet discret par nature. C'est aussi pourquoi le message du composant annonce le retard à 100 Hz et à 10 kHz, et non aux deux bouts mathématiques du spectre : annoncer « 86 ms » côté aigu ferait attendre un effet que l'oreille n'entendra pas. La réaction renvoie la sortie dans la cascade, ce qui donne une suite d'échos dont chacun est plus dispersé que le précédent : le premier est encore un son, le dixième une traînée. La modulation est le second article : la dispersion devient elle-même un geste, pilotée par une courbe — un suiveur de caractéristique, une suite logistique, une rampe. Sans courbe branchée, le composant rend exactement ce que rend le réglage : il n'y a qu'un seul chemin de calcul. La traîne max borne la sortie : la traîne croît comme (1+a)/(1−a), donc sans limite quand la dispersion approche un — à 0,999 et quatre cents sections elle vaut dix-huit secondes, que le rebouclage répète encore, et le rendu deviendrait interminable. La sortie est plus longue que l'entrée : la traîne du bout lent sort après la fin du son.", en: "Delays the low end more than the high end — or the other way round — without cutting anything. After Vesa Valimaki, Jonathan S. Abel and Julius O. Smith III, « Spectral Delay Filters », Journal of the Audio Engineering Society 57(7-8), 2009, pp. 521-531; feedback and time-varying coefficients come from Jussi Pekonen and Vesa Valimaki, « Spectral Delay Filters with Feedback and Time-Varying Coefficients », DAFx-09. An ordinary delay shifts the whole signal by the same time.\n\nFlanger, phaser, echo, stereo delay all delay the whole signal by the same amount — they vary the amount, never its distribution across the spectrum. Here the low end can arrive eighty milliseconds after the high end, and yet nothing is filtered: the sound is not cut, it is spread out. How: a first-order allpass changes no amplitude — hence its name — but delays each frequency by a different time, given by tau(w) = (1 - a^2)/(1 + 2a·cos w + a^2) samples.\n\nOne section does almost nothing; put two hundred of them and the delays add up. At 44.1 kHz with two hundred sections and a dispersion of 0.9: 85.5 ms of delay at 100 Hz, 73.5 ms at 300 Hz, 30.5 ms at 1 kHz, 2.9 ms at 4 kHz and 0.6 ms at 10 kHz — theory predicted 84.6, 74.0, 30.5, 2.9 and 0.6. The direction needs nothing but the sign of the coefficient: the formula swaps its two ends along with it. The two directions are not equals, and a measurement showed it rather than a reading: the delay gathers in a bump that is narrow in frequency, placed at the low end or at Nyquist depending on the sign.\n\nAt the low end that bump spans several audible octaves — 86 ms at 100 Hz, still 30 ms at 1 kHz. At the high end it sits in the last fraction of an octave below Nyquist, where there is almost nothing left to delay: 0.3 ms at 10 kHz, 1.4 ms at 16 kHz. « High end delayed » is therefore a subtle effect by nature. It is also why the node's message reports the delay at 100 Hz and at 10 kHz rather than at the two mathematical ends of the spectrum: announcing « 86 ms » on the high side would promise an effect the ear will not hear.\n\nFeedback returns the output into the cascade, giving a series of echoes each more dispersed than the last: the first is still a sound, the tenth a streak. Modulation is the second paper: dispersion itself becomes a gesture, driven by a curve — a feature follower, a logistic sequence, a ramp. With no curve connected, the node returns exactly what the setting gives: there is only one computation path. Max tail is not a comfort setting: the tail grows as (1+a)/(1-a), hence without bound as dispersion approaches one — at 0.999 and four hundred sections it is eighteen seconds, which feedback repeats again, and rendering would become endless. The output is longer than the input, and that is intended: the slow end's tail comes out after the sound has finished." },
  "stn-sinus-transitoires-bruit": { fr: "Sépare un son en trois matières — ce qui tient, ce qui claque, ce qui souffle — et ne perd rien en route. D'après Leonardo Fierro et Vesa Välimäki, « Enhanced Fuzzy Decomposition of Sound Into Sines, Transients, and Noise », Journal of the Audio Engineering Society 71(7-8), 2023, p. 468-480 ; la décomposition en trois remonte à Scott Levine et Julius O. Smith III (AES 1998), et le filtrage médian qui la rend si simple à Derry Fitzgerald (DAFx-10). Une séparation en deux range les transitoires avec le percussif ou avec le bruit. Or l'attaque est ce qui fait reconnaître un instrument, et c'est la matière qu'on veut traiter à part : allonger un son sans étaler ses attaques, adoucir une percussion sans éteindre sa queue, rendre un souffle sans désaccorder ce qui le porte. \n\nDeux fenêtres : une partielle ne se voit que sur une fenêtre longue — il faut du temps pour constater qu'une fréquence dure — et une attaque que sur une fenêtre courte, car sur une longue elle est déjà diluée dans les dizaines de millisecondes qui l'entourent. Une seule analyse ne peut donc pas faire les deux : on retire d'abord ce qui tient, puis on cherche ce qui claque dans ce qui reste. L'ordre n'est pas interchangeable — l'inverse prendrait pour attaque le début de chaque note tenue. \n\nLe flou est l'apport de l'article : un point du spectrogramme n'est pas forcément sinusoïdal OU bruité, il peut être des deux, et le masque passe de zéro à un par une rampe en cosinus surélevé plutôt que par une marche — ce qui évite les clics aux points qui traversent la borne. La reconstruction est parfaite : les trois masques somment à un en chaque point, si bien que les trois sorties additionnées redonnent le son de départ, échantillon pour échantillon, à 6,4e-8 près, soit l'arrondi du calcul. C'est ce qui permet de ne retoucher qu'une matière et de réassembler sans que la somme trahisse le découpage.\n\nSur un même son auquel on ajoute des attaques, la voie des transitoires gonfle de dix-neuf fois pendant que celle des sinus ne bouge pas (×1,00) ; en ajoutant du souffle, la voie du bruit gonfle de trente-six fois, les sinus toujours pas.\n\nLa méthode ne suit aucune partielle dans le temps : elle coupe en trois par la texture, et coûte trois dixièmes de seconde pour deux secondes de son.", en: "Splits a sound into three materials — what sustains, what strikes, what breathes — and loses nothing on the way. After Leonardo Fierro and Vesa Valimaki, « Enhanced Fuzzy Decomposition of Sound Into Sines, Transients, and Noise », Journal of the Audio Engineering Society 71(7-8), 2023, pp. 468-480; the three-way decomposition goes back to Scott Levine and Julius O. Smith III (AES 1998), and the median filtering that makes it so simple to Derry Fitzgerald (DAFx-10).\n\nTwo splits in two already existed — harmonic/percussive by median filtering, and SMS into deterministic plus stochastic — but neither isolates transients: harmonic/percussive separation files them with the percussive part, SMS with the noise. Yet the attack is what makes an instrument recognisable, and it is the material one wants to treat on its own: stretching a sound without smearing its attacks, softening a percussion without killing its tail, bringing out breath without detuning what carries it.\n\nTwo Windows, and that is the whole problem: a partial only shows on a long window — it takes time to establish that a frequency lasts — and an attack only on a short one, since in a long window it is already diluted into the tens of milliseconds around it. A single analysis therefore cannot do both: first remove what sustains, then look for what strikes in what remains. The order cannot be swapped — the other way round would take the beginning of every sustained note for an attack.\n\nThe fuzziness is the paper's contribution: a spectrogram point is not necessarily sinusoidal OR noisy, it can be both, and the mask goes from zero to one along a raised-cosine ramp rather than a step — which avoids clicks on points crossing the boundary. Reconstruction is perfect: the three masks sum to one at every point, so the three outputs added together give back the original sound, sample for sample (measured: 6.4e-8 maximum deviation, that is floating-point rounding and nothing else).\n\nThis is not an elegance, it is what allows one material to be reworked and the whole reassembled without the sum betraying the split. On one and the same sound with attacks added, the transient path swells nineteenfold while the sine path does not move (x1.00); adding breath, the noise path swells thirty-sixfold, the sines still unmoved. How this node differs from SMS: SMS tracks each partial through time, which lets one transpose it without touching the breath; it is slower and says nothing about attacks. STN tracks nothing, cuts in three by texture, and costs three tenths of a second for two seconds of sound." },
  "sms-sinusoides-bruit": { fr: "Suit les partiels d'un son, et met tout le reste a part. D'apres Xavier Serra et Julius O. Smith III, « Spectral Modeling Synthesis: A Sound Analysis/Synthesis System Based on a Deterministic plus Stochastic Decomposition », Computer Music Journal 14(4), 1990 ; le suivi de partiels et la resynthese additive reprennent Robert McAulay et Thomas Quatieri, IEEE Transactions on Acoustics, Speech and Signal Processing 34(4), 1986. L'idee : un son se compose d'une partie deterministe — des partiels, chacun avec sa frequence et son amplitude qui evoluent — et d'une partie stochastique, le reste : le souffle d'une flute, l'archet d'un violon, le bruit d'attaque d'un piano.\n\nLes separer permet de les transformer separement, et c'est la tout l'interet : transposer les partiels sans toucher au souffle, rendre un instrument plus souffle sans le desaccorder d'un centieme de ton, oter le bruit sans ternir l'harmonie. Aucun vocodeur de phase ne le permet, parce qu'il ne sait pas ce qu'est un partiel — il ne connait que des bins. Trois choses valent d'etre connues. La frequence de chaque pic est affinee par interpolation parabolique entre les bins : sans cela la resolution serait de vingt et un hertz a 2048 points, et un la 440 se lirait a 431 ou 452 — la transposition serait fausse.\n\nLa saillie est ce qui separe un partiel d'une bosse de bruit, et il en faut un critere : la persistance ne suffit pas, deux trames voisines partageant les trois quarts de leurs echantillons, si bien qu'une bosse de bruit « persiste » elle aussi — mesure avant ce critere, 55 % d'un bruit blanc passait pour deterministe. Enfin, deux voies de resynthese coexistent et ne servent pas a la meme chose : sans transposition, les partiels sont decoupes dans le son lui-meme par masques complementaires, si bien que partiels plus residu redonnent l'original echantillon pour echantillon — c'est teste ; des qu'on transpose, ils sont refaits par addition d'oscillateurs dont la phase est integree plutot que reprise, et recales sur l'energie de ceux qu'ils remplacent. Le residu, lui, n'est jamais refabrique : il est garde tel quel.", en: "Tracks a sound's partials, and sets all the rest aside. After Xavier Serra and Julius O. Smith III, « Spectral Modeling Synthesis: A Sound Analysis/Synthesis System Based on a Deterministic plus Stochastic Decomposition », Computer Music Journal 14(4), 1990; the partial tracking and additive resynthesis follow Robert McAulay and Thomas Quatieri, IEEE Transactions on Acoustics, Speech and Signal Processing 34(4), 1986. The idea: a sound consists of a deterministic part — partials, each with its own evolving frequency and amplitude — and a stochastic part, the rest: a flute's breath, a violin's bow, a piano's attack noise.\n\nSeparating them allows transforming them separately, and that is the whole point: transposing the partials without touching the breath, making an instrument breathier without detuning it by a hundredth of a tone, removing the noise without dulling the harmony. No phase vocoder allows this, because it does not know what a partial is — it only knows bins. Three things are worth knowing. Each peak's frequency is refined by parabolic interpolation between bins: without it the resolution would be twenty-one hertz at 2048 points, and an A 440 would read as 431 or 452 — the transposition would be wrong.\n\nProminence is what separates a partial from a noise bump, and such a criterion is needed: persistence does not suffice, since neighbouring frames share three quarters of their samples, so a noise bump « persists » too — measured before this criterion, 55 % of white noise passed for deterministic. Finally, two resynthesis paths coexist and do not serve the same purpose: without transposition the partials are cut out of the sound itself by complementary masks, so that partials plus residual give back the original sample for sample — this is tested; as soon as one transposes, they are rebuilt by adding oscillators whose phase is integrated rather than restarted, and rescaled onto the energy of those they replace. The residual is never rebuilt: it is kept as it is." },
  "reverberation-velours": { fr: "Reverberation tardive dont la queue prend la forme qu'on veut. D'apres Vesa Valimaki, Bo Holm-Rasmussen, Benoit Alary et Heidi-Maria Lehtonen, « Late Reverberation Synthesis Using Filtered Velvet Noise », 2017 ; et pour la decroissance quelconque, Jon Fagerstrom, Nils Meyer-Kahlen, Sebastian J. Schlecht et Vesa Valimaki, « Dark Velvet Noise », DAFx-22, puis « Non-Exponential Reverberation Modeling Using Dark Velvet Noise », 2024. Le bruit de velours est un bruit epars : une impulsion de plus ou moins un par intervalle regulier, placee au hasard dans cet intervalle, et rien entre elles.\n\nA mille cinq cents impulsions par seconde, l'oreille n'entend plus les impulsions separees mais une nappe — et une nappe plus lisse que celle d'un bruit gaussien de meme densite, parce qu'aucune impulsion n'est plus forte qu'une autre. C'est ce qui en fait une bonne reverberation tardive, et c'est aussi pourquoi baisser la densite sous le millier devient un effet en soi : on entend alors les impulsions une a une. Ce que ce composant ajoute aux quatre reverberations deja presentes tient en un mot : la queue n'a pas a etre une exponentielle.\n\nLa convolution demande un fichier de reponse impulsionnelle ; les trois autres decroissent exponentiellement, parce que c'est ce que fait une salle. Ici la decroissance est une courbe qu'on choisit. Exponentielle comme une salle. Lineaire, qui descend en ligne droite — aucune salle ne le fait. En gonflement, ou le son enfle et s'arrete net, ce qu'on n'obtient autrement qu'en retournant un enregistrement. Ou a deux pentes, signature des salles couplees : une eglise et sa chapelle, une scene et sa cage, ou la petite salle s'eteint vite et la grande prend le relais.\n\nL'assombrissement, lui, fait mourir les aigus avant les graves, comme toute salle : sans lui la queue reste brillante et s'entend comme une nappe de bruit collee au son plutot que comme un espace. La sortie Reponse rend la reponse impulsionnelle elle-meme, sous forme d'audio. Enfin, sur le calcul et pour etre exact : l'article vante une convolution sans multiplication, les impulsions valant plus ou moins un, ce qui est decisif en temps reel. Ici le traitement est hors ligne et la convolution passe par une transformee de Fourier, plus rapide encore a cette longueur. Ce qu'on garde du velours n'est donc pas son economie mais sa texture et la liberte de sa decroissance.", en: "Late reverberation whose tail takes whatever shape one wants. After Vesa Valimaki, Bo Holm-Rasmussen, Benoit Alary and Heidi-Maria Lehtonen, « Late Reverberation Synthesis Using Filtered Velvet Noise », 2017; and for the arbitrary decay, Jon Fagerstrom, Nils Meyer-Kahlen, Sebastian J. Schlecht and Vesa Valimaki, « Dark Velvet Noise », DAFx-22, then « Non-Exponential Reverberation Modeling Using Dark Velvet Noise », 2024. Velvet noise is a sparse noise: one plus-or-minus-one impulse per regular interval, placed at random within that interval, and nothing in between.\n\nAt fifteen hundred impulses per second the ear no longer hears separate impulses but a wash — and a smoother wash than a Gaussian noise of the same density, because no impulse is louder than another. That is what makes it a good late reverberation, and also why lowering the density below a thousand becomes an effect in itself: the impulses are then heard one by one. What this node adds to the four reverbs already present fits in one phrase: the tail need not be an exponential.\n\nConvolution requires an impulse response file; the other three decay exponentially, because that is what a room does. Here the decay is a curve one chooses. Exponential like a room. Linear, falling in a straight line — no room does that. Swelling, where the sound grows and stops dead, otherwise obtainable only by reversing a recording. Or two-sloped, the signature of coupled rooms: a church and its chapel, a stage and its tower, where the small room dies fast and the large one takes over.\n\nDarkening makes the treble die before the bass, as every room does: without it the tail stays bright and sounds like a noise wash glued onto the sound rather than a space. The Impulse response output returns the response itself, as audio. Finally, on computation and to be exact: the paper praises a convolution without multiplication, the impulses being plus or minus one, which is decisive in real time. Here the processing is offline and the convolution goes through a Fourier transform, faster still at this length. What is kept from velvet is therefore not its thrift but its texture and the freedom of its decay." },
  "suiveur-caracteristique": { fr: "Extrait une caracteristique d'un son pour en piloter un effet. D'apres Vincent Verfaille, Udo Zolzer et Daniel Arfib, « Adaptive Digital Audio Effects (A-DAFx): A New Class of Sound Transformations », IEEE Transactions on Audio, Speech and Language Processing 14(5), 2006, et « Implementation Strategies for Adaptive Digital Audio Effects », DAFx-02. L'idee de ces auteurs est qu'un effet devient autre chose quand son reglage cesse d'etre un nombre fixe pour devenir une caracteristique du son lui-meme : la brillance qui ouvre son propre filtre, l'energie qui allonge son propre delai.\n\nLes quatre caracteristiques disent des choses differentes et ne se remplacent pas. L'energie suit le geste de l'interprete, et c'est la plus immediate. La brillance — le centre de gravite du spectre — suit le timbre : elle monte quand le son devient dur, meme a volume constant. La platitude distingue une note d'un bruit, zero pour une sinusoide et un pour du bruit blanc : elle sert a traiter autrement le souffle et les notes. La variation marque les attaques et retombe pendant les tenues.\n\nL'inertie : sans elle, une courbe d'energie fait sauter le parametre a chaque attaque, et le resultat cliquette. Le lissage se fait en aller-retour, jamais a sens unique — un lissage a sens unique retarderait la courbe par rapport au son qui l'a produite, et le filtre s'ouvrirait apres la note au lieu de s'ouvrir avec elle. Le composant rend aussi l'audio tel quel, de sorte qu'il s'insere dans une chaine sans la couper. Une courbe porte toujours des valeurs entre zero et un : c'est le consommateur qui decide de ce que zero et un veulent dire chez lui, par ses reglages « Modulation min » et « Modulation max ».", en: "Extracts a feature from a sound to drive an effect with it. After Vincent Verfaille, Udo Zolzer and Daniel Arfib, « Adaptive Digital Audio Effects (A-DAFx): A New Class of Sound Transformations », IEEE Transactions on Audio, Speech and Language Processing 14(5), 2006, and « Implementation Strategies for Adaptive Digital Audio Effects », DAFx-02. Their idea is that an effect becomes something else when its setting stops being a fixed number and becomes a feature of the sound itself: brightness opening its own filter, energy lengthening its own delay.\n\nThe four features say different things and do not replace one another. Energy follows the player's gesture, and is the most immediate. Brightness — the spectrum's centre of gravity — follows timbre: it rises as the sound gets harsh, even at constant volume. Flatness tells a note from a noise, zero for a sine and one for white noise: it serves to treat breath and notes differently. Flux marks attacks and falls back during sustains. Inertia: without it, an energy curve makes the parameter jump at every attack and the result chatters.\n\nThe smoothing runs forwards then backwards, never one way only — a one-way smoothing would delay the curve relative to the sound that produced it, and the filter would open after the note instead of with it. The node also passes the audio through unchanged, so it slots into a chain without cutting it. A curve always carries values between zero and one: the consumer decides what zero and one mean at its end, through its « Modulation min » and « Modulation max » settings." },
  "suiveur-hauteur": { fr: "Suit la hauteur d'un son instant par instant, et la rend comme une courbe de modulation. D'après Alain de Cheveigné et Hideki Kawahara, « YIN, a fundamental frequency estimator for speech and music », Journal of the Acoustical Society of America 111(4), 2002 ; et Matthias Mauch et Simon Dixon, « pYIN: a fundamental frequency estimator using probabilistic threshold distributions », ICASSP 2014. C'est la caractéristique qui manquait au Suiveur de caractéristique, et ce n'est pas une de plus : l'article de Verfaille sur les effets adaptatifs cite la hauteur en premier parmi les caractéristiques qui pilotent, et c'est elle qui donne les effets qu'on cite toujours — un filtre qui suit la mélodie, un délai accordé sur la note jouée.\n\nMéthode : YIN cherche de combien il faut décaler le son pour qu'il se ressemble le plus — cette durée est la période, et son inverse la hauteur. Sa trouvaille est la normalisation par la moyenne cumulée : sans elle, un son se ressemble tout autant décalé de deux périodes, et rien ne départage une note de son octave. Pourquoi deux décodages : YIN rend une seule estimation par trame, et sur une trame où le fondamental faiblit c'est celle de l'octave — la courbe saute, et aucun lissage ne la répare puisque la valeur juste n'a jamais été produite. pYIN garde plusieurs candidats pondérés par une loi a priori sur le seuil, puis choisit le chemin le plus probable sur tout le son : une trame ambiguë est tranchée par ses voisines.\n\nSur une note tenue coupée de deux passages faibles : 17 trames fautives sur 119 avec YIN, aucune avec pYIN. Le réglage laisse les deux pour qu'on l'entende plutôt que de le croire. La hauteur continue pendant les silences au lieu de retomber à zéro — le chemin passe par l'état « non voisé » de la hauteur où il était —, si bien qu'un effet piloté par la mélodie traverse un silence sans se refermer d'un coup ; c'est la sortie confiance qui dit où rien n'était joué, et on peut s'en servir pour ne laisser agir un effet que sur les notes.\n\nL'échelle de la courbe est logarithmique entre « Hauteur min » et « Hauteur max » : une octave vaut le même intervalle où qu'elle se trouve. Le coût tient en une transformée par trame : environ 112 ms de calcul par seconde de son à la cadence par défaut.", en: "Follows a sound's pitch instant by instant and returns it as a modulation curve. After Alain de Cheveigné and Hideki Kawahara, « YIN, a fundamental frequency estimator for speech and music », Journal of the Acoustical Society of America 111(4), 2002; and Matthias Mauch and Simon Dixon, « pYIN: a fundamental frequency estimator using probabilistic threshold distributions », ICASSP 2014. This is the feature the Feature Follower was missing, and it is not just one more: Verfaille's paper on adaptive effects cites pitch first among the features that drive, and it is the one that yields the effects everyone quotes — a filter following the melody, a delay tuned to the note being played.\n\nMethod: YIN looks for how far the sound must be shifted to resemble itself most — that duration is the period, and its inverse the pitch. Its finding is the cumulative-mean normalisation: without it a sound resembles itself just as much shifted by two periods, and nothing tells a note from its octave. Why two decodings: YIN returns a single estimate per frame, and on a frame where the fundamental weakens that estimate is the octave — the curve jumps, and no smoothing repairs it since the right value was never produced. pYIN keeps several candidates weighted by a prior distribution over the threshold, then picks the most likely path over the whole sound: an ambiguous frame is settled by its neighbours.\n\nOn a held note broken by two weak passages: 17 faulty frames out of 119 with YIN, none with pYIN. The setting keeps both so that it can be heard rather than believed. The pitch continues through silences instead of dropping to zero — the path goes through the « unvoiced » state of the pitch it was on — so an effect driven by the melody crosses a silence without slamming shut; it is the confidence output that says where nothing was played, and it can be used to let an effect act on notes only.\n\nThe curve's scale is logarithmic between « Lowest pitch » and « Highest pitch »: an octave is worth the same interval wherever it falls. The cost is one transform per frame: about 112 ms of computation per second of sound at the default rate." },
  "generateur-courbe": { fr: "Fabrique une courbe de modulation a brancher sur l'entree Modulation d'un effet. Une courbe porte des valeurs entre zero et un ; c'est l'effet qui decide de ce que zero et un veulent dire chez lui. La suite logistique tient une place particuliere parmi les autant que les autres formes : sept composants l'ont chacun reimplementee dans leur coin — echo logistique, tremolo logistique, vibrato logistique, auto-pan logistique, chopper logistique, Paulstretch logistique, melangeur logistique. Sept implementations de la meme suite, et pour sept effets seulement. Une source unique branchee sur n'importe quel effet fait le meme travail, et sur tous ceux qui acceptent une modulation. La suite elle-meme est x suivant = r x (1 - x) : en dessous de 3 elle se fixe sur une valeur, vers 3,45 elle alterne entre deux valeurs puis quatre, et au-dela de 3,57 elle devient chaotique et ne se repete jamais — c'est la que le reglage Chaos est interessant. Les formes periodiques donnent le tremolo, le vibrato et le balayage ordinaires ; la rampe donne les effets « progressifs » ; la marche aleatoire donne une derive douce qui ne revient jamais au meme endroit.", en: "Builds a modulation curve to plug into an effect's Modulation input. A curve carries values between zero and one; the effect decides what zero and one mean at its end. The logistic sequence deserves an explanation, because it is this node's reason for being as much as the other shapes: seven nodes each reimplemented it on their own — logistic echo, logistic tremolo, logistic vibrato, logistic auto-pan, logistic chopper, logistic Paulstretch, logistic mixer. Seven implementations of the same sequence, and for seven effects only. A single source plugged into any effect does the same work, and for every effect that accepts a modulation. The sequence itself is x next = r x (1 - x): below 3 it settles on one value, around 3.45 it alternates between two then four, and beyond 3.57 it turns chaotic and never repeats — that is where the Chaos setting gets interesting. The periodic shapes give the ordinary tremolo, vibrato and sweep; the ramp gives the « progressive » effects; the random walk gives a gentle drift that never comes back to the same place." },
  "temperament": { fr: "Rejoue un fichier MIDI dans un tempérament autre que l'égal, et le rend en audio. Tous les autres composants jouent en tempérament égal : douze demi-tons rigoureusement identiques, qui ne sonnent juste nulle part mais faux partout de la même façon. Ce n'est ni naturel ni ancien — c'est un compromis généralisé au XIXᵉ siècle. Sept accords sont proposés, de l'intonation juste (tierce 5/4 et quinte 3/2 exactes, d'une pureté qu'aucun piano ne donne, mais la tonalité voisine devient inutilisable) au mésotonique 1/4 de comma de la Renaissance, en passant par Werckmeister III, Kirnberger III et Vallotti, où toutes les tonalités sont jouables sans qu'aucune ne soit identique — c'est de ces accords-là que « Le Clavier bien tempéré » tire son titre, bien tempéré ne voulant pas dire égal. « Tonique » choisit la note sur laquelle l'accord est fait : c'est elle qui sonne pure, et les tonalités éloignées s'écartent d'autant plus. La sortie texte donne les douze écarts au tempérament égal, en centièmes de demi-ton. Le composant rend de l'audio et non du MIDI, et c'est voulu : un fichier MIDI ne sait pas porter une hauteur en centièmes sans pitch-bend par canal, que tous les lecteurs n'honorent pas. Ici les hauteurs deviennent fractionnaires et le rendu — FM ou SoundFont — les joue exactement.", en: "Replays a MIDI file in a tuning other than equal temperament, and renders it to audio. Every other node plays in equal temperament: twelve rigorously identical semitones, which sound in tune nowhere but equally out of tune everywhere. That is neither natural nor ancient — it is a compromise generalised in the 19th century. Seven tunings are offered, from just intonation (exact 5/4 third and 3/2 fifth, a purity no piano gives, but the neighbouring key becomes unusable) to Renaissance quarter-comma meantone, by way of Werckmeister III, Kirnberger III and Vallotti, where every key is playable without any two sounding alike — it is those tunings that give « The Well-Tempered Clavier » its title, well-tempered not meaning equal. « Tonic » picks the note the tuning is built on: that one sounds pure, and distant keys drift the further away. The text output lists the twelve deviations from equal temperament, in cents. The node outputs audio rather than MIDI, deliberately: a MIDI file cannot carry a pitch in cents without per-channel pitch bend, which not every player honours. Here the pitches become fractional and the renderer — FM or SoundFont — plays them exactly." },
  "l-systeme": { fr: "Engendre une mélodie par une grammaire qui se réécrit. Aristid Lindenmayer, biologiste, a proposé en 1968 ce système pour décrire la croissance des plantes : un mot de départ, et des règles qui remplacent chaque lettre par un groupe de lettres, appliquées à toutes les lettres en même temps. Répétée, la réécriture engendre des structures auto-similaires — d'où les fougères et les arbres qu'on en tire en image, et ici des phrases dont les motifs se répètent à plusieurs échelles sans jamais se répéter à l'identique.\n\nL'interprétation est celle d'une tortue : chaque signe est un geste. Une lettre joue une note et avance ; + et − montent et descendent d'un degré de la gamme, jamais d'un demi-ton, si bien que le résultat ne sort pas de la tonalité ; les crochets ouvrent et ferment une broderie, dont on ressort exactement là où l'on était, et qui se joue plus doucement que la ligne ; > et < doublent et divisent la durée du pas ; le point est un silence. Cinq grammaires classiques sont fournies — les algues de Lindenmayer, dont les longueurs suivent la suite de Fibonacci, le flocon de Koch, la courbe du dragon, une plante et la poussière de Cantor.\n\n« Écrit à la main » prend les règles écrites dans les champs. Le mot grandit vite : une règle qui double sa longueur atteint le millier en dix tours, et la réécriture s'arrête d'elle-même avant l'explosion. La sortie texte donne le mot obtenu, pour qu'on voie ce qu'on écoute. Rien n'est aléatoire ici : une même grammaire rend toujours la même musique.", en: "Generates a melody from a self-rewriting grammar. Aristid Lindenmayer, a biologist, proposed this system in 1968 to describe plant growth: a starting word, and rules replacing each letter with a group of letters, applied to every letter at once. Repeated, the rewriting produces self-similar structures — hence the ferns and trees drawn from it, and here phrases whose motifs repeat at several scales without ever repeating identically. The reading is a turtle's: each symbol is a gesture. A letter plays a note and moves on; + and − move up and down one scale degree, never a semitone, so the result never leaves the key; brackets open and close an ornament, which returns exactly where it started and plays more softly than the line; > and < double and halve the step; a dot is a rest. Five classic grammars are provided — Lindenmayer's algae, whose lengths follow the Fibonacci sequence, the Koch snowflake, the dragon curve, a plant and Cantor dust. « Hand-written » takes the rules written in the fields. The word grows fast: a rule that doubles its length reaches a thousand in ten passes, and the rewriting stops by itself before exploding. The text output gives the resulting word, in regard of what is heard. Nothing is random here: the same grammar always gives the same music." },
  "markov-midi": { fr: "Apprend les enchaînements de notes d'un fichier MIDI, puis en engendre de nouveaux. La sortie texte donne la table, contexte par contexte, en noms de notes et en pourcentages. « Ordre » est le réglage qui compte : c'est le nombre de notes regardées en arrière. À 1, le morceau ressort dans sa tonalité mais sans phrase ; à 2 ou 3, ses tournures réapparaissent ; au-delà, la chaîne n'a plus le choix et recopie la source. La part de contextes « sans choix », affichée en tête du rapport, mesure exactement ce sur-apprentissage : au-delà de 80 %, baissez l'ordre. Deux simplifications, dites plutôt que tues : les durées de la source ne sont pas apprises — le composant n'imite que les hauteurs et les joue en croches —, et un accord est lu du grave vers l'aigu, donc comme un arpège. Quand la chaîne tombe sur un enchaînement jamais vu, elle repart d'un contexte connu au lieu de s'arrêter. À graine fixée, la même suite est rejouée à l'identique.", en: "Learns a MIDI file's note transitions, then generates new ones. The text output gives the table, context by context, in note names and percentages. « Order » is the setting that matters: it is how many notes are looked back on. At 1, the piece comes out in its key but without phrasing; at 2 or 3, its turns of phrase reappear; beyond that, the chain has no choice left and copies the source. The share of contexts with « no choice », shown at the head of the report, measures exactly that overfitting: above 80%, lower the order. Two simplifications, stated rather than hidden: the source's durations are not learned — the node imitates pitches only and plays them as eighth notes — and a chord is read from the bottom up, hence as an arpeggio. When the chain meets a transition never seen, it restarts from a known context instead of stopping. With a fixed seed, the same sequence is replayed identically." },
  "boucle-graphe-debut": { fr: "Ouvre une boucle de graphe. Tout ce qui est branché entre ce composant et une « Fin de boucle » — A, B ou C — est joué « Tours » fois, et chaque tour part du résultat du précédent : si la chaîne transpose d'un demi-ton, le deuxième tour transpose un signal déjà transposé, donc de deux demi-tons au total, le troisième de trois, et ainsi de suite. La fin de boucle décide ensuite de ce qu'on garde des N états successifs : « Fin de boucle A » les met bout à bout, « B » ne garde que le dernier, « C » les empile l'un sur l'autre comme le mélangeur. Le moteur n'exécute que des graphes sans cycle : la boucle est donc dépliée avant l'exécution — la chaîne interne est recopiée autant de fois qu'il y a de tours, et chaque copie est reliée à la précédente. Cela se voit sur le temps de calcul, qui est bien celui de N passages, et non d'un seul. Ce qui entre dans la boucle depuis l'extérieur par un autre port — un réglage, une seconde source — alimente identiquement chaque tour. Ce qui en sort ailleurs que par « Fin de boucle » ne sort qu'une fois, au dernier tour. Limites : une boucle ne peut pas en contenir une autre, et une fin de boucle ne peut avoir qu'un seul début en amont. Dans ces cas, rien n'est déplié et le composant le dit au lieu de produire n'importe quoi.", en: "Opens a graph loop. Everything wired between this node and a « Loop End » — A, B or C — is played « Passes » times, and each pass starts from the previous result: if the chain transposes by a semitone, the second pass transposes an already transposed signal, so by two semitones in total, the third by three, and so on. The loop end then decides what is kept of the N successive states: « Loop End A » puts them end to end, « B » keeps only the last one, « C » stacks them on top of one another like the mixer. It shows in the computation time, which is that of N passes, not one. Anything entering the loop from outside through another port — a setting, a second source — feeds every pass identically. Anything leaving it other than through « Loop End » leaves only once, on the last pass. Limits: a loop cannot contain another loop, and a loop end can only have one start upstream. In those cases nothing is unrolled and the node says so instead of producing nonsense." },
  "boucle-graphe-fin": { fr: "Referme une boucle de graphe ouverte par « Début de boucle », et met bout à bout les résultats de tous les tours : la sortie contient les N états successifs, dans l'ordre où ils ont été produits — la durée est donc la somme des tours. C'est la fin de boucle qui donne à entendre la transformation elle-même : on suit le son qui dérive de tour en tour. « Fondu » adoucit le raccord entre deux tours ; à 0 ms ils se suivent exactement. Les deux autres fins font le même travail de boucle et ne diffèrent que par ce qu'elles gardent : « Fin de boucle B » ne rend que le dernier tour, « Fin de boucle C » empile les tours l'un sur l'autre. Une boucle n'a qu'une seule fin : c'est en la choisissant qu'on choisit le résultat. Si ce composant n'a aucun « Début de boucle » en amont, rien n'est déplié : il se comporte alors comme une simple jointure de ce qu'il reçoit.", en: "Closes a graph loop opened by « Loop Start », and puts every pass's result end to end: the output holds the N successive states, in the order they were produced — its duration is therefore the sum of the passes. This is the loop end that lets you hear the transformation itself: you follow the sound drifting pass after pass. « Fade » smooths the join between two passes; at 0 ms they follow each other exactly. The two other ends do the same loop work and differ only in what they keep: « Loop End B » returns the last pass only, « Loop End C » stacks the passes on top of one another. A loop has a single end: choosing it is how you choose the result. If this node has no « Loop Start » upstream, nothing is unrolled: it then behaves as a plain join of whatever it receives." },
  "boucle-graphe-fin-b": { fr: "Referme une boucle de graphe ouverte par « Début de boucle » et ne garde que le résultat du dernier tour. Les tours précédents sont calculés — ils doivent l'être, chacun partant du résultat du précédent —, mais ils ne ressortent pas d'ici : la sortie a la durée d'un seul tour. C'est ce qu'on veut quand la boucle sert à itérer et non à donner à entendre l'itération : cinq tours d'une légère saturation pour obtenir la saturation qu'un seul tour ne donne pas, dix tours d'un lissage pour un son poli, une réverbération appliquée encore et encore jusqu'à ce qu'il ne reste qu'une nappe. « Fin de boucle A » garderait les dix états successifs bout à bout et rendrait dix fois la durée ; ici on ne garde que l'état d'arrivée. Sans réglage : il n'y a rien à décider, et le nombre de tours se règle sur « Début de boucle ». Si ce composant n'a aucun « Début de boucle » en amont, rien n'est déplié : il rend alors ce qu'il reçoit.", en: "Closes a graph loop opened by « Loop Start » and keeps only the last pass's result. The earlier passes are computed — they must be, each starting from the previous result — but they do not come out here: the output lasts a single pass. This is what you want when the loop is there to iterate rather than to let the iteration be heard: five passes of a light saturation to get the saturation a single pass cannot give, ten passes of a smoothing for a polished sound, a reverb applied again and again until nothing is left but a wash. « Loop End A » would keep the ten successive states end to end and return ten times the duration; here only the final state is kept. No setting: there is nothing to decide, and the number of passes is set on « Loop Start ». If this node has no « Loop Start » upstream, nothing is unrolled: it then returns what it receives." },
  "boucle-graphe-fin-c": { fr: "Referme une boucle de graphe ouverte par « Début de boucle » et empile les tours : ils sonnent tous en même temps, additionnés depuis l'instant zéro, exactement comme le mélangeur additionne des pistes. La sortie a la durée du tour le plus long, et non la somme des tours. C'est ce qui fait entendre ensemble ce qu'une boucle produit l'un après l'autre : un canon si la chaîne retarde le son, un accord si elle transpose, un chœur si elle la désaccorde un peu. Le mélangeur n'a pas de niveau, parce que le niveau de chaque piste se règle sur le composant qui la produit ; ici c'est impossible — les tours sont des copies d'une seule chaîne et partagent leurs réglages —, d'où le réglage « Niveau », appliqué à la somme. Le message annonce la crête obtenue : empiler dix tours d'un même son dépasse 1, et cela doit se voir sur le composant plutôt que s'entendre à la lecture ; baissez alors le niveau. Si ce composant n'a aucun « Début de boucle » en amont, rien n'est déplié : il se comporte comme un mélangeur de ce qu'il reçoit.", en: "Closes a graph loop opened by « Loop Start » and stacks the passes: they all sound at once, summed from time zero, exactly as the mixer sums tracks. The output lasts as long as the longest pass, not the sum of the passes. This is what makes audible together what a loop produces one after the other: a canon if the chain delays the sound, a chord if it transposes, a choir if it detunes slightly. The mixer has no level setting because each track's level is set on the node producing it; here that is impossible — the passes are copies of a single chain and share their settings — hence the « Level » setting, applied to the sum. The message reports the peak reached: stacking ten passes of the same sound goes above 1, and that should be visible on the node rather than audible on playback; lower the level then. If this node has no « Loop Start » upstream, nothing is unrolled: it behaves as a mixer of whatever it receives." },
  "csound": { fr: "Exécute un orchestre et une partition Csound. Csound descend de music V, la lignée qui a inventé la synthèse numérique : Barry Vercoe l'écrit au MIT en 1986, il compte aujourd'hui environ mille neuf cents opcodes, et son portage WebAssembly permet de le faire tourner ici sans rien installer. C'est un langage de programmation sonore, et non un traitement fixé d'avance. Un programme Csound se compose de deux parties, et cette séparation est sa marque de fabrique : l'orchestre définit des instruments, la partition dit quand les jouer et avec quels arguments. « i1 0 1 220 0.5 » joue l'instrument 1 à l'instant zéro pendant une seconde, en lui passant 220 et 0,5 comme p4 et p5.\n\nCe que le composant règle lui-même. La fréquence d'échantillonnage est imposée par la carte son, souvent 48 kHz, et Csound ignore les demandes contraires : un « sr » écrit dans l'orchestre reste sans effet. Le résultat est ensuite ramené à 44 100 Hz, avec 83 dB de rapport signal/erreur à 10 kHz. La sortie est limitée sous l'unité, parce que Csound ne borne rien et qu'un orchestre mal réglé rend des crêtes au-delà de deux ; la crête d'origine est annoncée dans le rapport.\n\nL'orchestre et la partition s'écrivent dans l'inspecteur, mais ils peuvent aussi venir du graphe : les entrées Orchestre et Partition acceptent du texte, et une entrée branchée prend le pas sur le champ correspondant, qui reste alors un exemple. Tout composant qui sort du texte peut ainsi fournir une partition.\n\nLa partition a trois sources possibles, et l'ordre est celui-ci : un MIDI branché d'abord — chaque note devenant un événement « i1 » avec la fréquence en p4, l'amplitude en p5 et le numéro de note en p6 —, puis l'entrée Partition, puis le champ. Le composant dit dans son message laquelle des trois il a prise, et signale l'entrée branchée qui n'a pas servi.\n\nUn son branché sur l'entrée Audio est écrit dans le système de fichiers de Csound sous le nom « entree1.wav » et ne s'entend que si l'orchestre le lit, par « a1 diskin2 \"entree1.wav\", 1 » — faute de quoi le composant signale que le son n'est jamais lu ; il est écrit en mono par défaut, parce que diskin2 exige que le nombre de sorties demandées corresponde au nombre de canaux du fichier et refuse la note sinon, l'erreur n'apparaissant que dans les messages de Csound. Enfin, les opcodes aléatoires demandent une graine fixée pour qu'un rendu se reproduise.", en: "Runs a Csound orchestra and score. Csound descends from music V, the line that invented digital synthesis: Barry Vercoe wrote it at MIT in 1986, it now counts some nineteen hundred opcodes, and its WebAssembly port lets it run here with nothing to install. It is a sound programming language, not a fixed process. A Csound program has two parts, and that separation is its signature: the orchestra defines instruments, the score says when to play them and with which arguments. « i1 0 1 220 0.5 » plays instrument 1 at time zero for one second, passing it 220 and 0.5 as p4 and p5.\n\nWhat the node settles by itself. The sampling rate is imposed by the sound card, often 48 kHz, and Csound ignores requests to the contrary: an « sr » written in the orchestra has no effect. The result is then brought back to 44100 Hz, at 83 dB signal-to-error at 10 kHz. The output is limited below unity, because Csound bounds nothing and a badly set orchestra returns peaks above two; the original peak is reported.\n\nThe orchestra and the score are written in the inspector, but they can also come from the graph: the Orchestra and Score inputs accept text, and a connected input takes precedence over the matching field, which then remains an example. Any node that outputs text can thus feed a score.\n\nThe score has three possible sources, in this order: a connected MIDI file first — each note becoming an « i1 » event with the frequency in p4, the amplitude in p5 and the note number in p6 —, then the Score input, then the field. The node states in its message which of the three it took, and flags a connected input that was not used.\n\nA sound connected to the Audio input is written into Csound's filesystem as « entree1.wav » and is heard only if the orchestra reads it, with « a1 diskin2 \"entree1.wav\", 1 » — failing which the node reports that the sound is never read; it is written in mono by default, because diskin2 requires the number of outputs asked for to match the file's channel count and refuses the note otherwise, the error showing only in Csound's own messages. Finally, random opcodes require a fixed seed for a render to reproduce." },
  "csound-instrument": { fr: "Joue un fichier MIDI avec un orchestre Csound. Chaque note devient un événement de partition, et l'instrument 1 est appelé pour chacune. La convention des arguments est celle des exemples de Csound, et elle évite toute conversion : p4 porte la fréquence en hertz, p5 l'amplitude de zéro à un, p6 le numéro de note MIDI pour qui en a besoin. N'importe quelle source MIDI alimente ainsi un orchestre écrit une fois. « Queue » ajoute du temps après la dernière note : sans lui, une réverbération ou une résonance se couperait net à la fin de la partition, ce qui est le défaut le plus courant d'un rendu hors ligne. Techniquement, ce temps est obtenu par un « f0 » qui tient la partition ouverte, ce qui est la façon canonique de le faire en Csound. L'orchestre s'écrit dans l'inspecteur, mais il peut aussi venir du graphe : l'entrée Orchestre accepte du texte, et une entrée branchée prend le pas sur le champ, qui reste alors un exemple, ce que le composant annonce dans son message. Un « sr » écrit dans l'orchestre reste sans effet : la sortie est ramenée à 44 100 Hz et limitée sous l'unité, et les opcodes aléatoires demandent une graine fixée.", en: "Plays a MIDI file with a Csound orchestra. Each note becomes a score event, and instrument 1 is called for every one of them. The argument convention is that of Csound's own examples, and it avoids any conversion: p4 carries the frequency in hertz, p5 the amplitude from zero to one, p6 the MIDI note number for whoever needs it. Any MIDI source can thus feed an orchestra written once. « Tail » adds time after the last note: without it, a reverb or a resonance would be cut off at the end of the score, which is the commonest flaw of an offline render. Technically that time comes from an « f0 » holding the score open, which is the canonical way to do it in Csound. The orchestra is written in the inspector, but it can also come from the graph: the Orchestra input accepts text, and a connected input takes precedence over the field, which then remains an example, as the node's message states. An « sr » written in the orchestra has no effect: the output is brought back to 44100 Hz and limited below unity, and random opcodes require a fixed seed." },
  "csound-effet": { fr: "Traite un ou deux sons par un orchestre Csound. Les entrées sont écrites dans le système de fichiers de Csound sous les noms « entree1.wav » et « entree2.wav », et se lisent par diskin2 ou soundin — ce sont donc des fichiers et non des flux, ce qui a une conséquence utile : on peut les relire à une autre vitesse, en boucle, à l'envers, ou les charger dans une table pour les traiter par blocs. La durée de la partition est réglée sur celle de la plus longue entrée, plus la queue demandée, laquelle est indispensable dès qu'un délai ou une réverbération a quelque chose à laisser mourir.\n\n« Canaux d'entrée » : diskin2 exige que le nombre de sorties demandées corresponde au nombre de canaux du fichier. « a1 diskin2 » sur un fichier stéréo refuse la note et ne rend qu'un silence, l'erreur n'apparaissant que dans les messages de Csound. Les entrées sont donc réduites en mono par défaut ; le mode stéréo convient à un orchestre qui écrit « a1, a2 diskin2 ». L'orchestre par défaut est un délai modulé, qui donne la forme d'un traitement.\n\nIl s'écrit dans l'inspecteur, mais il peut aussi venir du graphe : l'entrée Orchestre accepte du texte et prend le pas sur le champ, ce que le composant annonce dans son message. Enfin, un son branché que l'orchestre ne nomme jamais n'a aucun effet — le fichier est écrit, personne ne le lit — le son rendu n'a alors rien à voir avec celui qui entre ; le composant contrôle donc que « entree1.wav » et « entree2.wav » sont bien lus, commentaires retirés, et le signale sinon.", en: "Processes one or two sounds through a Csound orchestra. The inputs are written into Csound's filesystem as « entree1.wav » and « entree2.wav », and read with diskin2 or soundin — they are therefore files rather than streams, which has a useful consequence: they can be read back at another speed, looped, reversed, or loaded into a table for block processing. The score's duration is set from the longest input plus the requested tail, which is essential as soon as a delay or a reverb has something to let die away.\n\n« Input channels »: diskin2 requires the number of outputs asked for to match the file's channel count. « a1 diskin2 » on a stereo file refuses the note and returns nothing but silence, the error showing only in Csound's own messages. The inputs are therefore downmixed to mono by default; stereo suits an orchestra that writes « a1, a2 diskin2 ». The default orchestra is a modulated delay, which gives the shape of a process. It is written in the inspector, but it can also come from the graph: the Orchestra input accepts text and takes precedence over the field, which the node announces in its message.\n\nFinally, a connected sound the orchestra never names has no effect — the file is written, nobody reads it — and the rendered sound then has nothing to do with the one connected; the node therefore checks that « entree1.wav » and « entree2.wav » are really read, comments stripped, and reports it otherwise." },
  "formules-csound": { fr: "Huit orchestres Csound complets au choix, chacun avec sa partition d'essai. Chaque entrée est un orchestre entier qui met en œuvre une technique de synthèse, avec ses propres p-fields : l'indice de modulation pour la FM, la coupure du filtre pour la soustractive, la densité de grains pour le granulaire. Les huit : oscillateur à vibrato, modulation de fréquence à indice variable (Chowning, 1973), soustractive à filtre de Moog balayé, additive à harmoniques comptés, corde de Karplus-Strong (1983), modulation en anneau, nuage granulaire (d'après Gabor, 1947, repris par Roads et Truax), et un instrument doublé d'un bus de réverbération — deux instruments et une variable globale, la structure de presque toutes les pièces sérieuses, et la seule chose qu'un orchestre à un instrument ne peut pas montrer.\n\nLes p-fields diffèrent d'une formule à l'autre, et une partition écrite pour la FM ne veut rien dire pour le granulaire. Celle qui sort avec chaque formule démontre ce qu'elle sait faire — la FM y balaie son indice de 1 à 12 puis passe à un rapport irrationnel, la soustractive y balaie sa coupure dans les deux sens, le granulaire y épaissit son nuage de huit à quatre cents grains par seconde. Les deux sorties forment un orchestre et sa partition, prêts à être rendus.\n\nLe niveau est écrit dans l'orchestre sous la forme d'une variable globale « gkNiveau » que chaque ligne de sortie multiplie : elle est visible dans le texte, donc modifiable à la main par qui le relit. Le bus de réverbération sort en stéréo et demande un rendu stéréo, la moitié du signal se perdant autrement. Et la densité du granulaire multiplie le niveau — des grains qui se recouvrent s'additionnent —, ce pour quoi sa partition d'essai baisse l'amplitude à mesure qu'elle épaissit le nuage : à quatre cents grains par seconde, l'amplitude 0,4 atteint une crête de 0,95.", en: "Eight complete Csound orchestras to choose from, each with its own test score. Each entry is a whole orchestra carrying out one synthesis technique, with its own p-fields: the modulation index for FM, the filter cutoff for subtractive, the grain density for granular. The eight: vibrato oscillator, frequency modulation with variable index (Chowning, 1973), subtractive with swept Moog filter, additive with counted harmonics, Karplus-Strong string (1983), ring modulation, granular cloud (after Gabor, 1947, taken up by Roads and Truax), and an instrument paired with a reverb bus — two instruments and a global variable, the structure of nearly every serious piece, and the one thing a single-instrument orchestra cannot show.\n\nThe p-fields differ from one formula to the next, and a score written for FM means nothing for the granular one. The one that comes out with each formula demonstrates what it can do — FM sweeps its index from 1 to 12 then moves to an irrational ratio, subtractive sweeps its cutoff both ways, granular thickens its cloud from eight to four hundred grains per second. Wire both outputs to the Csound node and you hear the technique. The level is written into the orchestra as a global variable « gkNiveau » that every output line multiplies: it is visible in the text, hence editable by hand by whoever reads it.\n\nThe reverb bus outputs in stereo and requires a stereo render, half the signal being lost otherwise. And the granular density multiplies the level — overlapping grains add up — which is why its test score lowers the amplitude as it thickens the cloud: at four hundred grains per second, amplitude 0.4 reaches a peak of 0.95." },
  "orchestre-csound": { fr: "Compose un orchestre Csound en cochant des instruments dans une liste, plutôt qu'en écrivant du code. L'orchestre est la moitié du langage : Csound sépare les instruments, qui disent comment sonner, de la partition, qui dit quand jouer quoi. Un arrangement à quatre parties demande quatre instruments dans le même orchestre, chacun numéroté. La seconde sortie est une partition d'essai : elle fait sonner chaque instrument coché à son tour, un la3 d'une seconde chacun.\n\nElle porte aussi, en commentaires que Csound ignore, le numéro et la description de chaque instrument ainsi que les tables créées, et sert ainsi de squelette à une partition écrite ensuite, p-fields déjà en place. L'ordre des cases cochées décide des numéros : le premier devient « instr 1 », le second « instr 2 », ce qui s'accorde avec l'option « un instrument par canal » de « Partition Csound », qui numérote les canaux MIDI présents de la même façon.\n\nTrois défauts d'un orchestre combiné sont fermés par le composant. Premièrement la numérotation : deux instruments nommés tous deux « instr 1 » ne provoquent aucune erreur, le second remplace simplement le premier et la partition joue le mauvais son. Deuxièmement les tables de fonction, qui se déclaraient dans la partition — « f1 0 16384 10 1 » — et se marcheraient dessus à plusieurs ; elles passent par « ftgen » dans l'orchestre, avec un numéro attribué par Csound et retenu dans une variable, si bien qu'aucune collision n'est plus possible et qu'une même table sert à tous ceux qui la demandent.\n\nTroisièmement le nombre de canaux : un instrument qui écrit « out » mélangé à un qui écrit « outs » donne un rendu à moitié muet — tous sont donc écrits de la même façon, et le réglage Canaux doit être le même que celui du composant Csound. Le contrat des p-fields est commun : p4 la hauteur en hertz, p5 l'amplitude entre 0 et 1 — les valeurs par défaut de « Partition Csound », de sorte que les deux composants s'assemblent sans réglage. Les instruments sont accordés et égaliés sur trois octaves.\n\n« wgbrass » n'est pas proposé, ne tenant aucune hauteur. La corde frottée et la flûte portent une compensation d'accord : la corde surblow d'une octave et une quinte dans l'aigu à pression d'archet 4, et joue 0,034 cent trop haut par hertz à pression 2, ce qui se corrige exactement. Les gains suivent : pour une amplitude demandée de 0,6, les crêtes vont de 0,10 à 0,95 selon l'opcode, et chaque gain les ramène à 0,6. Le composant ne règle pas un instrument dans le détail : ses entrées sont des préréglages jouables, et l'enveloppe est commune — 20 ms d'attaque, 40 ms d'extinction, de quoi ne pas cliquer, chaque modèle gardant sa propre décroissance.", en: "Composes a Csound orchestra by ticking instruments in a list rather than writing code. The orchestra is half the language: Csound separates the instruments, which say how to sound, from the score, which says when to play what. A four-part arrangement needs four instruments in the same orchestra, each numbered. The second output is a test score: it sounds each ticked instrument in turn, one second of A4 each. It also carries, as comments Csound ignores, each instrument's number and description along with the tables created, and so serves as the skeleton of a score written afterwards, p-fields already in place.\n\nThe order of the ticked boxes decides the numbers: the first becomes « instr 1 », the second « instr 2 », which matches « Csound Score »'s « one instrument per channel » option, numbering the MIDI channels present the same way. Three faults of a combined orchestra are closed by the node. First numbering: two instruments both named « instr 1 » raise no error, the second simply replaces the first and the score plays the wrong sound. Second function tables, which used to be declared in the score — « f1 0 16384 10 1 » — and would clash between instruments; they go through « ftgen » in the orchestra, with a number assigned by Csound and held in a variable, so no collision is possible any more and one table serves everyone who asks for it.\n\nThird the channel count: an instrument writing « out » mixed with one writing « outs » yields a half-silent render — so all are written the same way, and the Channels setting must match the Csound node's. The p-field contract is shared: p4 the pitch in hertz, p5 the amplitude between 0 and 1 — « Csound Score »'s defaults, so the two nodes assemble with no setting at all. The instruments are tuned and levelled over three octaves. « wgbrass » is not offered, holding no pitch.\n\nThe bowed string and the flute carry a tuning compensation: the string overblows by an octave and a fifth in the treble at bow pressure 4, and plays 0.034 cent sharp per hertz at pressure 2, which corrects exactly. The gains follow: for a requested amplitude of 0.6, peaks range from 0.10 to 0.95 depending on the opcode, and each gain brings them back to 0.6. The node does not tune an instrument in detail: its entries are playable presets, and the envelope is shared — 20 ms attack, 40 ms release, enough not to click, each model keeping its own decay." },
  "partition-aleatoire-csound": { fr: "Tire une partition Csound au sort. Un MIDI ne porte que hauteur, vélocité et durée, et il est tenu à une grille ; une partition Csound porte autant de p-fields qu'on veut et n'a aucune grille. C'est même l'usage historique de cette famille de langages — Iannis Xenakis a écrit ses pièces stochastiques, la série ST en 1962 sur un IBM 7090, en tirant les instants d'attaque dans une loi exponentielle, c'est-à-dire un processus de Poisson, et les hauteurs et durées dans d'autres lois.\n\nLe processus de Poisson : les événements y arrivent au hasard, sans mémoire, à une densité moyenne donnée, et l'intervalle entre deux voisins suit alors une loi exponentielle. Sa signature se mesure, et la sortie Statistiques la mesure : l'écart-type des intervalles égale leur moyenne, là où une grille régulière l'a nul. C'est la différence entre un nuage et une pulsation. Une courbe branchée module la densité au fil du temps — un nuage qui s'épaissit puis se dissipe —, et elle le fait par amincissement, la méthode de Lewis et Shedler (1979) : on tire à la densité maximale, puis on garde chaque instant avec la probabilité que la courbe indique.\n\nFaire varier la densité dans le tirage lui-même biaiserait la loi. Le champ libre est ce qu'une partition a de plus qu'un MIDI : un p-field supplémentaire, tiré dans sa propre loi pour chaque événement, que l'orchestre lit comme il veut — une position stéréo, un indice de modulation, une largeur de bande. Ce qui n'est pas tiré au sort compte autant : la gamme, l'étendue, le nombre d'instruments et les bornes de durée sont les contraintes du tirage, et Xenakis les bornait étroitement.\n\nLes statistiques annoncent ce qui a été produit, et non ce qui a été demandé : huit secondes à quatre événements par seconde ne font pas trente-deux événements mais un nombre qui varie d'un tirage à l'autre. La graine, enfin, rend un tirage reproductible : zéro en tire une nouvelle à chaque exécution et l'affiche dans le message, toute autre valeur redonne exactement la même partition.", en: "Draws a Csound score at random. A MIDI file carries only pitch, velocity and duration, and it is tied to a grid; a Csound score carries as many p-fields as needed and has no grid at all. It is even the historical use of this family of languages — Iannis Xenakis wrote his stochastic pieces, the ST series in 1962 on an IBM 7090, by drawing the onsets from an exponential law, that is to say a Poisson process, and the pitches and durations from other laws.\n\nThe Poisson process: events arrive at random, without memory, at a given mean density, and the interval between neighbours then follows an exponential law. Its signature is measurable, and the Statistics output measures it: the standard deviation of the intervals equals their mean, where a regular grid has it at zero. That is the difference between a cloud and a pulse. A connected curve modulates the density over time — a cloud that thickens then disperses — and it does so by thinning, the method of Lewis and Shedler (1979): draw at the maximum density, then keep each onset with the probability the curve gives.\n\nVarying the density inside the draw itself would bias the law. The free field is what a score has that MIDI does not: an extra p-field, drawn from its own law for every event, which the orchestra reads as it likes — a stereo position, a modulation index, a bandwidth. What is not drawn matters just as much: the scale, the range, the number of instruments and the duration bounds are the constraints of the draw, and Xenakis bounded them tightly. The statistics report what was produced, not what was asked: eight seconds at four events per second do not make thirty-two events but a number that varies from draw to draw.\n\nThe seed, finally, makes a draw reproducible: zero draws a new one on each run and shows it in the message, any other value gives exactly the same score again." },
  "partition-csound": { fr: "Traduit un fichier MIDI en partition Csound. Toutes les notations convergent sur le MIDI — ABC, tablature, séquenceurs de batterie, de mélodie et d'accords, texte vers MIDI — si bien que le traduire les traduit toutes. La sortie est du texte, qui alimente une partition Csound. Ce qu'une partition a de plus qu'un MIDI : une note y est une ligne « i1 0 1 440 0.5 60 », où chaque nombre après la durée est un p-field que l'orchestre lit comme il veut.\n\nUn MIDI n'a que hauteur, vélocité et durée ; une partition en a autant qu'on veut, et ce composant laisse choisir ce qui va dans chacun — hauteur, amplitude, vélocité brute, numéro de note, durée, canal, une constante, ou la valeur d'une courbe branchée, lue à l'instant de chaque note. Le réglage qui décide de tout est la convention de hauteur. Csound en a quatre et un orchestre écrit pour l'une ne fonctionne pas avec une autre : cps en hertz (440 pour le la3), pch en octave point classe de hauteur (8.00 le do central, 8.09 le la — la notation de music V, dont les centièmes s'arrêtent à 11), oct en octave décimale (8.0 le do central, 8.75 le la), et midi en numéro de note.\n\nNourrir en hertz un orchestre qui attend du pch ne produit ni son ni erreur, d'où ce réglage explicite plutôt qu'une valeur en dur. Un instrument par canal permet de jouer un arrangement complet : chaque canal MIDI présent reçoit son numéro, à la suite du précédent — les canaux 1, 2 et 10 donnent les instruments 1, 2 et 3, parce qu'un orchestre numérote les siens à la suite —, et la sortie Rapport donne la correspondance, dont l'orchestre a besoin.\n\nLes temps sont en secondes et il n'y a pas de réglage de tempo : une partition Csound bat à soixante par défaut, où un temps vaut une seconde. Ajouter un « t » de tempo réinterpréterait ces nombres et ferait défiler le morceau à côté de ce qu'on a écrit. La marge finale, écrite en « f0 », laisse sonner les queues de réverbération : sans elle Csound s'arrête à la dernière note et les coupe net.", en: "Translates a MIDI file into a Csound score. All notations converge on MIDI — ABC, tablature, drum, melody and chord sequencers, text to MIDI — so translating it translates them all. The output is text, which feeds a Csound score. What a score has that MIDI does not: a note is a line « i1 0 1 440 0.5 60 », where every number after the duration is a p-field the orchestra reads as it likes. MIDI carries only pitch, velocity and duration; a score carries as many as needed, and each one is assigned here — pitch, amplitude, raw velocity, note number, duration, channel, a constant, or the value of a connected curve, read at each note's onset.\n\nThe setting that decides everything is the pitch convention. Csound has four and an orchestra written for one does not work with another: cps in hertz (440 for A4), pch in octave point pitch-class (8.00 middle C, 8.09 the A — Music V's notation, whose hundredths stop at 11), oct in decimal octaves (8.0 middle C, 8.75 the A), and midi as a note number. Feeding hertz to an orchestra that expects pch produces neither sound nor error, hence this explicit setting rather than a hard-coded value.\n\nOne instrument per channel makes a whole arrangement playable: each MIDI channel present gets its number, following the previous one — channels 1, 2 and 10 yield instruments 1, 2 and 3, because an orchestra numbers its own consecutively — and the Report output gives the mapping, which the orchestra needs. Times are in seconds and there is no tempo setting: a Csound score beats at sixty by default, where one beat is one second. Adding a « t » tempo statement would reinterpret those numbers and make the piece run beside what was written.\n\nThe final margin, written as « f0 », lets reverb tails ring: without it Csound stops at the last note and cuts them off." },
  "csound-instruments-physiques": { fr: "Les instruments à modèle physique de Csound, réglables sans écrire une ligne de code. Ce sont les modèles de Perry Cook et Julius Smith, portés dans Csound et débogués depuis trente ans. La corde frottée y tient son régime de Helmholtz, celui qui distingue un archet d'un simple résonateur. Six opcodes : corde frottée (wgbow), clarinette (wgclar), flûte (wgflute), cuivre (wgbrass), corde pincée (wgpluck2) et formants (fof2). Les trois réglages — Pression, Position, Vibrato — n'ont pas le même sens d'un instrument à l'autre : Pression est la pression d'archet du violon, la raideur d'anche de la clarinette, le souffle de la flûte, la tension des lèvres du cuivre, et la réflexion de la corde pincée, laquelle décide de sa durée. Position est le point de contact de l'archet, le rapport du jet d'air, le temps d'attaque ou la fréquence du formant, et c'est le réglage le plus sensible de la plupart d'entre eux. Les gains de sortie sont corrigés instrument par instrument : wgclar rend douze fois moins fort que wgbow à réglages comparables, et sans cette correction le volume changerait à chaque instrument.", en: "Csound's physical-model instruments, adjustable without writing a line of code. These are Perry Cook's and Julius Smith's models, carried into Csound and debugged for thirty years. The bowed string holds its Helmholtz regime, the thing that separates a bow from a mere resonator. Six opcodes: bowed string (wgbow), clarinet (wgclar), flute (wgflute), brass (wgbrass), plucked string (wgpluck2) and formants (fof2). The three controls — Pressure, Position, Vibrato — do not mean the same thing from one instrument to the next: Pressure is the violin's bow pressure, the clarinet's reed stiffness, the flute's breath, the brass's lip tension, and the plucked string's reflection, which sets its decay. Position is the bow's contact point, the air jet ratio, the attack time or the formant frequency, and it is the most sensitive control of most of them. Each opcode's output gain is corrected: wgclar is twelve times quieter than wgbow at comparable settings, and without that correction the volume would change with every instrument." },
  "csound-spectral": { fr: "Les traitements spectraux de Csound. Les opcodes en « pvs » travaillent sur un flux spectral et non sur des trames qu'on se passe à la main : pvsanal analyse, l'opcode transforme, pvsynth resynthétise, et l'on écrit une chaîne de morphing en quatre lignes. Trois traitements. Le croisement (pvscross) garde les fréquences du premier son et lui impose les niveaux du second : une voix qui prend la dynamique d'une batterie. Le vocodeur (pvsvoc) fait l'inverse — le premier donne son enveloppe spectrale, donc ses formants, le second son excitation : c'est le vocodeur au sens propre, celui de la voix robotique, mais fait dans le domaine spectral et non par banc de filtres. L'étirement (mincer) allonge un son sans changer sa hauteur et la change sans toucher à la durée, à phase verrouillée, ce qui évite le chuintement des étirements naïfs. La taille de fenêtre est l'arbitrage habituel : grande, la résolution fréquentielle est fine mais les transitoires s'étalent ; petite, l'inverse. Deux opcodes voisins ne sont pas proposés : partikkel, dont les quarante-et-un arguments n'ont pas abouti, et pvsmorph, qui compile et se termine sans rien écrire.", en: "Csound's spectral processes. The « pvs » opcodes work on a spectral stream rather than on frames passed by hand: pvsanal analyses, the opcode transforms, pvsynth resynthesises, and a morphing chain is written in four lines. Three processes. The cross (pvscross) keeps the first sound's frequencies and imposes the second's levels: a voice taking on a drum kit's dynamics. The vocoder (pvsvoc) does the opposite — the first gives its spectral envelope, hence its formants, the second its excitation: this is the vocoder proper, the robot-voice one, but done in the spectral domain rather than with a filter bank. The stretch (mincer) lengthens a sound without changing its pitch and changes its pitch without touching its length, phase-locked, which avoids the smearing of naive stretches. The window size is the usual trade-off: large gives fine frequency resolution but smeared transients; small the opposite. Two neighbouring opcodes are not offered: partikkel, whose forty-one arguments did not come out, and pvsmorph, which compiles and finishes without writing anything." },
  "tonnetz": { fr: "Enchaîne les accords par les transformations néo-riemanniennes. Hugo Riemann a dessiné à la fin du XIXᵉ siècle un réseau où les triades majeures et mineures forment des triangles adjacents — le Tonnetz —, et Richard Cohn en a tiré dans les années 1990 un outil d'analyse pour la musique où les accords s'enchaînent sans que la tonalité les explique : Wagner, Liszt, Schubert tardif, et par extension beaucoup de musique de film. Tout repose sur trois opérations, et chacune ne déplace qu'une seule voix.\n\nP échange majeur et mineur sur la même fondamentale en bougeant la tierce d'un demi-ton : do majeur devient do mineur. L bouge d'un demi-ton la note qui n'appartient pas à l'accord voisin : do majeur devient mi mineur. R bouge d'un ton : do majeur devient la mineur. C'est ce qu'on appelle la conduite parcimonieuse, et c'est la raison pour laquelle ces enchaînements sonnent liés alors qu'ils n'ont aucun rapport tonal — entre deux accords voisins, deux notes sur trois ne bougent pas du tout.\n\nLe composant place d'ailleurs les voix pour que cela s'entende : sans cela, on aurait des accords en position fondamentale qui sautent d'un bout du clavier à l'autre, et la parcimonie resterait théorique. Le mode « Chemin » cherche le plus court trajet entre deux accords, ce qui donne une mesure de distance qu'aucune analyse tonale ne fournit : mesuré sur les 576 couples de triades, deux accords quelconques sont toujours à cinq opérations au plus. Do majeur et sol dièse mineur, qui n'ont aucune note commune, ne sont qu'à trois — c'est le pôle hexatonique, et c'est le genre de voisinage que le Tonnetz révèle et que le cycle des quintes cache.", en: "Chains chords through the neo-Riemannian transformations. Hugo Riemann drew, at the end of the 19th century, a network in which major and minor triads form adjacent triangles — the Tonnetz — and Richard Cohn turned it in the 1990s into an analytical tool for music where chords follow one another without tonality explaining them: Wagner, Liszt, late Schubert, and by extension much film music. Everything rests on three operations, and each moves a single voice.\n\nP swaps major and minor on the same root by moving the third a semitone: C major becomes C minor. L moves by a semitone the note not belonging to the neighbouring chord: C major becomes E minor. R moves by a whole tone: C major becomes A minor. This is called parsimonious voice leading, and it is why these progressions sound connected although they have no tonal relation — between two neighbouring chords, two notes out of three do not move at all.\n\nThe node places the voices so that this can be heard: without it, root-position chords would jump from one end of the keyboard to the other and the parsimony would stay theoretical. The « Path » mode finds the shortest route between two chords, which gives a distance no tonal analysis provides: measured over the 576 pairs of triads, any two chords are at most five operations apart. C major and G sharp minor, which share no note, are only three apart — the hexatonic pole, and exactly the kind of neighbourhood the Tonnetz reveals and the circle of fifths hides." },
  "contrepoint-especes": { fr: "Vérifie un contrepoint de première espèce. Ce composant corrige au lieu de produire. Johann Joseph Fux a publié en 1725 le « Gradus ad Parnassum », où le contrepoint s'apprend par espèces : à la première, une note contre une note, ce qui isole la question de l'harmonie et du mouvement entre deux voix sans que le rythme s'en mêle. Haydn, Mozart et Beethoven l'ont tous travaillé, et les règles n'ont pas changé depuis. Elles tiennent en peu de choses et chacune se vérifie mécaniquement : seules les consonances sont admises — et la quarte n'en est pas une à deux voix, ce qui surprend toujours —, les quintes et octaves parallèles sont interdites, ainsi que celles atteintes par mouvement semblable, on commence et l'on finit sur une consonance parfaite, les grands sauts se compensent par un mouvement contraire conjoint, et la cadence se fait par mouvement contraire vers l'octave. Le composant ne réécrit rien : il annote, en séparant les interdictions des simples recommandations. C'est ce que fait un professeur, et c'est plus utile qu'une correction automatique, qui priverait de la seule chose qui compte — comprendre pourquoi la règle existe. L'exercice proposé par défaut est juste : le composant ne doit rien y trouver, et c'est le premier test du module. Un vérificateur trop zélé est inutilisable, puisqu'on cesse de le lire.", en: "Checks a first-species counterpoint. Johann Joseph Fux published in 1725 the « Gradus ad Parnassum », where counterpoint is learned by species: in the first, note against note, which isolates the question of harmony and motion between two voices without rhythm interfering. Haydn, Mozart and Beethoven all worked through it, and the rules have not changed since. They amount to few things and each can be checked mechanically: only consonances are allowed — and the fourth is not one in two voices, which always surprises — parallel fifths and octaves are forbidden, as are those reached by similar motion, one begins and ends on a perfect consonance, large leaps are answered by contrary stepwise motion, and the cadence is by contrary motion to the octave. The node rewrites nothing: it annotates, separating prohibitions from mere recommendations. That is what a teacher does, and it is more useful than an automatic correction, which would deprive one of the only thing that matters — understanding why the rule exists. The exercise offered by default is correct: the node must find nothing in it, and that is the module's first test. An over-zealous checker is unusable, since one stops reading it." },
  "canon-pavage": { fr: "Construit un canon rythmique par pavage. Un canon ordinaire superpose une mélodie à elle-même, décalée. Un canon par pavage ajoute une contrainte d'une sévérité arithmétique : à chaque pulsation du cycle, une voix et une seule doit frapper — jamais deux ensemble, jamais aucune. Le motif et les entrées des voix s'emboîtent donc exactement, comme des carreaux qui couvrent le sol sans trou ni recouvrement. La question remonte aux années 1950 en mathématiques (Hajós, de Bruijn) ; Dan Tudor Vuza l'a reformulée musicalement en 1991, et Moreno Andreatta et Emmanuel Amiot l'ont implémentée à l'IRCAM dans OpenMusic. La recherche des entrées se fait par couverture exacte : on prend la plus petite pulsation encore libre — quelqu'un doit bien la frapper —, on essaie chaque façon d'y poser une voix, et l'on recommence ; aucune branche n'est oubliée. Le cas le plus recherché est celui où NI le motif NI les entrées ne sont périodiques : un canon de Vuza. Ces canons-là n'existent qu'à partir d'un cycle de 72 pulsations, tout pavage plus court ayant une régularité cachée — le composant le vérifie et le dit dans son rapport. Chaque voix reçoit une hauteur différente : à hauteur unique on n'entendrait qu'une pulsation régulière, ce qu'est justement tout canon par pavage, sans entendre qu'elle est partagée.", en: "Builds a rhythmic tiling canon. An ordinary canon layers a melody over itself, offset. A tiling canon adds a constraint of arithmetical severity: at each pulse of the cycle, one voice and one only must strike — never two together, never none. The motif and the voice entries therefore interlock exactly, like tiles covering a floor with no gap and no overlap. The question goes back to the 1950s in mathematics (Hajós, de Bruijn); Dan Tudor Vuza restated it musically in 1991, and Moreno Andreatta and Emmanuel Amiot implemented it at IRCAM in OpenMusic. The entries are found by exact cover: take the smallest still-free pulse — someone has to strike it — try every way of placing a voice there, and repeat; no branch is missed. The most sought-after case is the one where neither the motif nor the entries are periodic: a Vuza canon. Those exist only from a cycle of 72 pulses upwards, every shorter tiling having a hidden regularity — the node checks this and says so in its report. Each voice takes a different pitch: on a single pitch one would hear only a steady pulse, which is exactly what every tiling canon is, without hearing that it is shared." },
  "serie-infinie": { fr: "Engendre la série de l'infini de Per Nørgård, découverte en 1959 et matière entière de sa Deuxième Symphonie (1970). Sa définition tient en trois lignes : s(0) = 0, s(2n) = −s(n), s(2n+1) = s(n) + 1. Les premiers termes sont 0, 1, −1, 2, 1, 0, −2, 3, −1, 2, 0, 1, 2, −1, −3, 4… et la suite ne se répète jamais. Elle est pourtant auto-similaire, et d'une façon exacte plutôt qu'approchée : une note sur deux redonne la série inversée, une note sur quatre redonne la série elle-même, à l'identique.\n\nOn peut donc superposer la mélodie à sa propre version quatre fois plus lente et obtenir un contrepoint parfaitement cohérent — c'est exactement ce que fait Nørgård, et c'est pourquoi sa symphonie peut être une seule mélodie du début à la fin sans jamais sonner répétitive. Le réglage « Voix » fait précisément cela, et ce n'est donc pas un effet de superposition : la voix lente est la même mélodie. Deux lectures sont proposées, qui changent tout le caractère sans toucher à la structure : en demi-tons, la suite se déploie chromatiquement et sort de toute tonalité, ce qui est la lecture de Nørgård ; en degrés, chaque entier compte un degré de la gamme et le résultat reste tonal.\n\nLa suite n'est pas bornée mais monte lentement — mille termes tiennent dans une vingtaine de degrés —, et les hauteurs qui sortiraient du clavier sont repliées à l'octave. Elle est cataloguée A004718 dans l'encyclopédie des suites d'entiers, ce qui permet de vérifier ses premiers termes hors d'ici.", en: "Generates Per Nørgård's infinity series, discovered in 1959 and the entire material of his Second Symphony (1970). Its definition fits in three lines: s(0) = 0, s(2n) = −s(n), s(2n+1) = s(n) + 1. The first terms are 0, 1, −1, 2, 1, 0, −2, 3, −1, 2, 0, 1, 2, −1, −3, 4… and the sequence never repeats. It is nevertheless self-similar, and exactly rather than approximately: every second note gives back the inverted series, every fourth note gives back the series itself, identically.\n\nOne can therefore layer the melody over its own four-times-slower version and obtain a perfectly coherent counterpoint — which is exactly what Nørgård does, and why his symphony can be a single melody from beginning to end without ever sounding repetitive. The « Voices » setting does precisely that, and is therefore not a layering effect: the slow voice IS the same melody. Two readings are offered, which change the whole character without touching the structure: in semitones the sequence unfolds chromatically and leaves any key behind, which is Nørgård's reading; in degrees each integer counts a scale step and the result stays tonal.\n\nThe sequence is unbounded but rises slowly — a thousand terms fit within some twenty degrees — and pitches that would leave the keyboard are folded by octaves. It is catalogued as A004718 in the encyclopedia of integer sequences, which allows its first terms to be checked elsewhere than here." },
  "auto-similarite": { fr: "Dessine la forme d'un morceau et en détecte les articulations. Jonathan Foote a proposé en 1999 un procédé d'une simplicité désarmante, devenu la base de toute l'analyse de structure musicale. On découpe le morceau en trames, on décrit chacune par son chromagramme — quelles notes sonnent —, et l'on compare chaque trame à chaque autre. Le résultat est une image carrée, symétrique, à diagonale blanche : la matrice d'auto-similarité. On y lit la forme à l'œil nu, un carré clair étant un passage homogène et une diagonale décalée une répétition littérale.\n\nPour passer de l'image aux frontières, Foote fait glisser le long de la diagonale un noyau en damier : deux carrés clairs sur la diagonale, deux carrés sombres hors diagonale. Ce motif ne s'accorde bien qu'à un endroit où « avant » ressemble à « avant », « après » ressemble à « après », et où les deux ne se ressemblent pas — c'est-à-dire exactement une frontière. La courbe obtenue s'appelle la nouveauté, et ses pics sont les articulations. « Trame » est le réglage qui compte : courte, on voit le détail des accords ; longue, on voit les grandes sections.\n\nC'est l'échelle à laquelle on regarde la forme, et non un réglage de précision. Aux deux bouts du morceau, le noyau déborderait de la matrice : la courbe y est laissée à zéro plutôt que complétée par des valeurs inventées, qui feraient de fausses frontières là où il n'y a rien à détecter.", en: "Draws a piece's form and detects its boundaries. Jonathan Foote proposed in 1999 a disarmingly simple method that became the basis of all musical structure analysis. The piece is cut into frames, each described by its chromagram — which notes sound — and every frame is compared to every other. The result is a square, symmetric image with a white diagonal: the self-similarity matrix. The form can be read in it by eye, a bright square being a homogeneous passage and an offset diagonal a literal repetition. To go from the image to the boundaries, Foote slides a checkerboard kernel along the diagonal: two bright squares on the diagonal, two dark ones off it. That pattern only matches where « before » resembles « before », « after » resembles « after », and the two do not resemble each other — that is, exactly at a boundary. The resulting curve is called novelty, and its peaks are the articulations. « Frame » is the setting that matters: short, the chord detail shows; long, the large sections do. It is the scale at which the form is looked at, not a precision setting. At both ends of the piece the kernel would hang off the matrix: the curve is left at zero there rather than filled with invented values, which would create false boundaries where there is nothing to detect." },
  "synthese-scanning": { fr: "Synthèse par scanning, d'après Bill Verplank, Max Mathews et Rob Shaw (CCRMA, 2000). L'idée est étrange et tient en deux phrases. On simule un objet mécanique — ici une chaîne de masses reliées par des ressorts, fermée en anneau — à une cadence lente, quelques centaines de pas par seconde, si bien que son mouvement est à l'échelle du geste : quelques hertz, comme une corde qu'on regarderait au ralenti. Puis on lit la forme de cet objet, masse par masse, comme une table d'onde, à la fréquence audio qu'on veut entendre.\n\nLa conséquence est tout l'intérêt du procédé : la hauteur et le timbre sont entièrement séparés. La hauteur ne dépend que de la vitesse de balayage, la forme d'onde ne dépend que de la mécanique, et elle évolue donc continûment, sans jamais se répéter, pendant que la note reste juste. Aucun oscillateur à table d'onde ordinaire ne fait cela, puisque sa table est figée — et l'on peut s'en convaincre ici en mettant la tension à zéro : la chaîne se fige et l'on retrouve exactement un oscillateur ordinaire.\n\nMax Mathews, qui avait écrit le premier programme de synthèse en 1957, voyait dans le scanning l'aboutissement de sa recherche d'un timbre vivant sans échantillon. Rien n'entretient le mouvement : c'est donc l'excitation de départ qui décide de tout le son, comme la façon de pincer une corde, et « Pincée » donne un déplacement sans vitesse là où « Frappée » donne une vitesse sans déplacement. La table est interpolée dans le temps entre deux pas de mécanique, sans quoi elle changeait d'un coup et faisait entendre une raie à la cadence de simulation — mesuré, un la 110 se faisait dominer par une composante à 1 kHz qui n'était que cet artefact.", en: "Scanned synthesis, after Bill Verplank, Max Mathews and Rob Shaw (CCRMA, 2000). The idea is strange and fits in two sentences. A mechanical object is simulated — here a chain of masses joined by springs, closed into a ring — at a slow rate, a few hundred steps per second, so that its motion is on the scale of a gesture: a few hertz, like a string filmed in slow motion. Then the shape of that object is read, mass by mass, as a wavetable, at whatever audio frequency one wants to hear.\n\nThe consequence is the whole point: pitch and timbre are entirely separate. The pitch depends only on the scanning speed, the waveform only on the mechanics, and it therefore evolves continuously, never repeating, while the note stays in tune. No ordinary wavetable oscillator does this, since its table is frozen — and one can check that here by setting the tension to zero: the chain freezes and an ordinary oscillator is exactly what comes back. Max Mathews, who wrote the first synthesis program in 1957, saw scanning as the culmination of his search for a living timbre without samples.\n\nNothing sustains the motion: it is therefore the initial excitation that decides the whole sound, like the way a string is plucked, and « Plucked » gives displacement without velocity where « Struck » gives velocity without displacement. One implementation detail that was audible: the table is interpolated in time between two mechanical steps, without which it changed all at once and rang at the simulation rate — measured, an A 110 was dominated by a 1 kHz component that was nothing but that artefact." },
  "terrain-onde": { fr: "Synthèse par terrain d'onde. Un oscillateur à table d'onde lit une courbe à une dimension ; celui-ci en lit une à deux : une surface z = f(x, y), parcourue par une orbite qui s'y promène, le son étant l'altitude du terrain sous l'orbite. L'idée vient des années 1970 (Bischoff, Gold, Horton ; Mitsuhashi, 1982) et Curtis Roads en donne l'exposé de référence dans « The Computer Music Tutorial ». Les rôles sont séparés : l'orbite décide de la période, donc de la hauteur ; le terrain décide de la forme d'onde, donc du timbre.\n\nÉlargir l'orbite sur un terrain accidenté change tout le spectre sans toucher à la note, et une orbite qui dérive fait évoluer le timbre indéfiniment. Deux conséquences surprennent, et toutes deux sont de la géométrie et non des défauts. La symétrie du terrain multiplie la fréquence : sur une selle z = x² − y², un tour d'orbite passe deux fois par le même relief, et l'on entend donc l'octave au-dessus de la vitesse de rotation — la demi-période s'y répète, alors que sur le terrain classique elle ne se répète pas.\n\nEt un terrain fait de cercles concentriques est constant le long d'un cercle centré : il ne donne alors aucun son, et il faut décaler le centre de l'orbite pour l'entendre. Le terrain « Classique » est celui que Mitsuhashi donne en exemple et que toute la littérature reprend ; il est creusé le long des droites x = ±1 et y = ±1, et aussi le long de la diagonale, ce qui fait que son relief est très inégal selon la zone explorée — d'où l'importance du rayon et du centre.", en: "Wave terrain synthesis. A wavetable oscillator reads a one-dimensional curve; this one reads a two-dimensional one: a surface z = f(x, y), travelled by an orbit that wanders over it, the sound being the terrain's altitude under the orbit. The idea dates from the 1970s (Bischoff, Gold, Horton; Mitsuhashi, 1982) and Curtis Roads gives the reference account in « The Computer Music Tutorial ». The roles are separate: the orbit decides the period, hence the pitch; the terrain decides the waveform, hence the timbre.\n\nWidening the orbit over rugged terrain changes the whole spectrum without touching the note, and a drifting orbit evolves the timbre indefinitely. Two consequences surprise, and both are geometry rather than defects. The terrain's symmetry multiplies the frequency: on a saddle z = x² − y², one turn of the orbit passes twice over the same relief, so one hears the octave above the rotation speed — the half-period repeats there, where on the classic terrain it does not.\n\nAnd a terrain of concentric circles is constant along a centred circle: it then gives no sound at all, and the orbit's centre must be offset to hear it. The « Classic » terrain is the one Mitsuhashi gives as an example and the whole literature reuses; it is hollowed along the lines x = ±1 and y = ±1, and along the diagonal too, so its relief is very uneven from area to area — hence the importance of the radius and the centre." },
  "voyelle-fof": { fr: "Voyelle chantée par synthèse de formants. Une voyelle n'est pas une forme d'onde, c'est une configuration de résonances : le conduit vocal est un tuyau dont la langue et les lèvres changent la géométrie, et cette géométrie place trois ou quatre bosses dans le spectre — les formants. Ce sont eux, et eux seuls, qui distinguent un A d'un I, la hauteur de la voix n'y étant pour rien : c'est bien pourquoi on reconnaît la même voyelle chantée grave ou aiguë.\n\nXavier Rodet a proposé en 1984, avec le programme chant de l'IRCAM, de synthétiser cela directement : au lieu de filtrer une source, on additionne les réponses impulsionnelles des formants. Chaque formant produit une bouffée — une sinusoïde à sa fréquence sous une enveloppe qui monte vite et décroît selon sa largeur de bande — et l'on redéclenche toutes ces bouffées à chaque période de la fondamentale ; elles se chevauchent, et c'est ce chevauchement qui fait la résonance continue.\n\nC'est la FOF, « Fonction d'Onde Formantique ». La conséquence est celle qu'on veut : changer la note ne déplace pas les formants, là où transposer un échantillon de voix les emporte avec lui et donne le fameux effet « Chipmunk ». Le réglage « Taille du conduit » fait justement l'inverse : il déplace les formants sans toucher à la note, ce qui revient à changer la taille du chanteur. Les fréquences employées sont celles de Peterson et Barney (1952), la table la plus citée de la phonétique, mesurée sur des voix d'hommes.\n\n« Instabilité » est ce qui empêche le résultat de sonner comme un orgue : une vraie voix n'est jamais exactement périodique, et quelques millièmes de variation d'une période à l'autre suffisent à la rendre vivante.", en: "Sung vowel by formant synthesis. A vowel is not a waveform, it is a configuration of resonances: the vocal tract is a tube whose geometry the tongue and lips change, and that geometry places three or four bumps in the spectrum — the formants. They, and they alone, tell an A from an I; the pitch of the voice plays no part, which is exactly why the same vowel is recognisable sung low or high. Xavier Rodet proposed in 1984, with IRCAM's chant program, to synthesise this directly: instead of filtering a source, the formants' impulse responses are added.\n\nEach formant produces a burst — a sinusoid at its frequency under an envelope that rises fast and decays according to its bandwidth — and all these bursts are retriggered at every period of the fundamental; they overlap, and that overlap is what makes the continuous resonance. This is FOF, « Fonction d'Onde Formantique ». The consequence is the one wanted: changing the note does not move the formants, where transposing a voice sample carries them along and gives the famous « Chipmunk » effect.\n\nThe « Tract size » control does precisely the opposite: it moves the formants without touching the note, which amounts to changing the singer's size. The frequencies used are Peterson and Barney's (1952), the most cited table in phonetics, measured on men's voices. « Jitter » is what stops the result sounding like an organ: a real voice is never exactly periodic, and a few thousandths of variation from one period to the next are enough to make it alive." },
  "mosaiquage": { fr: "Mosaïquage audio, ou synthèse concaténative par corpus. Le principe est celui d'une mosaïque : on découpe un corpus — n'importe quel son, une collection d'échantillons, un disque entier — en petits grains, on décrit chacun par quelques chiffres, on décrit de la même façon les grains d'un son cible, et l'on remplace chaque grain de la cible par celui du corpus qui lui ressemble le plus. Le résultat a la forme de la cible et la matière du corpus : une phrase parlée jouée avec des cordes de piano, une batterie reconstruite avec des bruits de porte.\n\nC'est le procédé que Diemo Schwarz a formalisé à l'IRCAM (CataRT, 2006). Le composant fait l'appariement entre descripteurs, similarité et échantillons. Trois descripteurs sont employés, et ils sont volontairement lisibles, de sorte qu'on puisse dire pourquoi tel grain a été choisi : le niveau, le centre de gravité du spectre, et le taux de passages par zéro qui distingue un son bruité d'un son tenu. Ils sont normalisés avant comparaison, sans quoi la distance ne verrait que le centre de gravité, qui se compte en milliers quand les autres valent moins de un.\n\n« Éviter les répétitions » traite le défaut le plus audible du procédé : un corpus trop pauvre rend cent fois le même grain, ce qui s'entend comme un bourdonnement — et le rapport de sortie le dit franchement quand cela arrive. « Taille des grains » est l'arbitrage principal : courts, les grains suivent la cible de près mais perdent le caractère du corpus ; longs, on reconnaît le corpus mais la cible se devine à peine. Le recollage se fait par fenêtres qui se recouvrent de moitié, dont la somme vaut exactement un : un corpus identique à la cible la reconstruit donc à mieux que 2 % près.", en: "Audio mosaicing, or corpus-based concatenative synthesis. The principle is a mosaic's: a corpus — any sound, a sample collection, a whole record — is cut into small grains, each described by a few numbers, the grains of a target sound are described the same way, and each target grain is replaced by the corpus grain that most resembles it. The result has the target's shape and the corpus's material: a spoken phrase played with piano strings, a drum track rebuilt from door noises.\n\nThis is the method Diemo Schwarz formalised at IRCAM (CataRT, 2006). Three descriptors are used, deliberately legible so that one can say why a grain was chosen: loudness, the spectral centre of gravity, and the zero-crossing rate that tells a noisy sound from a steady one. They are normalised before comparison, without which the distance would see only the centre of gravity, counted in thousands where the others are below one. « Avoid repeats » deals with the method's most audible defect: too poor a corpus returns the same grain a hundred times, which sounds like a drone — and the output report says so plainly when it happens.\n\n« Grain size » is the main trade-off: short grains follow the target closely but lose the corpus's character; long ones make the corpus recognisable but the target barely shows. The joining uses windows overlapping by half, whose sum is exactly one: a corpus identical to the target therefore rebuilds it to better than 2 %." },
  "secoueurs": { fr: "Percussions secouées par modèle stochastique de particules. Perry Cook a posé le problème à l'envers de la synthèse ordinaire : pour une maraca, on pourrait résoudre le mouvement de chaque grain dans la calebasse — c'est ce qu'il a fait —, mais le résultat est trop lourd et surtout inutile, car l'oreille n'entend pas les trajectoires, elle entend une statistique. Il n'a donc gardé de ses simulations que deux nombres : la probabilité qu'une collision se produise à un instant donné, et la vitesse à laquelle l'énergie du système retombe.\n\nC'est le PhISEM (« Physically Informed Stochastic Event Modeling », 1996-97), et il tient en quinze lignes. Le modèle a trois étages : l'énergie monte à chaque secousse et retombe, une collision se produit avec une probabilité proportionnelle à cette énergie et au nombre de particules, et la bouffée de bruit qu'elle dépose passe dans des résonateurs qui sont la seule chose distinguant vraiment un instrument d'un autre. « Énergie » ne règle donc pas le volume : plus elle est grande, plus les collisions sont probables, donc plus le grain est dense — c'est un paramètre physique et non un gain.\n\n« Particules » est le réglage qui transforme un crépitement compté en chuintement continu : la cabasa engendre plus de cinq fois les collisions d'une maraca à énergie égale, et c'est tout ce qui les sépare. Un MIDI branché en entrée fait de chaque note une secousse, dont la vélocité devient l'énergie. À graine fixée, le son se rejoue à l'identique, ce qu'aucun vrai tambourin ne fait et dont un graphe qu'on relance a besoin.", en: "Shaken percussion from a stochastic particle model. Perry Cook posed the problem the opposite way round to ordinary synthesis: for a maraca one could solve the motion of every seed in the gourd — and he did — but the result is too heavy and, above all, useless, because the ear does not hear trajectories, it hears a statistic. So from his simulations he kept only two numbers: the probability that a collision occurs at a given instant, and the rate at which the system's energy falls.\n\nThat is PhISEM (« Physically Informed Stochastic Event Modeling », 1996-97), and it fits in fifteen lines. The model has three stages: energy rises with each shake and falls back, a collision occurs with a probability proportional to that energy and to the number of particles, and the burst of noise it deposits passes through resonators, which are the only thing that really tells one instrument from another. « Energy » therefore does not set the volume: the greater it is, the likelier the collisions, hence the denser the grain — it is a physical parameter, not a gain.\n\n« Particles » is the setting that turns a countable rattle into a continuous hiss: measured, the cabasa produces more than five times a maraca's collisions at equal energy, and that is all that separates them. A MIDI file on the input turns each note into a shake whose velocity becomes the energy. With a fixed seed the sound replays identically, which no real tambourine does and which a graph you re-run needs." },
  "vent-guide-onde": { fr: "Clarinette, flûte ou cuivre par guide d'onde numérique. Un instrument à vent n'est pas un oscillateur muni d'un filtre : c'est un tuyau dans lequel une onde de pression fait l'aller-retour, et une anche — ou un jet d'air — qui décide, à chaque retour, de ce qu'elle laisse passer. Julius Smith a montré dans les années 1980 qu'une simple ligne de retard bouclée et une non-linéarité à son entrée suffisaient à le simuler ; Perry Cook en a tiré les instruments du Synthesis ToolKit, dont ce composant s'inspire.\n\nL'intérêt n'est pas l'économie de calcul mais le comportement : le son met un temps à s'établir, l'instrument refuse de parler si l'on souffle trop peu, et le timbre change avec la dynamique au lieu de changer seulement de volume. Rien de cela n'est programmé comme un effet, tout tombe du modèle. La clarinette a un tuyau fermé à un bout, ce qui inverse la réflexion et ne laisse vivre que les harmoniques impairs : mesuré, les pairs pèsent 0,4 % des impairs, et c'est là toute sa couleur creuse.\n\nSous 40 % de pression, son anche ne s'établit pas et il ne sort qu'un bruit de souffle — comportement d'une vraie anche, pas défaut du composant. La flûte est presque sinusoïdale, le vent le plus pauvre en harmoniques. Le cuivre s'éclaircit franchement quand on souffle fort, parce que l'onde se raidit en se propageant : le centre de gravité de son spectre passe de 1020 à 3393 Hz entre 20 % et 100 % de pression. Deux corrections ont été trouvées par la mesure et méritent d'être dites, parce qu'elles expliquent ce que le composant fait : le retard du filtre de pertes est compensé, sans quoi la clarinette rendait 218 Hz pour 220 demandés ; et le tuyau de la flûte et du cuivre est amorcé à la note visée, sans quoi le modèle choisissait seul son partiel et un la 440 pouvait sortir à 164 Hz — exactement le problème d'un débutant qui n'a pas encore l'embouchure.\n\nUne limite assumée : le modèle de flûte ne tient sa hauteur qu'au-dessus de 85 % de pression, si bien que son réglage de pression est ramené dans cette plage et n'agit que sur la dynamique.", en: "Clarinet, flute or brass by digital waveguide. A wind instrument is not an oscillator with a filter on it: it is a bore in which a pressure wave travels back and forth, and a reed — or an air jet — that decides, at each return, what it lets through. Julius Smith showed in the 1980s that a single looped delay line with a nonlinearity at its input was enough to simulate this; Perry Cook drew the Synthesis ToolKit instruments from it, which this node follows.\n\nThe point is not cheap computation but behaviour: the sound takes time to settle, the instrument refuses to speak if blown too gently, and the timbre changes with dynamics instead of only the volume. None of that is programmed as an effect; it all falls out of the model. The clarinet's bore is closed at one end, which inverts the reflection and lets only odd harmonics live: measured, the even ones weigh 0.4 % of the odd, and that is its whole hollow colour.\n\nBelow 40 % pressure its reed does not start and only breath noise comes out — a real reed's behaviour, not a defect of the node. The flute is nearly sinusoidal, the wind poorest in harmonics. The brass brightens markedly when blown hard, because the wave steepens as it travels: measured, its spectral centre of gravity moves from 1020 to 3393 Hz between 20 % and 100 % pressure. Two corrections were found by measurement and are worth stating, because they explain what the node does: the loss filter's delay is compensated, without which the clarinet gave 218 Hz for 220 asked; and the flute's and brass's bore is primed at the target note, without which the model picked its own partial and an A 440 could come out at 164 Hz — exactly a beginner's problem, embouchure not yet formed.\n\nOne accepted limit: the flute model only holds its pitch above 85 % pressure, so its pressure setting is remapped into that range and acts on dynamics only." },
  "barre-modale": { fr: "Percussions à sons définis par synthèse modale. Une barre ne vibre pas comme une corde. Une corde a des partiels entiers — 1, 2, 3, 4 — parce qu'elle vibre en une dimension sous tension ; une barre libre vibre en flexion, et ses modes propres tombent sur 1, puis 2,756, puis 5,404, puis 8,933. Ces rapports non entiers sont un résultat d'acoustique publié, et ce sont eux qui donnent au glockenspiel sa couleur métallique. Les facteurs d'instruments les corrigent exprès : creuser une arche sous une barre de marimba abaisse son deuxième mode jusqu'à quatre fois le premier et le troisième vers dix, si bien que la barre devient harmonique, donc musicale.\n\nLa cloche tubulaire va plus loin — ses partiels sont vers 2, 3, 4,16 et 5,43, de sorte que la note qu'on entend n'existe pas dans le son : c'est une fondamentale absente, que l'oreille reconstruit, et le spectre du composant n'en porte effectivement aucune trace. Le bol tibétain, lui, doit sa voix à deux modes presque confondus, à 1 et 1,02, dont l'écart produit un battement lent. « Dureté du maillet » est le réglage qui change le plus le timbre, et pour une raison physique : un maillet dur donne une impulsion courte, donc riche en aigus, qui réveille les modes hauts, là où un maillet mou ne réveille que le premier.\n\nUn mode dont la fréquence dépasserait la moitié de la fréquence d'échantillonnage est simplement abandonné, plutôt que replié dans le grave où il sonnerait faux. Un MIDI branché en entrée fait de chaque note un coup de maillet, et les coups se superposent — c'est ce qui donne le halo d'un vibraphone.", en: "Definite-pitched percussion by modal synthesis. A bar does not vibrate like a string. A string has integer partials — 1, 2, 3, 4 — because it vibrates in one dimension under tension; a free bar vibrates in flexion, and its natural modes land on 1, then 2.756, then 5.404, then 8.933. Those non-integer ratios are a published acoustics result, and they are what give the glockenspiel its metallic colour. Instrument makers correct them deliberately: carving an arch under a marimba bar lowers its second mode to four times the first and its third towards ten, so the bar becomes harmonic, hence musical.\n\nThe tubular bell goes further — its partials sit around 2, 3, 4.16 and 5.43, so the note one hears does not exist in the sound: it is a missing fundamental the ear reconstructs, and the node's spectrum indeed carries no trace of it. The Tibetan bowl owes its voice to two nearly coincident modes, at 1 and 1.02, whose spacing produces a slow beating. « Mallet hardness » is the setting that changes the timbre most, and for a physical reason: a hard mallet gives a short impulse, hence rich in highs, which wakes the upper modes, whereas a soft one wakes only the first.\n\nA mode whose frequency would exceed half the sampling rate is simply dropped rather than folded down into the bass where it would sound wrong. A MIDI file on the input turns each note into a mallet stroke, and the strokes overlap — which is what gives a vibraphone its halo." },
  "serie-dodecaphonique": { fr: "Joue les quatre formes d'une série et écrit sa matrice. Le dodécaphonisme est une technique de calcul avant d'être une esthétique : une série des douze hauteurs, et quatre transformations — l'originale, le rétrograde, l'inversion, et le rétrograde de l'inversion —, chacune transposable sur douze degrés, soit quarante-huit formes tirées d'un seul matériau. Schoenberg, Webern et Berg les écrivaient à la main dans une grille de douze sur douze ; c'est cette grille que la sortie texte donne, étiquetée P et I, avec les rétrogrades qui se lisent à l'envers.\n\nElle se contrôle du coup d'œil qu'on apprenait au conservatoire : la première ligne est la série, la première colonne son inversion, et la diagonale ne change jamais. Rien de tout cela n'est réservé au sérialisme — rétrograder et inverser un motif sont des opérations de contrepoint aussi vieilles que le canon, et le composant accepte une suite de n'importe quelle longueur. Il dit seulement, en passant, si ce qu'on lui a donné est une vraie série : douze classes distinctes.\n\n« Registre » décide de la façon de jouer les classes obtenues : « Serré » prend à chaque note l'octave la plus proche de la précédente, et l'on entend une ligne — c'est ainsi qu'une série se joue réellement, les octaves étant libres ; « Une octave » range tout au-dessus de la note de départ, et l'on entend l'ordre des classes. La série par défaut est celle du Concerto pour violon de Berg, faite de tierces alternées qui la rendent presque tonale.", en: "Plays a row's four forms and writes its matrix. Twelve-tone writing is a calculating technique before it is an aesthetic: a row of the twelve pitches, and four transformations — original, retrograde, inversion, retrograde inversion — each transposable onto twelve levels, so forty-eight forms drawn from a single material. Schoenberg, Webern and Berg wrote them out by hand in a twelve-by-twelve grid; that grid is what the text output gives, labelled P and I, with the retrogrades read backwards. It can be checked at a glance the way it was taught: the first row is the series, the first column its inversion, and the diagonal never changes. None of this is reserved for serialism — retrograding and inverting a motif are counterpoint operations as old as the canon, and the node accepts a sequence of any length. It merely states, in passing, whether what it was given is a real row: twelve distinct classes. « Register » decides how the resulting classes are played: « Closest » takes for each note the octave nearest the previous one, and one hears a line — which is how a row is actually played, the octaves being free; « One octave » stacks everything above the starting note, and one hears the order of the classes. The default row is that of Berg's Violin Concerto, built from alternating thirds that make it almost tonal." },
  "classes-hauteurs": { fr: "Analyse un accord ou un passage en ensemble de classes de hauteurs. Quand une harmonie n'est plus tonale, l'appeler « septième sur ré » n'a plus de sens ; l'analyse mise au point par Allen Forte et Milton Babbitt propose autre chose. On ramène l'accord aux classes qu'il emploie, puis on cherche la façon la plus compacte de les écrire : c'est la forme normale. On compare ensuite avec son inversion et l'on garde la plus serrée à gauche, ramenée à zéro : c'est la forme première, le nom de la famille.\n\nDeux accords qui ne se ressemblent pas sur le papier — un accord, le même renversé, transposé, retourné — y aboutissent ensemble, et l'on peut enfin dire que deux passages emploient le même matériau. Le vecteur d'intervalles dit la couleur : combien de secondes mineures, de secondes majeures, de tierces… l'ensemble contient. Un vecteur riche en quintes sonne ouvert, un vecteur riche en demi-tons sonne serré. Il ne suffit pourtant pas à nommer : les deux tétracordes « tous-intervalles » ont le même vecteur et des formes premières différentes — c'est la relation Z.\n\nLa symétrie par transposition explique pourquoi certains ensembles ne vont nulle part : l'accord diminué et la gamme par tons se retrouvent identiques à eux-mêmes après transposition, donc sans fonction tonale possible, et c'est le fondement du procédé chez Debussy et Messiaen. Deux limites, dites plutôt que tues. Les noms ne sont donnés que pour les ensembles catalogués ici — les douze trichordes au complet et les accords et gammes courants : recopier de mémoire les deux cents entrées de Forte serait prendre le risque d'étiqueter faux, ce qui est pire que de ne pas étiqueter, et la forme première suffit à identifier le reste.\n\nEt la forme première est calculée par la méthode dite du « plus serré à gauche », celle des manuels de Straus ; elle diffère de celle de Forte lui-même sur une poignée d'ensembles de cinq et six notes. « Accord par accord » analyse chaque groupe de notes simultanées et relève ensuite les formes premières qui reviennent.", en: "Analyses a chord or passage as a pitch-class set. When a harmony is no longer tonal, calling it « seventh on D » means nothing; the analysis developed by Allen Forte and Milton Babbitt offers something else. The chord is reduced to the classes it uses, then the most compact way of writing them is sought: that is the normal form. It is then compared with its inversion and the one most packed to the left is kept, brought to zero: that is the prime form, the family's name.\n\nTwo chords that look unrelated on paper — a chord, the same one inverted, transposed, turned over — end up together, and one can finally say that two passages use the same material. The interval vector gives the colour: how many minor seconds, major seconds, thirds… the set holds. A vector rich in fifths sounds open, one rich in semitones sounds tight. It is not enough to name, though: the two « all-interval » tetrachords share a vector and have different prime forms — the Z-relation.\n\nTranspositional symmetry explains why some sets go nowhere: the diminished chord and the whole-tone scale come back identical to themselves after transposition, hence without possible tonal function, and that is the basis of the procedure in Debussy and Messiaen. Two limits, stated rather than hidden. Names are given only for the sets catalogued here — the twelve trichords in full, and the common chords and scales: copying Forte's two hundred entries from memory would risk labelling wrongly, which is worse than not labelling, and the prime form is enough to identify the rest.\n\nAnd the prime form is computed by the « most packed to the left » method of Straus's textbooks; it differs from Forte's own on a handful of five- and six-note sets. « Chord by chord » analyses each group of simultaneous notes and then lists the prime forms that recur." },
  "harmonie-negative": { fr: "Réfléchit les hauteurs autour de l'axe tonique-dominante. L'idée vient de l'harmonie duale d'Hugo Riemann, reprise par Ernst Levy dans « A Theory of Harmony » (1985), et remise en circulation ces dernières années sous le nom d'harmonie négative. Si l'on réfléchit les douze hauteurs autour de l'axe placé à mi-chemin de la tonique et de sa dominante, chaque fonction tonale se change en son image, et l'on obtient une harmonie qui remplit le même rôle par le chemin opposé.\n\nEn do, l'axe tombe entre mi bémol et mi — il ne tombe sur aucune note du clavier, et n'a donc aucun point fixe : les douze classes s'échangent par six paires. La tonique devient la dominante, mi bémol et mi s'échangent, et do majeur ressort en do mineur. Le résultat célèbre est celui du sol septième, qui devient un fa mineur sixte : deux accords que rien ne rapproche sur le papier, et qui appellent tous deux la résolution sur do. La sortie texte donne les six paires, pour qu'on voie ce que la réflexion fait avant de l'écouter.\n\n« Réflexion » propose les deux lectures honnêtes du procédé. « Classes, registre gardé » réfléchit chaque note dans son octave : l'harmonie change, la ligne garde son contour, et c'est ce qu'on veut pour substituer un accord dans une progression. « Miroir vrai » réfléchit tout autour d'un seul axe absolu, placé au milieu du morceau : les intervalles changent de sens, donc la mélodie se retourne — ce qui est le vrai miroir, mais rarement ce qu'on cherche sur une ligne. Ce composant est un générateur, pas une règle : il propose une substitution, il ne dit pas qu'elle est bonne.", en: "Reflects pitches around the tonic-dominant axis. The idea comes from Hugo Riemann's dualist harmony, taken up by Ernst Levy in « A Theory of Harmony » (1985), and put back into circulation in recent years under the name negative harmony. Reflect the twelve pitches around the axis lying halfway between the tonic and its dominant, and every tonal function turns into its image, giving a harmony that fills the same role by the opposite path. In C, the axis falls between E flat and E — it falls on no note of the keyboard, and therefore has no fixed point: the twelve classes swap in six pairs.\n\nThe tonic becomes the dominant, E flat and E swap, and C major comes out as C minor. The famous result is G7, which becomes an F minor 6: two chords that nothing relates on paper, and which both call for resolution onto C. The text output gives the six pairs, so one sees what the reflection does before hearing it. « Reflection » offers the procedure's two honest readings. « Classes, register kept » reflects each note within its octave: the harmony changes, the line keeps its contour, and that is what one wants to substitute a chord inside a progression.\n\n« True mirror » reflects everything around a single absolute axis, placed in the middle of the piece: intervals change direction, so the melody turns over — which is the real mirror, but rarely what one is after on a melodic line. This node is a generator, not a rule: it offers a substitution, it does not say the substitution is good." },
  "voicings-accords": { fr: "Renverse, écarte et enchaîne les accords d'un fichier MIDI. Ce composant fait ce qu'on fait à la main. « Renversement » fait passer les notes basses au-dessus, une par une, sans changer l'accord — seulement qui le porte ; poussé jusqu'au nombre de notes, il rend l'accord inchangé plutôt que de faire monter la musique indéfiniment. « Disposition » répartit les voix : « Ouvert » monte une note sur deux d'une octave, et les « drop » descendent d'une octave la deuxième ou la troisième voix en partant du haut, ce qui creuse l'accord au milieu et lui donne la sonorité de la guitare jazz et des quatre cuivres — il faut au moins quatre notes, et sans elles l'accord sort inchangé.\n\n« Conduite des voix » est le réglage qui s'entend le plus. Entre do majeur et fa majeur, il existe une version qui déplace les trois voix de plusieurs tons et une qui n'en déplace qu'une d'un demi-ton ; la seconde s'entend comme une harmonie qui avance, la première comme deux accords sans rapport. Le composant cherche donc, pour chaque accord, le registre qui bouge le moins de voix depuis le précédent — par octaves entières seulement, afin que la disposition choisie plus haut soit conservée exactement.\n\nLe premier accord n'est jamais déplacé : c'est lui qui fixe le registre. La recherche est gloutonne, sans retour sur les choix passés : une recherche globale ferait parfois mieux d'un demi-ton, pour un coût exponentiel et un résultat qu'on n'entendrait pas.", en: "Inverts, spreads and chains a MIDI file's chords. This node does what one does by hand. « Inversion » moves the bottom notes above, one at a time, without changing the chord — only who carries it; pushed as far as the note count, it leaves the chord unchanged rather than driving the music ever upwards. « Voicing » spreads the voices: « Open » raises every other note by an octave, and the « drop » voicings lower the second or third voice from the top by an octave, which hollows the chord in the middle and gives it the sound of jazz guitar and four-part brass — it needs at least four notes, and without them the chord comes out unchanged. « Voice leading » is the setting one hears most. Between C major and F major there is a version that moves all three voices by several tones and one that moves a single voice by a semitone; the latter sounds like a harmony moving forward, the former like two unrelated chords. So the node looks, for each chord, for the register that moves the fewest voices from the previous one — by whole octaves only, so that the voicing chosen above is kept exactly. The first chord is never moved: it is the one that sets the register. The search is greedy, with no going back on past choices: a global search would sometimes do better by a semitone, at exponential cost and for a result one would not hear." },
  "motif-imposer-rythme": { fr: "Sépare les hauteurs du rythme, puis les remarie. La première entrée fournit une suite de hauteurs — une mélodie, une progression d'accords —, la seconde une grille de frappes, et chaque frappe reçoit la hauteur suivante de la suite, qui tourne en boucle quand la grille est plus longue. C'est l'opération que TidalCycles appelle « struct », et c'est elle qui rend le « Rythme euclidien » composable : un tresillo cubain devient la grille d'une suite d'accords, sans qu'on écrive un seul départ à la main. Ce qui vient de quel côté est explicite : les hauteurs n'apportent que les hauteurs, la grille apporte les départs, les durées et les vélocités — donc l'accentuation. Un accord de l'entrée Hauteurs est plaqué entier sur une frappe, il n'est pas égrené. La grille commande la longueur du résultat : elle ne se répète jamais d'elle-même, alors que les hauteurs, elles, se rejouent depuis le début autant de fois qu'il faut. Le canal de sortie est celui des hauteurs, ce qui permet de prendre la grille sur une piste de batterie sans que le résultat sorte en percussion.", en: "Separates pitch from rhythm, then marries them again. The first input supplies a sequence of pitches — a melody, a chord progression — the second a grid of onsets, and each onset takes the next pitch from the sequence, which cycles when the grid is longer. This is the operation TidalCycles calls « struct », and it is what makes « Euclidean Rhythm » composable: a Cuban tresillo becomes the grid for a chord sequence, without writing a single onset by hand. What comes from which side is explicit: Pitches contribute pitches only, the grid contributes onsets, durations and velocities — hence the accentuation. A chord on the Pitches input is struck whole on one onset, not spelled out. The grid governs the length of the result: it never repeats by itself, whereas the pitches replay from the start as many times as needed. The output channel is the pitches' one, so the grid can be taken from a drum track without the result coming out as percussion." },
  "motif-echo-notes": { fr: "Superpose des copies décalées du motif, chacune plus faible que la précédente. La différence avec un délai audio est entière : ce ne sont pas des répétitions d'un signal, ce sont des notes, qui s'écrivent dans le fichier MIDI et se transposent, se quantifient, se rejouent avec un autre instrument, se relisent dans une partition. Un délai se mixe ; celui-ci se compose. « Atténuation » est multiplicative : à 60 %, une note à 100 donne 60, puis 36, puis 22. La série s'arrête d'elle-même dès qu'une copie descendrait sous la vélocité 1, plutôt que d'écrire des notes muettes dans le fichier. « Transposition » se cumule d'une copie à l'autre : à +7, l'écho monte de quinte en quinte, et la série s'arrête net quand elle sortirait du clavier MIDI plutôt que de replier les notes n'importe où. Chaque note d'un accord est échouée, donc l'accord entier. À décalage court — un vingtième de seconde — l'effet n'est plus un écho mais un flam ; à décalage long et transposition nulle, c'est un canon avec soi-même.", en: "Layers time-shifted copies of the pattern, each weaker than the last. The difference from an audio delay is total: these are not repetitions of a signal, they are notes, written into the MIDI file, and they can be transposed, quantized, replayed with another instrument, read in a score. A delay is mixed in; this one composes. « Feedback » is multiplicative: at 60 %, a note at 100 gives 60, then 36, then 22. The series stops by itself as soon as a copy would fall below velocity 1, rather than writing silent notes into the file. « Transpose » accumulates from copy to copy: at +7, the echo climbs fifth by fifth, and the series stops dead when it would leave the MIDI range instead of folding notes back anywhere. Every note of a chord is echoed, hence the whole chord. At a short offset — a twentieth of a second — the effect is no longer an echo but a flam; at a long offset with no transposition, it is a canon with oneself." },
  "motif-eclaircir": { fr: "Retire une part des notes au hasard, mais de façon reproductible. C'est le « degrade » du live-coding, et il sert à alléger une trame trop dense sans choisir soi-même les notes à sacrifier — une boucle de seize doubles-croches jouée à 70 % devient une figure irrégulière qui garde son allure. Deux précautions le distinguent d'un simple tirage. Le tirage se fait par événement et non par note : un accord part entier ou reste entier, un éclaircissement ne doit pas défaire les harmonies. Et « Garder les temps » épargne ce qui tombe sur un temps, parce qu'une trame éclaircie entièrement au hasard perd sa pulsation : on veut souvent l'alléger, pas la dissoudre. « Durée d'un temps » dit ce qui compte pour un temps, en secondes — à 120 BPM, la noire fait 0,5 s. À graine fixée, le même éclaircissement se rejoue à l'identique : un résultat trouvé plaisant est retrouvable, et c'est pourquoi la graine tirée au sort est affichée dans le message pour pouvoir être recopiée.", en: "Removes a share of the notes at random, but reproducibly. This is live-coding's « degrade », and it serves to lighten an over-dense texture without choosing the notes to sacrifice oneself — a loop of sixteen sixteenths played at 70 % becomes an irregular figure that keeps its shape. Two precautions set it apart from a plain draw. The draw is per event, not per note: a chord leaves whole or stays whole, thinning must not undo the harmony. And « Keep beats » spares whatever lands on a beat, because a texture thinned purely at random loses its pulse: one usually wants it lighter, not dissolved. « Beat length » says what counts as a beat, in seconds — at 120 BPM, a quarter note is 0.5 s. With a fixed seed, the same thinning replays identically: a result found pleasing can be found again, which is why the randomly drawn seed is shown in the message so it can be copied back." },
  "motif-retrograde": { fr: "Joue le motif à l'envers, ou en aller-retour. Le rétrograde est une opération de contrepoint aussi vieille que le canon, et sa définition est précise : on renverse l'ordre des notes, pas les notes elles-mêmes. Les durées sont donc conservées exactement, et la conséquence s'entend — une figure qui finissait sur une longue tenue commence maintenant par elle. Le temps est retourné autour de l'étendue du motif, qui ne se déplace donc pas. « Aller-retour » met le motif puis son rétrograde à la suite : c'est le palindrome, la figure que Machaut écrivait déjà et que le live-coding appelle `palindrome`. « Retour-aller » commence par le rétrograde, ce qui fait entendre le motif d'origine comme une résolution plutôt que comme un départ. « Rejouer la charnière » décide du sort de l'événement du retournement, et le choix est offert parce que les deux se défendent : do-ré-mi suivi de son rétrograde donne do-ré-mi-mi-ré-do, où le mi est joué deux fois et marque nettement le pivot ; le palindrome qu'on écrit en musique est do-ré-mi-ré-do, avec un seul mi au sommet, et il coule. La charnière retirée, le raccord est exact : ni trou ni chevauchement. Les accords restent plaqués de part et d'autre, et une note seule est rendue telle quelle, étant son propre palindrome.", en: "Plays the pattern backwards, or there and back. The retrograde is a counterpoint operation as old as the canon, and its definition is precise: the order of the notes is reversed, not the notes themselves. Durations are therefore kept exactly, and the consequence is audible — a figure that ended on a long held note now opens with it. Time is turned around the pattern's own span, so the pattern does not move. « There and back » puts the pattern then its retrograde one after the other: that is the palindrome, the figure Machaut was already writing and that live-coding calls `palindrome`. « Back and there » starts with the retrograde, which makes the original pattern sound like a resolution rather than a departure. « Repeat the hinge » decides what becomes of the turning event, and the choice is offered because both stand up: C-D-E followed by its retrograde gives C-D-E-E-D-C, where the E is played twice and marks the pivot clearly; the palindrome one writes in music is C-D-E-D-C, with a single E at the top, and it flows. With the hinge dropped, the join is exact: no gap and no overlap. Chords stay struck whole on either side, and a single note is returned as is, being its own palindrome." },
  "motif-repeter-tourner": { fr: "Deux opérations sur un même motif, qui ne touchent pas à la même chose. Répéter subdivise la durée de chaque événement en parts égales et rejoue la même hauteur dans chacune — le « ply » du live-coding : la grille rythmique ne se déplace pas, elle se remplit. Une noire répétée quatre fois devient quatre doubles-croches sur la même hauteur, et les départs des autres notes restent exactement où ils étaient. Tourner décale la suite des hauteurs sur la grille sans toucher aux départs : le rythme reste en place, la mélodie glisse. Une rotation de 1 sur do-ré-mi donne ré-mi-do aux mêmes instants. C'est l'« iter », et sur une boucle il fait entendre le même matériau depuis un autre point de départ. Les deux s'appliquent dans cet ordre, ce qui veut dire que la rotation porte sur le motif déjà densifié : deux notes répétées deux fois font quatre pas, et tourner d'un pas décale donc d'un demi-pas du motif d'origine. Une rotation négative tourne dans l'autre sens, et une rotation plus grande que le motif boucle. Les accords sont répétés entiers.", en: "Two operations on one pattern, which do not touch the same thing. Repeat subdivides each event's duration into equal parts and replays the same pitch in each — live-coding's « ply »: the rhythmic grid does not move, it fills up. A quarter note repeated four times becomes four sixteenths on the same pitch, and the other notes' onsets stay exactly where they were. Rotate shifts the pitch sequence along the grid without touching the onsets: the rhythm stays put, the melody slides. A rotation of 1 on C-D-E gives D-E-C at the same instants. This is « iter », and on a loop it makes the same material heard from another starting point. The two apply in that order, which means the rotation acts on the already densified pattern: two notes repeated twice make four steps, so rotating by one step shifts by half a step of the original pattern. A negative rotation turns the other way, and a rotation larger than the pattern wraps. Chords are repeated whole." },
  "quadrafuzz": { fr: "Distorsion à quatre bandes. Une distorsion ordinaire écrase tout le spectre ensemble : les graves, qui portent le plus d'énergie, saturent les premiers et étouffent le reste — c'est pourquoi une basse passée dans une fuzz devient une bouillie. Ici le signal est découpé en quatre registres par trois fréquences de coupure réglables, chacun est saturé séparément, puis tout est rassemblé. On peut donc mordre les médiums en laissant la basse propre, ou donner du grain aux graves sans rendre les cymbales agressives. Mesuré : saturer les aigus à fond ne déplace un 80 Hz que de six millièmes, tandis que saturer les graves multiplie son harmonique de rang trois par soixante-dix. C'est cette indépendance qui fait tout l'intérêt du composant. « Aigus » est volontairement bas par défaut : c'est la bande qui rend un fuzz strident. « Sortie » est à −6 dB, parce qu'une saturation fait monter le niveau et qu'il faut le rattraper. À « Mix » 0 %, le signal d'origine ressort intact. Une remarque sur le découpage : il emploie de vrais filtres — un passe-bas, deux passe-bande, un passe-haut —, si bien que la somme des quatre bandes ne redonne pas exactement le signal d'entrée, même sans saturation. Un découpage par soustraction reconstruirait parfaitement mais séparerait mal, et la séparation est ce qu'on vient chercher.", en: "Four-band distortion. An ordinary distortion crushes the whole spectrum together: the low end, which carries the most energy, saturates first and smothers the rest — which is why a bass through a fuzz turns to mush. Here the signal is split into four registers by three adjustable crossover frequencies, each is saturated separately, then everything is summed. The mids can therefore bite while the bass stays clean, and the low end can be given grit without the cymbals turning harsh. Saturating the highs fully moves an 80 Hz tone by six thousandths, while saturating the lows multiplies its third harmonic by seventy. That independence is the whole point of the node. « High » is deliberately low by default: it is the band that makes a fuzz shrill. « Output » sits at -6 dB, because saturation raises the level and it has to be brought back. At « Mix » 0%, the original signal comes out untouched. A note on the split: it uses real filters — one lowpass, two bandpass, one highpass — so the sum of the four bands does not exactly reproduce the input, even with no saturation. A subtractive split would reconstruct perfectly but separate poorly, and separation is what one comes for." },
  "musicxml": { fr: "Convertit un fichier MIDI en partition MusicXML — le format d'échange que lisent MuseScore, Finale, Sibelius et Dorico. La sortie texte donne le XML, la sortie fichier un .musicxml prêt à enregistrer. Les notes qui commencent ensemble deviennent un accord, les trous deviennent des silences, et chaque mesure est remplie exactement — une mesure qui ne tombe pas juste est refusée par MuseScore. « Quantification » décide de la plus petite valeur écrite : une note jouée entre deux cases est ramenée sur la grille. C'est ce qui rend la partition lisible, et c'est aussi ce qui lui fait perdre le détail de l'interprétation. « Tempo » ne change pas les hauteurs, mais un tempo faux donne des durées fausses. Ce que l'export ne sait pas faire, et qu'aucune transcription automatique ne sait : les liaisons, les nuances, les indications d'expression, et le choix enharmonique du compositeur — un do dièse est écrit dièse, jamais ré bémol. Une note plus longue qu'une mesure est tronquée, faute de pouvoir être liée. C'est un point de départ à éditer, pas une gravure.", en: "Converts a MIDI file into a MusicXML score — the interchange format read by MuseScore, Finale, Sibelius and Dorico. The text output gives the XML, the file output a .musicxml ready to save. Notes starting together become a chord, gaps become rests, and every bar is filled exactly — a bar that does not add up is rejected by MuseScore. « Quantization » sets the smallest value written: a note played between two slots is snapped to the grid. That is what makes the score readable, and also what loses the detail of the performance. « Tempo » does not change the pitches, but a wrong tempo gives wrong durations. What the export cannot do, and no automatic transcription can: slurs, dynamics, expression marks, and the composer's enharmonic choice — a C sharp is written sharp, never D flat. A note longer than a bar is truncated, for lack of a tie. It is a starting point to edit, not an engraving." },
  "detecteur-tempo": { fr: "Estime le tempo d'un enregistrement et le rend comme valeur, branchable sur le paramètre Tempo d'un autre composant — c'est ce qui permet d'aligner une boucle générée sur un extrait importé. La mesure est celle de l'analyse audio : enveloppe d'attaques, autocorrélation, et flux spectral. « Correction d'octave » traite la faiblesse classique de toute détection de tempo : rien ne distingue 80 BPM d'un 160 BPM compté un temps sur deux, les deux périodes expliquent aussi bien le signal. Le repli ramène la valeur dans la plage réglable, ce qui ne change pas le rythme entendu, seulement la façon de le compter ; le rapport rappelle la valeur brute et les autres lectures plausibles. La fiabilité est annoncée en trois paliers, et non en pourcentage : le pic d'autocorrélation n'est pas une probabilité, et donner deux décimales serait une précision inventée. Ce que vaut la mesure, chiffré : sur des trains de clics, 90, 100, 120 et 140 BPM sont retrouvés à un battement près. Sur des motifs de boîte à rythmes, 100 et 75 BPM sont justes, mais un motif à 140 ressort à 70 — une erreur d'octave, que le rapport signale en proposant 140 parmi les lectures plausibles. Un morceau rubato ou sans percussion se mesure mal, et la fiabilité annoncée le dit.", en: "Estimates a recording's tempo and outputs it as a value, connectable to another node's Tempo parameter — which is how a generated loop gets aligned to an imported excerpt. The measurement is that of the audio analysis: onset envelope, autocorrelation and spectral flux. « Octave correction » deals with the classic weakness of every tempo detector: nothing tells 80 BPM from a 160 BPM counted every other beat, both periods explain the signal equally well. Folding brings the value into the adjustable range, which does not change the rhythm heard, only how it is counted; the report recalls the raw value and the other plausible readings. Reliability is reported in three levels rather than as a percentage: the autocorrelation peak is not a probability, and two decimals would be invented precision. What the measurement is worth, in figures: on click trains, 90, 100, 120 and 140 BPM are recovered within one beat. On drum-machine patterns, 100 and 75 BPM are right, but a 140 pattern comes out as 70 — an octave error, which the report flags by offering 140 among the plausible readings. A rubato or percussionless piece measures poorly, and the reported reliability says so." },
  "goniometre": { fr: "Mesure ce que les deux canaux font l'un de l'autre, et le montre. La figure est un goniomètre : chaque échantillon devient un point dont l'axe vertical porte la somme des canaux — ce qui survit en mono — et l'axe horizontal leur différence, ce qui disparaît. Un trait vertical est du mono, un nuage rond une stéréo large, un trait horizontal une opposition de phase. Sous la figure, la corrélation de Pearson, de −1 à +1 : au-dessus de 0,95 le mix est mono ou presque ; vers 0 les canaux sont indépendants ; en dessous de −0,2 ils s'opposent et la somme mono les annule. Le rapport donne aussi le niveau de chaque canal et celui de la somme mono : la « perte en mono » est le nombre de décibels que le mix laisse en route si on l'écoute sur une enceinte unique. Trois décibels sont normaux pour une stéréo large ; au-delà de dix, quelque chose s'annule. L'audio ressort inchangé : le composant mesure, il ne corrige pas. Un fichier mono est annoncé comme tel, ce qui est la vérité et non une erreur.", en: "Measures what the two channels do to each other, and shows it. The figure is a goniometer: each sample becomes a point whose vertical axis carries the sum of the channels — what survives in mono — and whose horizontal axis carries their difference, what disappears. A vertical line is mono, a round cloud is wide stereo, a horizontal line is out of phase. Below the figure, Pearson's correlation, from -1 to +1: above 0.95 the mix is mono or nearly so; near 0 the channels are independent; below -0.2 they oppose each other and the mono sum cancels them. The report also gives each channel's level and the level of the mono sum: the « loss in mono » is how many decibels the mix leaves behind when heard on a single speaker. Three decibels are normal for wide stereo; beyond ten, something is cancelling. Audio passes through unchanged: this node measures, it does not correct. A mono file is reported as mono, which is the truth and not an error." },
  "rythme-euclidien": { fr: "Répartit N frappes le plus régulièrement possible sur M pas, par l'algorithme de Bjorklund — celui qui sert à espacer les impulsions d'un accélérateur de particules. Godfried Toussaint a montré en 2005 que ces motifs sont ceux de rythmes traditionnels attestés : E(3,8) est le tresillo cubain, E(5,8) le cinquillo, E(2,5) le khafif-e-ramal persan, E(7,12) le bembé d'Afrique de l'Ouest, E(5,16) la bossa-nova. Le message affiche le motif obtenu et, quand le couple est reconnu, son nom d'usage. « Rotation » décale le départ du cycle sans toucher aux intervalles : le tresillo tourné de trois pas donne la figure qui commence sur le contretemps. Un composant ne joue qu'une percussion : pour une polyrythmie, superposez-en plusieurs — grosse caisse en E(3,8), charley en E(5,8) — et mélangez leurs sorties audio, ou réunissez leurs sorties MIDI. Le rendu audio passe par les percussions synthétisées internes, sans SoundFont ; la sortie MIDI porte les notes sur le canal 10 (percussions), prête pour un autre composant.", en: "Spreads N onsets as evenly as possible over M steps, using Bjorklund's algorithm — the one that spaces pulses in a particle accelerator. Godfried Toussaint showed in 2005 that these patterns are those of attested traditional rhythms: E(3,8) is the Cuban tresillo, E(5,8) the cinquillo, E(2,5) the Persian khafif-e-ramal, E(7,12) the West African bembé, E(5,16) the bossa-nova. The message shows the resulting pattern and, when the pair is a known one, its usual name. « Rotation » shifts the cycle's start without touching the intervals: the tresillo rotated by three steps gives the figure that starts off-beat. One node plays a single drum: for a polyrhythm, stack several — kick on E(3,8), hi-hat on E(5,8) — and mix their audio outputs, or merge their MIDI outputs. Audio is rendered with the internal synthesized drums, without a SoundFont; the MIDI output carries the notes on channel 10 (percussion), ready for another node." },
  "clavier-melodie": { fr: "Rejoue une séquence de notes enregistrée au clavier virtuel du bloc et la synthétise en audio. Le clavier compte 88 touches, de La0 à Do8, et défile ; les touches noires se jouent à la souris dans leur partie haute, les blanches en dessous. On peut aussi jouer au clavier de l'ordinateur — rangée wxcvbn pour les blanches, sdghj pour les noires — et changer d'octave avec les flèches haut et bas.", en: "Replays a sequence of notes recorded on the block's virtual keyboard and synthesizes it to audio. The keyboard has 88 keys, from A0 to C8, and scrolls; black keys play from their upper part, white keys below. The computer keyboard plays too — the zxcvbnm row for white keys, sdghj for black ones — and the up and down arrows change octave." },
  "sampler-personnalise": { fr: "Utilise un échantillon audio comme instrument mélodique : l'échantillon est transposé pour jouer une mélodie dans la gamme choisie.", en: "Uses an audio sample as a melodic instrument: the sample is pitched to play a melody in the chosen scale." },
  // ── Effets ──
  "delay-stereo": { fr: "Répète le signal avec un délai réglable indépendamment à gauche et à droite, créant un effet d'écho stéréo. Le feedback règle le nombre de répétitions.", en: "Repeats the signal with an independently adjustable left/right delay, creating a stereo echo. Feedback sets the number of repeats." },
  "echo-ping-pong": { fr: "Écho dont les répétitions rebondissent alternativement entre les canaux gauche et droit.", en: "Echo whose repeats bounce alternately between the left and right channels." },
  "echo-inverse": { fr: "Echo inversé : les répétitions atténuées arrivent avant le son principal. Principe : on inverse le signal, on lui applique un echo classique, puis on ré-inverse le résultat. Cela produit une montée de pré-échos de plus en plus forts jusqu'au son principal. Réglages : le temps entre répétitions et le feedback (nombre et décroissance des répétitions).", en: "Reverse echo: attenuated repetitions build up before the main sound. Principle: reverse the signal, apply a normal echo, then reverse the result. This produces a build-up of pre-echos that grow louder until the main sound hits. Settings: the time between repetitions and the feedback (number and decay of repetitions)." },
  "reverberation": { fr: "Simule l'acoustique d'une pièce par convolution. La taille et le decay définissent l'ampleur et la durée de la queue de réverbération.", en: "Simulates room acoustics via convolution. Size and decay set the extent and length of the reverb tail." },
  "reverb-fractale": { fr: "Réverbération à convolution dont la réponse impulsionnelle est construite par une poussière de Cantor. Les réflexions sont placées récursivement : à chaque niveau, l'intervalle temporel est divisé en trois et les réflexions sont conservées sur les tiers externes uniquement. La densité contrôle la profondeur de récursion, l'atténuation règle la décroissance de l'amplitude par niveau, et la diffusion étale les réflexions en stéréo. Réglages : le mix pour équilibrer le son direct et la réverbération.", en: "Convolution reverb whose impulse response is built from a Cantor dust. Reflections are placed recursively: at each level, the time interval is divided into three and reflections are kept only on the outer thirds. Density controls the recursion depth, attenuation sets the amplitude decay per level, and diffusion spreads reflections in stereo. Settings: the mix to balance dry and wet signals." },
  "reverbe-convolution": { fr: "Réverbération à convolution : génère une réponse impulsionnelle (IR) synthétique à partir de vos réglages (type de pièce, taille, decay, pre-delay, damping) et la convolue avec le signal. L'ir est la « signature acoustique » d'un espace : le convoleur la superpose au signal pour recréer son acoustique. Un fichier de réponse impulsionnelle (WAV) se charge aussi par le bouton du composant ; les paramètres de synthèse sont alors ignorés. Réglages : le mix pour équilibrer le son direct et la réverbération.", en: "Convolution reverb: generates a synthetic impulse response (IR) from your settings (room type, size, decay, pre-delay, damping) and convolves it with the signal. The IR is the « acoustic signature » of a space: the convolver superimposes it onto the signal to recreate its acoustics. An external impulse response file (WAV) can also be loaded from the node's button; the synthesis parameters are then ignored. Settings: the mix to balance dry and wet signals." },
  "reverb-progressive": { fr: "Réverbération dont le mélange évolue progressivement du son sec vers le son réverbéré sur une durée de fondu réglable.", en: "Reverb whose mix gradually evolves from dry to wet over an adjustable fade duration." },
  "dereverberation": { fr: "Atténue la réverbération d'un enregistrement par traitement spectral, pour resserrer un son trop réverbérant.", en: "Attenuates the reverberation of a recording via spectral processing, tightening an overly reverberant sound." },
  "distorsion": { fr: "Sature le signal pour ajouter de l'harmonique et du grain, du léger overdrive à la distorsion franche.", en: "Saturates the signal to add harmonics and grit, from light overdrive to full distortion." },
  "bitcrusher": { fr: "Simule la basse résolution des convertisseurs N/A anciens en réduisant le nombre de bits (quantification) et la fréquence d'échantillonnage (sous-échantillonnage). À 8 bits, on retrouve le son des consoles 8-bit ; à 4 bits, le son devient très crunch et aliased. Réduire la fréquence d'échantillonnage ajoute de l'aliasing (repliement de spectre) caractéristique. S'emploie pour un effet rétro, lo-fi ou destructif. Le mix permet de doser l'effet sur le signal original.", en: "Simulates the low resolution of old D/A converters by reducing the bit depth (quantization) and sample rate (downsampling). At 8 bits, you get the 8-bit console sound; at 4 bits, the sound becomes very crunchy and aliased. Reducing the sample rate adds characteristic aliasing (spectral folding). Used for a retro, lo-fi or destructive effect. The mix controls the dry/wet balance." },
  "flanger": { fr: "Module un court délai variable pour produire un balayage caractéristique en « jet d'avion ».", en: "Modulates a short variable delay to produce the characteristic jet-plane sweep." },
  "chorus": { fr: "Superpose des copies légèrement désaccordées et modulées du signal pour l'épaissir et l'élargir en stéréo.", en: "Layers slightly detuned, modulated copies of the signal to thicken and widen it in stereo." },
  "compresseur": { fr: "Réduit la dynamique en atténuant les passages au-dessus du seuil, selon le ratio, l'attaque et le relâchement choisis.", en: "Reduces dynamics by attenuating passages above the threshold, according to the chosen ratio, attack and release." },
  "gate-expandeur": { fr: "Deux effets dynamiques en un seul composant. Gate : coupe le signal quand il passe sous un seuil (utile pour éliminer le bruit de fond entre les phrases, le souffle, les résidus de réverbération). Expandeur : atténue渐进ment le signal sous le seuil selon un ratio (compresseur inversé — plus doux qu'un gate). Réglages :\n• le seuil (en dB)\n• l'attaque\n• le relâchement (temps de transition)\n• l'atténuation maximale du plancher (le niveau de coupure en mode Gate, la limite en mode Expandeur)\n• le ratio (mode Expandeur uniquement).\nNettoie un enregistrement vocal ou instrumental.", en: "Two dynamic effects in one node. Gate: cuts the signal when it drops below a threshold (useful for removing background noise between phrases, hiss, reverb tails). Expander: gradually attenuates signal below threshold by a ratio (reverse compressor — gentler than a gate). Settings:\n• the threshold (in dB)\n• attack\n• release (transition times)\n• maximum floor attenuation (cut level in Gate mode, limit in Expander mode)\n• ratio (Expander mode only).\nCleans up a vocal or instrumental recording." },
  "de-esser": { fr: "Atténue dynamiquement les sibilances (s, ch, sh, t, z) qui ressortent trop dans un enregistrement vocal. Fonctionne comme un compresseur ciblé sur une bande de fréquences étroite (typiquement 5-9 kHz) : un filtre passe-bande extrait l'énergie de la bande cible, et quand elle dépasse le seuil, un gain réducteur est appliqué au signal complet. Réglages :\n• la fréquence centrale\n• la largeur de la bande\n• le seuil (niveau d'activation)\n• le ratio (force de la réduction)\n• l'attaque\n• le relâchement.\nAttaque courte = réaction précise sur les transitoires ; relâchement moyen = transition naturelle.", en: "Dynamically attenuates sibilants (s, ch, sh, t, z) that stand out too much in a vocal recording. Works like a compressor targeted at a narrow frequency band (typically 5-9 kHz): a bandpass filter extracts the target band's energy, and when it exceeds the threshold, a reducing gain is applied to the full signal. Settings:\n• the center frequency\n• band width\n• threshold (activation level)\n• ratio (reduction strength)\n• attack\n• release.\nShort attack = precise reaction to transients; medium release = natural transition." },
  "ring-modulator": { fr: "Multiplie le signal par une onde sinusoïdale (porteuse), produisant des sidebands — les sommes et différences de fréquences entre le signal et la porteuse. À une fréquence de porteuse donnée (ex. 200 Hz), une note de 440 Hz produit des composantes à 240 et 640 Hz. Effet caractéristique des sonneries de téléphone, des voix métalliques/robotiques et des textures alien. Réglages : la fréquence de la porteuse (1-8000 Hz) et le mix (100% = effet seul).", en: "Multiplies the signal by a sine wave (carrier), producing sidebands — the sum and difference frequencies between the signal and the carrier. At a given carrier frequency (e.g. 200 Hz), a 440 Hz note produces components at 240 and 640 Hz. Characteristic effect of telephone rings, metallic/robotic voices and alien textures. Settings: the carrier frequency (1-8000 Hz) and mix (100% = effect only)." },
  "limiteur": { fr: "Limiteur de crête pour le mastering : attaque instantanée, relâchement réglable et plafond de sortie. Réduit les pics dépassant le seuil avec un ratio infini, puis applique un gain de make-up pour que le plafond atteigne la valeur cible. Gagne en sonie sans dépasser 0 dB.", en: "Peak limiter for mastering: instant attack, adjustable release and output ceiling. Reduces peaks above the threshold with an infinite ratio, then applies makeup gain so the ceiling reaches the target value. Gains loudness without clipping." },
  "transient-shaper": { fr: "Contrôle indépendant de l'attaque et du sustain d'un son. Deux détecteurs d'enveloppe (rapide pour les attaques, lent pour le corps) permettent de booster ou couper les transitoires et la tenue séparément. Donne du punch à une batterie, ou raccourcit une caisse claire trop longue.", en: "Independent control of a sound's attack and sustain. Two envelope detectors (fast for attacks, slow for the body) let you boost or cut transients and sustain separately. Essential for adding punch to drums or shortening an overly long snare." },
  "largeur-stereo": { fr: "Contrôle de la largeur stéréo et de la balance Mid/Side. Décode le signal en centre (Mid = L+R) et côtés (Side = L-R), ajuste leur gain, puis recode en L/R. Largeur = 0% donne le mono, 100% conserve l'image stéréo originale, 200% élargit le stéréo. Le paramètre Mid permet de booster ou couper le centre indépendamment (utile pour faire de la place à une voix ou un kick).", en: "Stereo width and Mid/Side balance control. Decodes the signal into center (Mid = L+R) and sides (Side = L-R), adjusts their gain, then re-encodes to L/R. Width = 0% gives mono, 100% preserves the original stereo image, 200% widens it. The Mid parameter lets you boost or cut the center independently (useful to make room for a vocal or kick)." },
  "compresseur-multibande": { fr: "Compresseur divisé en trois bandes (low, mid, high). Chaque bande est isolée par un crossover, puis compressée avec son propre seuil et ratio. Maîtrise les basses sans toucher aux aigus, ou ajoute du punch sur le medium sans écraser les graves.", en: "Compressor split into three bands (low, mid, high). Each band is isolated by a crossover and compressed with its own threshold and ratio. Controls lows without affecting highs, or adds punch to the mids without squashing the bass." },
  "harmonizer": { fr: "Ajoute jusqu'à deux voix pitch-shiftées sous le signal original. Réglages : l'intervalle de chaque voix en demi-tons (12 = octave supérieure, -12 = octave inférieure, 7 = quinte) et son niveau de mix. Épaissit une guitare ou forme des harmonies simples.", en: "Adds up to two pitch-shifted voices under the original signal. Settings: each voice's interval in semitones (12 = octave up, -12 = octave down, 7 = fifth) and its mix level. Thickens a guitar or forms simple harmonies." },
  "exciter": { fr: "Ajoute de la présence et du brillant par distorsion harmonique asymétrique dans les hautes fréquences. Utile pour faire ressortir une voix, une guitare ou un master manquant de définition. Le paramètre Amount contrôle l'intensité de la saturation, Fréquence la coupure du passe-haut, et Mix le dosage.", en: "Adds presence and brightness via asymmetrical harmonic distortion in the high frequencies. Useful for bringing out a vocal, guitar or a master lacking definition. Amount controls saturation intensity, Frequency sets the high-pass cutoff, and Mix controls the dry/wet balance." },
  "granular-freeze": { fr: "Extrait un petit grain à la position choisie et le boucle sur toute la durée. Contrôlez la taille du grain, sa transposition (Pitch) et le mix. Utile pour créer des textures drones, des effets de freeze ou des sons granulaires abstraits.", en: "Extracts a small grain at the chosen position and loops it across the whole duration. Control grain size, pitch transposition and mix. Useful for creating drone textures, freeze effects or abstract granular sounds." },
  "vocoder": { fr: "Vocoder par banc de filtres passe-bande. L'entrée Modulateur reçoit une voix, ou tout autre modulateur ; l'entrée Porteuse un son riche en harmoniques. Le spectre du modulateur contrôle le volume de chaque bande de la porteuse, produisant l'effet robotique classique. Réglages :\n• le nombre de bandes\n• la plage de fréquences\n• le Q.", en: "Filterbank vocoder.\nConnect a voice (or any modulator) to the Modulator input and a synthesizer (or any harmonic-rich carrier) to the Carrier input. The modulator's spectrum controls the volume of each carrier band, producing the classic robot effect. Settings:\n• the number of bands\n• frequency range\n• Q." },
  "normaliseur": { fr: "Ajuste le gain global pour amener la crête du signal au niveau cible, sans modifier la dynamique.", en: "Adjusts overall gain to bring the signal peak to the target level, without changing dynamics." },
  "amplificateur": { fr: "Applique un gain constant en décibels pour amplifier ou atténuer l'ensemble du signal.", en: "Applies a constant gain in decibels to amplify or attenuate the whole signal." },
  "suppression-clics": { fr: "Détecte les clics et crépitements brefs et les remplace par une interpolation du signal voisin.", en: "Detects brief clicks and crackles and replaces them with an interpolation of the neighbouring signal." },
  "reduction-bruit": { fr: "Soustrait le bruit de fond du signal à partir d'un profil de bruit capturé sur un passage silencieux (bloc « Profil de bruit »).", en: "Subtracts background noise from the signal using a noise profile captured on a silent passage (« Noise Profile » block)." },
  "profil-bruit": { fr: "Analyse un passage de bruit seul et en produit un profil spectral, à brancher sur « Réduction de bruit ».", en: "Analyses a noise-only passage and produces a spectral profile, to feed into « Noise Reduction »." },
  "reponse-filtre": { fr: "Filtre le signal selon le type choisi (passe-bas, passe-haut, passe-bande, coupe-bande) avec une fréquence de coupure et une résonance (Q) réglables.\nLa vue affiche en temps réel la courbe de réponse en fréquence du filtre (gain en dB par fréquence) — utile pour comprendre visuellement ce que le filtre fait au spectre. La courbe se met à jour instantanément quand on règle les paramètres, même avant exécution.", en: "Filters the signal by the chosen type (lowpass, highpass, bandpass, notch) with adjustable cutoff frequency and resonance (Q). The view displays the filter's frequency response curve (gain in dB per frequency) in real time — useful to visually understand what the filter does to the spectrum. The curve updates instantly as you change parameters, even before execution." },
  "equaliseur": { fr: "Égaliseur neuf bandes : ajuste indépendamment le gain des fréquences 32 Hz, 64 Hz, 125 Hz, 250 Hz, 500 Hz, 1 kHz, 2 kHz, 4 kHz et 8 kHz. Sculpte finement le timbre d'une piste.", en: "Nine-band equalizer: independently adjusts the gain of the 32 Hz, 64 Hz, 125 Hz, 250 Hz, 500 Hz, 1 kHz, 2 kHz, 4 kHz and 8 kHz bands. Finely sculpts a track's timbre." },
  "changement-tempo": { fr: "Accélère ou ralentit la piste en préservant la hauteur (vocodeur de phase). La durée change en proportion inverse de la vitesse.", en: "Speeds up or slows down the track while preserving pitch (phase vocoder). Duration changes inversely to speed." },
  "changement-tonalite": { fr: "Transpose la hauteur d'un nombre de demi-tons donné, sans modifier la durée de la piste.", en: "Transposes the pitch by a given number of semitones, without changing the track duration." },
  "glissando-tonalite": { fr: "Glissando de hauteur : la transposition évolue continuellement entre les valeurs de début et de fin (en demi-tons), tout en conservant la durée totale. L'effet est obtenu par une lecture temporelle variable dont le débit est normalisé sur la durée de la piste. Si les deux hauteurs sont égales, le node se comporte comme un changement de tonalité statique.", en: "Pitch glissando: the transposition continuously evolves between the start and end values (in semitones), while keeping the total duration. The effect is produced by a variable-speed playback whose rate is normalized across the track length. If both pitches are equal, the node behaves like a static pitch shift." },
  "paulstretch": { fr: "Paulstretch : étirement temporel extrême par randomisation des phases de la STFT. Le signal est découpé en grandes fenêtres, les phases sont tirées au hasard dans chaque fenêtre, puis les morceaux sont recollés par overlap-add. Cela produit une texture sonore lisse et flottante, idéale pour des drones ou des ambiances. Chaque canal est traité indépendamment : une entrée stéréo reste stéréo. Paramètres : Stretch (facteur d'étirement, 1 à 100×) et Fenêtre (taille de la fenêtre en secondes, 0.01 à 1 s).", en: "Paulstretch: extreme time-stretch by randomizing the phases of the STFT. The signal is sliced into large windows, phases are randomized in each window, then the pieces are overlap-added. This produces a smooth, floating sound texture, suited to drones and ambient textures. Each channel is processed independently: a stereo input stays stereo. Parameters: Stretch (stretch factor, 1 to 100×) and Window (STFT window size in seconds, 0.01 to 1 s)." },
  "paulstretch-logistique": { fr: "Paulstretch logistique : l'étirement extrême s'installe progressivement selon une courbe logistique. En début de piste le signal est intact, puis il se transforme progressivement en texture étirée jusqu'au facteur maximal. Paramètres : Stretch maximal, Fenêtre, Centre, Pente et Mix.", en: "Logistic Paulstretch: extreme time-stretch grows in progressively following a logistic curve. At the start the signal is intact, then it gradually transforms into a stretched texture up to the maximum factor. Parameters: max Stretch, Window, Center, Steepness and Mix." },
  "beat-repeat": { fr: "Beat Repeat / Stutter : capture un court segment de l'audio à intervalles rythmiques synchronisés sur le tempo et le répète plusieurs fois avec décroissance. Crée des effets stutter, glitch et répétitions rythmiques typiques des productions électroniques. Paramètres : Tempo, Intervalle entre captures, Taille du segment, Répétitions, Feedback et Mix.", en: "Beat Repeat / Stutter: captures a short audio segment at rhythmic intervals synchronized to the tempo and repeats it several times with decay. Creates stutter, glitch and rhythmic repeat effects typical of electronic productions. Parameters: Tempo, Capture interval, Segment size, Repeats, Feedback and Mix." },
  "formule-echantillons": { fr: "Applique une expression mathématique à chaque échantillon du signal. Variables : x (valeur actuelle), t (temps en s), i (index), c (canal), ch (nombre de canaux), sr (fréquence d'échantillonnage). Par exemple, y = x * 0.5 divise le volume par deux ; y = sin(t * 2 * pi * 440) + x ajoute une sinusoïde de 440 Hz. Le résultat est clampé à [-1, 1] pour éviter les signaux hors plage, puis mis à l'échelle par le Volume de sortie. Les résultats à forte intensité demandent de la prudence sur le volume d'écoute.", en: "Applies a mathematical expression to each sample of the signal. Variables: x (current value), t (time in s), i (index), c (channel), ch (channel count), sr (sample rate). For example, y = x * 0.5 halves the volume; y = sin(t * 2 * pi * 440) + x adds a 440 Hz sine. The output is clamped to [-1, 1] to avoid out-of-range signals, then scaled by the Volume parameter. Be careful with your system volume before listening to high-intensity results." },
  "formule-spectrale": { fr: "Modifie le spectre du signal par des expressions mathématiques appliquées à chaque bin de fréquence. Variables : mag (magnitude actuelle), phase (phase actuelle), freq (fréquence en Hz), bin (index du bin), N (taille de la FFT), sr (fréquence d'échantillonnage). Par exemple, mag * 2 double le gain spectral ; mag * (freq > 1000) ne garde que les fréquences au-dessus de 1 kHz. L'opération utilise une STFT avec overlap-add. Le paramètre Volume règle le niveau de sortie. La sortie est clampée à [-1, 1] pour éviter les signaux hors plage ; les résultats à forte intensité demandent de la prudence sur le volume de votre système avant d'écouter des résultats à forte intensité.", en: "Modifies the signal spectrum by mathematical expressions applied to each frequency bin. Variables: mag (current magnitude), phase (current phase), freq (frequency in Hz), bin (bin index), N (FFT size), sr (sample rate). For example, mag * 2 doubles the spectral gain; mag * (freq > 1000) keeps only frequencies above 1 kHz. Uses STFT with overlap-add. The Volume parameter sets the output level. Output is clamped to [-1, 1] to avoid out-of-range signals; be careful with your system volume before listening to high-intensity results." },
  "griffin-lim": { fr: "Reconstruction itérative d'un signal audio à partir de son spectrogramme de magnitude par l'algorithme Griffin-Lim. Le composant garde la magnitude de l'entrée et réinvente la phase, ce qui produit des textures sonores créatives (drones, brouillard spectral) ou permet de re-synthétiser un audio issu d'un modèle qui ne prédit que la magnitude. Paramètres : Itérations (plus il y en a, plus la phase est cohérente), Phase initiale (Aléatoire, Nulle ou Originale), Taille FFT, Recouvrement et Mix sec/mouillé. La sortie est normalisée à la crête du signal original pour conserver le niveau.", en: "Iterative audio signal reconstruction from its magnitude spectrogram using the Griffin-Lim algorithm. The node keeps the input magnitude and reinvents the phase, producing creative sound textures (drones, spectral fog) or allowing resynthesis of audio from a model that predicts only magnitude. Parameters: Iterations (more iterations = more coherent phase), Initial phase (Random, Zero or Original), FFT size, Overlap and Dry/wet mix. Output is normalized to the original signal peak to preserve level." },
  "generateur-audio-mathematique": { fr: "Génère un signal audio de toutes pièces à partir d'une expression mathématique. Variables : t (temps en s), i (index d'échantillon), c (canal), ch (nombre de canaux), sr (fréquence d'échantillonnage). Par exemple, sin(t * 2 * pi * 440) génère une sinusoïde de 440 Hz. Le résultat est clampé à [-1, 1] pour éviter les signaux hors plage, puis mis à l'échelle par le Volume de sortie. Les résultats à forte intensité demandent de la prudence sur le volume d'écoute.", en: "Generates an audio signal from scratch using a mathematical expression. Variables: t (time in s), i (sample index), c (channel), ch (channel count), sr (sample rate). For example, sin(t * 2 * pi * 440) generates a 440 Hz sine. The output is clamped to [-1, 1] to avoid out-of-range signals, then scaled by the Volume parameter. Be careful with your system volume before listening to high-intensity results." },
  "inverseur-audio": { fr: "Inverse le signal dans le temps : la piste est lue de la fin vers le début. À ne pas confondre avec l'inversion de polarité, qui change le signe des échantillons sans toucher à l'ordre du temps — ce composant s'appelait « Inverseur audio » et se résumait par « inverse le signal », ce qui désigne la polarité dans tout le métier.", en: "Reverses the signal in time: the track plays from end to start. Not to be confused with polarity inversion, which flips the sign of the samples without touching the order of time — this node used to be called « Audio Inverter » and summarised as « inverts the signal », which means polarity everywhere else in the craft." },
  "inversion-polarite": { fr: "Change le signe de chaque échantillon. Seule, l'opération ne s’entend pas : l’oreille est insensible à la polarité absolue d’un son, et c’est pourquoi on peut la croire inutile. Elle ne travaille qu’en relation, et trois usages en font le tour. L’annulation d’abord : la somme d’un son et de sa polarité inverse ne laisse rien. Ce silence est la preuve la plus sûre que deux fichiers sont identiques : s’il reste quelque chose, c’est exactement ce qui diffère, et cela s’écoute. Les prises à deux micros ensuite : un micro placé sous une caisse claire reçoit la peau qui s’éloigne quand celui du dessus la reçoit qui s’approche, si bien que leur somme se creuse ; retourner l’un des deux rend le coup. La compatibilité mono enfin : retourner un canal sur deux vide la somme mono. À ne pas confondre avec « Lecture inversée », qui inverse le temps et non le signe.", en: "Flips the sign of every sample. On its own the operation cannot be heard: the ear is insensitive to the absolute polarity of a sound, which is why it can seem useless. It works only in relation, and three uses cover it. The null test first: add a sound and its inverted polarity in the mixer, and nothing remains. That silence is the surest proof that two files are identical: if something remains, it is exactly what differs, and it can be listened to. Two-microphone takes next: a microphone under a snare receives the head moving away when the one above receives it moving closer, so their sum hollows out; flipping one of the two gives the hit back. Mono compatibility last: flipping every other channel empties the mono sum, and it is the quickest way to check that a goniometer is telling the truth. Not to be confused with « Reverse Playback », which inverts time rather than sign." },
  "echange-canaux": { fr: "Permute les canaux gauche et droit d'un signal stéréo.", en: "Swaps the left and right channels of a stereo signal." },
  "extraction-centre-cote": { fr: "Sépare la composante centrale (mono, commune aux deux canaux) des composantes latérales, avec dosage indépendant.", en: "Separates the center component (mono, common to both channels) from the side components, with independent balance." },
  "separateur-canaux": { fr: "Sépare un signal stéréo en deux sorties mono distinctes : la sortie 'Gauche' contient uniquement le canal gauche (L), la sortie 'Droite' uniquement le canal droit (R). Si l'entrée est déjà mono, les deux sorties reçoivent le même signal.", en: "Splits a stereo signal into two distinct mono outputs: the 'Left' output contains only the left channel (L), the 'Right' output only the right channel (R). If the input is already mono, both outputs receive the same signal." },
  "hard-panner": { fr: "Bascule le son entièrement à gauche, au centre ou à droite. Utile pour tester une chaîne mono, forcer un placement extrême ou corriger une erreur de câblage. L'entrée peut être stéréo ou mono ; la sortie est toujours stéréo.", en: "Switches the sound fully to the left, center, or right. Useful for testing a mono chain, forcing an extreme position, or fixing a wiring mistake. Input can be stereo or mono; output is always stereo." },
  "fondu": { fr: "Applique un fondu d'ouverture au début et un fondu de fermeture à la fin de la piste, de durées réglables.", en: "Applies a fade-in at the start and a fade-out at the end of the track, with adjustable durations." },
  "aligneur-piste": { fr: "Ajuste la longueur d'une piste à celle d'une référence. Entrée 1 (haut) = référence (passe inchangée). Entrée 2 (bas) = piste à aligner. Si la piste est trop courte : du silence est ajouté — au début (« Avant ») ou à la fin (« Après »). Si la piste est trop longue : un fade est appliqué — fade d'ouverture (« Avant », garde le début) ou fade de fermeture (« Après », garde la fin). La sortie 1 = référence inchangée, la sortie 2 = piste alignée (même longueur que la référence). Utile pour synchroniser des pistes de durées différentes avant de les fusionner ou les comparer.", en: "Aligns a track's length to a reference. Input 1 (top) = reference (passed through unchanged). Input 2 (bottom) = track to align. If the track is too short: silence is added — at the start (« Before ») or end (« After »). If too long: a fade is applied — fade in (« Before », keeps the start) or fade out (« After », keeps the end). Output 1 = reference unchanged, output 2 = aligned track (same length as reference). Useful for synchronizing tracks of different durations before merging or comparing them." },
  "extraire-zone": { fr: "Découpe une portion de la piste à partir d'un début et d'une durée, avec un léger fondu aux bords pour éviter les clics. Produit l'audio découpé et un objet « Zone » (début + durée) utilisable par « Réinsérer une zone ».", en: "Cuts out a portion of the track from a start and a duration, with a slight fade at the edges to avoid clicks. Produces the cut audio and a « Zone » object (start + duration) usable by « Reinsert Zone »." },
  "shift-formants": { fr: "Décalage formantique par analyse LPC. Sépare la voix en source glottale (hauteur) et filtre vocal (formants). Change la hauteur et les formants indépendamment — pas d'effet helium. Pour homme→femme : Hauteur +12, Formants 120%. Pour femme→homme : Hauteur −12, Formants 80%.", en: "Formant shifting via LPC analysis. Separates voice into glottal source (pitch) and vocal tract filter (formants). Change pitch and formants independently — no helium effect. For male→female: Pitch +12, Formants 120%. For female→male: Pitch −12, Formants 80%." },
  "ajouter-silence": { fr: "Ajoute du silence au début et/ou à la fin de la piste audio. Les durées de silence avant et après se règlent séparément, en secondes, de 0 à 60. Utile pour caler une piste dans un mixage, créer un intro/outro silencieux, ou synchroniser avec une référence.", en: "Adds silence at the beginning and/or end of the audio track. Independently set the silence durations before and after (in seconds, 0 to 60s). Useful for fitting a track in a mix, creating a silent intro/outro, or syncing with a reference." },
  "tremolo": { fr: "Modulation d'amplitude : fait varier le volume périodiquement. Réglages :\n• la fréquence (vitesse des vibrations, 0.1 à 20 Hz)\n• la profondeur (intensité, 0 à 100%)\n• la forme de l'onde (sinus, carré, triangle, sawtooth).\nUn effet classique pour les guitares et les orgues.", en: "Amplitude modulation: varies the volume periodically. Settings:\n• the rate (vibration speed, 0.1 to 20 Hz)\n• depth (intensity, 0 to 100%)\n• waveform shape (sine, square, triangle, sawtooth).\nA classic effect for guitars and organs." },
  "etirement-glissant": { fr: "Étirement temporel dont le facteur varie progressivement du début à la fin. Crée un effet d'accélération ou de décélération continue (effet « slide »). Réglages :\n• le facteur de début\n• de fin (0.25x à 4x) : par exemple début=1 (normal)\n• fin=4 (ralenti) crée un ralenti progressif.\nL'algorithme découpe le signal en segments, applique un phase vocoder avec un facteur interpolé, et recolle les segments avec un crossfade.", en: "Time-stretch with a factor that gradually changes from start to end. Creates a continuous acceleration or deceleration effect (\"slide\"). Settings: the start and end factors (0.25x to 4x): e.g. start=1 (normal) and end=4 (slow) creates a gradual slowdown. The algorithm slices the signal into segments, applies a phase vocoder with an interpolated factor, and rejoins segments with a crossfade." },
  "spatialisation-stereo": { fr: "Positionne un son mono ou stéréo dans l'espace stéréo. Utilise un PannerNode HRTF (Head-Related Transfer Function) pour une spatialisation binaurale réaliste. Position (-100% à 100%) contrôle la gauche/droite, Largeur (0% à 100%) contrôle l'étendue de l'effet. Utile pour placer un instrument dans un mixage ou créer un effet de mouvement spatial.", en: "Positions a mono or stereo sound in stereo space. Uses an HRTF PannerNode for realistic binaural spatialization. Position (-100% to 100%) controls left/right, Width (0% to 100%) controls the effect range. Useful for placing an instrument in a mix or creating a spatial movement effect." },
  "auto-pan": { fr: "Balayage stéréo automatique : le son se déplace périodiquement entre gauche et droite. Réglages : la fréquence (vitesse du balayage, 0.1 à 20 Hz) et la profondeur (amplitude, 0 à 100%). À faible fréquence, crée un effet de flottement ; à haute fréquence, approche un effet Leslie/vibrato stéréo.", en: "Automatic stereo sweep: the sound moves periodically between left and right. Settings: the rate (sweep speed, 0.1 to 20 Hz) and depth (amplitude, 0 to 100%). At low frequencies, creates a floating effect; at high frequencies, approaches a Leslie/vibrato stereo effect." },
  "auto-pan-logistique": { fr: "Balayage stéréo automatique progressif : le panoramique passe de gauche à droite en suivant une courbe logistique. Le Centre (0-100%) fixe le moment de la transition la plus rapide, la Pente (0.1-50) contrôle la raideur de la courbe (valeur élevée = transition abrupte), et le Mix règle le dosage entre signal original et effet. Utile pour des mouvements panoramiques qui apparaissent lentement puis s'accélèrent, ou inversement.", en: "Progressive automatic stereo sweep: the panning moves from left to right following a logistic curve. The Center (0-100%) sets the moment of the fastest transition, Steepness (0.1-50) controls the curve's sharpness (higher = more abrupt), and Mix sets the dry/wet balance. Useful for panning movements that appear slowly then accelerate, or vice versa." },
  "vibrato-logistique": { fr: "Vibrato dont la profondeur de modulation augmente selon une courbe logistique : le vibrato est inaudible au début, puis croît jusqu'à sa profondeur maximale. Réglages :\n• la fréquence (vitesse, 0.1 à 20 Hz)\n• la profondeur maximale (0 à ±2 demi-tons)\n• le centre (milieu de la transition)\n• la pente (raideur)\n• le mix.", en: "Vibrato whose modulation depth rises along a logistic curve: the vibrato is inaudible at the start, then grows to its maximum depth.\nSettings:\n• the rate (speed, 0.1 to 20 Hz)\n• the maximum depth (0 to ±2 semitones)\n• the center (midpoint of the transition)\n• the steepness\n• the mix." },
  "tremolo-logistique": { fr: "Tremolo dont la profondeur de modulation augmente selon une courbe logistique : l'effet est inaudible au début, puis croît jusqu'à sa profondeur maximale.\nRéglages :\n• la fréquence (vitesse, 0.1 à 20 Hz)\n• la profondeur maximale (0 à 100%)\n• le centre (milieu de la transition)\n• la pente (raideur)\n• le mix.", en: "Tremolo whose modulation depth rises along a logistic curve: the effect is inaudible at the start, then grows to its maximum depth.\nSettings:\n• the rate (speed, 0.1 to 20 Hz)\n• the maximum depth (0 to 100%)\n• the center (midpoint of the transition)\n• the steepness\n• the mix." },
  "echo-logistique": { fr: "Écho dont le feedback croît selon une courbe logistique : l'effet est inaudible au début, puis les répétitions deviennent de plus en plus présentes jusqu'au feedback maximal.\nRéglages :\n• le temps entre répétitions (50 à 2000 ms)\n• le feedback maximal (0 à 95%)\n• le centre (milieu de la transition)\n• la pente (raideur)\n• le mix.", en: "Echo whose feedback rises along a logistic curve: the effect is inaudible at the start, then repetitions become more and more present up to the maximum feedback.\nSettings:\n• the delay between repetitions (50 to 2000 ms)\n• the maximum feedback (0 to 95%)\n• the center (midpoint of the transition)\n• the steepness\n• the mix." },
  "resonance-audio": { fr: "Spatialise un son en 3D via le SDK Resonance Audio (Google).\nL’entrée est mixée en mono, positionnée dans un espace 3D avec un modèle de salle configurable, puis rendue en stéréo binaural (HRTF). Paramètres : position X/Y/Z de la source, dimensions de la pièce, matériau des parois.", en: "Spatializes a sound in 3D using the Resonance Audio SDK (Google). The input is mixed to mono, positioned in a 3D space with a configurable room model, and rendered as binaural stereo (HRTF). Parameters: source X/Y/Z position, room dimensions, wall material." },
  "stable-audio-3": { fr: "Génère de la musique stéréo à 44,1 kHz depuis un prompt texte avec Stable Audio 3 small-music. Le modèle ONNX (~640 MB) tourne dans le process principal. La génération est lente (plusieurs minutes). Le modèle « small-music » ne fait que de la musique, et attend un prompt en anglais.", en: "Generates stereo music at 44.1 kHz from a text prompt using Stable Audio 3 small-music. The ONNX model (~640 MB) runs in the main process. Generation is slow (several minutes). The small-music model handles music only, and expects an English prompt." },
  "continuation-stable-audio-3": { fr: "[expérimental] Prolonge une piste audio avec Stable Audio 3 small-music. Le modèle encode l'audio d'entrée, conserve son préfixe et génère la suite par inpainting causale. La qualité reste très limitée : l'encodeur ONNX int4 disponible n'est pas parfaitement aligné avec l'espace latent du DiT, donc la suite peut être un drone ou un bruit peu cohérent. Les entrées de plus de 5 secondes donnent de meilleurs résultats. Le bundle ONNX (~640 MB + encodeur ~36 MB) tourne dans le process principal. La génération est lente (plusieurs minutes). Nécessite le modèle small-music et l'encodeur encoder_q4.onnx dans le même dossier.", en: "[experimental] Extends an audio track with Stable Audio 3 small-music. The model encodes the input audio, keeps its prefix and generates the continuation via causal inpainting. Quality remains very limited: the available int4 ONNX encoder is not perfectly aligned with the DiT latent space, so the continuation may be a drone or incoherent noise. Inputs longer than 5 seconds give better results. The ONNX bundle (~640 MB + ~36 MB encoder) runs in the main process. Generation is slow (several minutes). Requires the small-music model and the encoder_q4.onnx in the same folder." },
  "legende-image": { fr: "Décrit le contenu d'une image en une phrase avec Mozilla/distilvit (ViT + GPT2 distillé, ~0,2 Md paramètres, licence Apache 2.0). Tourne dans un Web Worker via Transformers.js, se télécharge et se met en cache automatiquement au premier usage (~730 Mo en fp32 — contrainte de l'app, voir readme « ONNX Models »). Réglages : la longueur max de la légende générée. Les légendes sont en anglais (modèle entraîné sur des jeux de données anglophones).", en: "Describes an image's content in one sentence using Mozilla/distilvit (ViT + distilled GPT2, ~0.2B parameters, Apache 2.0 license). Runs in a Web Worker via Transformers.js, downloads and caches automatically on first use (~730 MB in fp32 — app-wide constraint, see readme « ONNX Models »). Settings: the max length of the generated caption. Captions are in English (model trained on English-language datasets)." },
  "texte-image": { fr: "Génère une image 512×512 depuis un prompt texte avec SDXS-512 (UNet distillé 1 pas + décodeur TAESD, quantifié int8, ~680 Mo). Tourne dans le process principal, CPU uniquement, ~10 s/image. Le modèle est embarqué avec l'application. Un bundle personnel s'indique par le paramètre « Chemin modèle ». Le modèle attend un prompt en anglais.", en: "Generates a 512×512 image from a text prompt using SDXS-512 (1-step distilled UNet + TAESD decoder, int8-quantized, ~680 MB). Runs in the main process, CPU only, ~10 s/image. The model is bundled with the app. A personal bundle is given by the “Model path” parameter. The model expects an English prompt." },
  "pure-data": { fr: "Génère un audio en exécutant un patch Pure Data (.pd). Le patch est interprété par libpd dans un AudioWorklet WebAssembly. Le fichier .pd se charge par le bouton du composant. Le patch s'exécute sur un buffer vide de la durée choisie et la sortie est capturée depuis les objets [dac~]. Les patches doivent être écrits sans [adc~] : ce composant ne reçoit pas d'audio d'entrée. Réglages : la bibliothèque d'objets (vanilla, cyclone, else, full) selon les objets utilisés par le patch. Les objets GUI (boutons, sliders, tableaux…) peuvent être ignorés avec l'option correspondante.", en: "Generates audio by running a Pure Data patch (.pd). The patch is interpreted by libpd in a WebAssembly AudioWorklet. The .pd file is loaded from the node's button. The patch runs on an empty buffer of the chosen duration and the output is captured from [dac~] objects. Patches must be written without [adc~]: this node receives no input audio. Settings: the object library (vanilla, cyclone, else, full) depending on the objects used by the patch. GUI objects (buttons, sliders, arrays…) can be ignored with the corresponding option." },
  "wahwah": { fr: "Filtre passe-bande dont la fréquence centrale est modulée par un LFO — l'effet pédale wah-wah classique. La fréquence centrale oscille entre 200 Hz et 2500 Hz. Réglages :\n• la vitesse (0.1 à 10 Hz)\n• la profondeur (amplitude du balayage)\n• la résonance (Q du filtre, élevé = wah prononcé)\n• le mix.\nIdéal sur les guitares électriques et les claviers.", en: "Bandpass filter with a LFO-modulated center frequency — the classic wah-wah pedal effect. The center frequency oscillates between 200 Hz and 2500 Hz. Settings:\n• the rate (0.1 to 10 Hz)\n• depth (sweep range)\n• resonance (filter Q, high = pronounced wah)\n• mix.\nIdeal on electric guitars and keyboards." },
  "phaser": { fr: "Filtres passe-tout en cascade dont la fréquence de coupure est modulée par un LFO. Crée des crêtes et creux mobiles dans le spectre — l'effet « planant » caractéristique des synthés analogiques et des guitares (Van Halen, Pink Floyd). Réglages :\n• la vitesse\n• la profondeur\n• le nombre d'étages (2 à 8, plus = plus prononcé)\n• le mix.", en: "All-pass filter cascade with a LFO-modulated cutoff frequency.\nCreates moving peaks and notches in the spectrum — the \"sweeping\" effect characteristic of analog synths and guitars (Van Halen, Pink Floyd). Settings:\n• rate\n• depth\n• number of stages (2 to 8, more = stronger)\n• mix." },
  "vibrato": { fr: "Modulation de hauteur par LFO : la note oscille autour de sa hauteur d'origine.\nDifférent du pitch shift (qui transpose fixe) — le vibrato fait varier la hauteur périodiquement. Réglages : la fréquence (vitesse, 0.1 à 20 Hz) et la profondeur (amplitude, 0 à ±2 demi-tons). Utilise un delay modulé pour préserver le timbre.", en: "Pitch modulation by LFO: the note oscillates around its original pitch. Different from pitch shift (which transposes statically) — vibrato varies the pitch periodically. Settings: the rate (speed, 0.1 to 20 Hz) and depth (amplitude, 0 to ±2 semitones). Uses a modulated delay to preserve timbre." },
  "octaver": { fr: "Ajoute une octave supérieure (doublement de fréquence par détection de zéros) et/ou une octave inférieure (décimation par 2). Le niveau de chaque octave et celui du signal original se règlent séparément. Effet guitare classique (Boss OC-3, eventide). L'octave inférieure fonctionne mieux sur des signaux monophoniques (une note à la fois).", en: "Adds an upper octave (frequency doubling via zero-crossing) and/or a lower octave (decimation by 2). Settings: each octave level and dry signal independently. Classic guitar effect (Boss OC-3, eventide). The lower octave works best on monophonic signals (one note at a time)." },
  "chopper": { fr: "Gate rythmique qui coupe le son périodiquement — effet stutter/DJ. Réglages :\n• la fréquence (coups par seconde, 0.5 à 20 Hz)\n• la durée du segment ON (1% = staccissimo, 50% = carré, 99% = quasi continu)\n• le type (Dur = coupure nette, Fondu = transition douce).\nProduit des effets de pompage, de gating rythmique ou de tremolo extrême.", en: "Rhythmic gate that chops the sound periodically — stutter/DJ effect. Settings:\n• the rate (cuts per second, 0.5 to 20 Hz)\n• ON segment length (1% = very short, 50% = square, 99% = near continuous)\n• type (Hard = abrupt, Soft = smooth).\nProduces pumping effects, rhythmic gating or extreme tremolo." },
  "chopper-logistique": { fr: "Gate rythmique dont la profondeur de coupe croît selon une courbe logistique : l'effet est inaudible au début, puis le gate devient de plus en plus marqué jusqu'à sa profondeur maximale. Réglages :\n• la fréquence (coups par seconde, 0.5 à 20 Hz)\n• la durée du segment ON\n• le type (Dur/Fondu)\n• la profondeur maximale (0 à 100%)\n• le centre (milieu de la transition)\n• la pente (raideur)\n• le mix.", en: "Rhythmic gate whose chopping depth rises along a logistic curve: the effect is inaudible at the start, then the gate becomes more and more pronounced up to its maximum depth.\nSettings:\n• the rate (cuts per second, 0.5 to 20 Hz)\n• ON segment length\n• type (Hard/Soft)\n• maximum depth (0 to 100%)\n• center (midpoint of the transition)\n• steepness\n• mix." },
  "decoupe-aleatoire": { fr: "Découpe une piste audio en parts égales et réarrange les tranches dans un ordre choisi.\nMode Random = ordre aléatoire, Original = ordre de départ, Reverse = ordre inverse. Le paramètre Parts règle le nombre de tranches (2 à 64), Crossfade ajoute un court fondu aux joints pour éviter les clics, et Graine permet de reproduire le même ordre aléatoire (0 = nouvel ordre à chaque exécution). Utile pour créer des variations rythmiques, des effets de glitch ou de remix.", en: "Slices an audio track into equal parts and rearranges the slices in a chosen order. Random mode = random order, Original = original order, Reverse = reversed order. The Parts parameter sets the number of slices (2 to 64), Crossfade adds a short fade at the joints to avoid clicks, and Seed lets you reproduce the same random order (0 = new order on each run). Useful for creating rhythmic variations, glitch or remix effects." },
  "generateur-paroles": { fr: "Génère des paroles de chanson structurées (couplets, refrain, pont, outro) sans modèle d'IA — par templates et tirage aléatoire dans des dictionnaires de mots. Saisissez un thème, une émotion, choisissez la langue (FR/EN) et le nombre de lignes par section. La structure varie aléatoirement (4 modèles). Chaque ligne est générée à partir de 12 modèles de phrases combinant sujets, verbes, objets, adjectifs, lieux, émotions et connecteurs. La graine permet de reproduire exactement les mêmes paroles. Instantané, hors-ligne, aucun téléchargement. Résultat à brancher sur une Sortie texte ou un TTS.", en: "Generates structured song lyrics (verse, chorus, bridge, outro) without an AI model — using templates and random word selection from dictionaries. Enter a theme, an emotion, choose the language (FR/EN) and the number of lines per section. The structure varies randomly (4 models). Each line is generated from 12 sentence templates combining subjects, verbs, objects, adjectives, places, emotions and connectors. The seed allows reproducing the exact same lyrics. Instant, offline, no download. Output to connect to a Text Output or TTS node." },
  "melangeur": { fr: "Additionne plusieurs pistes en une seule sortie. Ajoutez autant d'entrées que nécessaire. Il n'y a pas de niveau par piste, et pas de limiteur : les pistes sont sommées telles quelles, et la somme peut dépasser le plafond — trois pistes à 0,8 sortent à 2,4, ce qui écrête à l'écoute et à l'export. Le volume se règle sur le composant qui produit chaque piste, à la fois pour doser l'équilibre et pour garder de la marge.", en: "Sums several tracks into a single output. Add as many inputs as needed. There is no per-track level and no limiter: tracks are summed as they come, and the sum can exceed the ceiling — three tracks at 0.8 come out at 2.4, which clips on playback and on export. Settings:\n• the Volume on the node producing each track\n• both to balance them\n• to keep headroom." },
  "anneau-moebius": { fr: "Fait parcourir au son un anneau de Möbius.\nUn tour dure le son entier ; en avançant, la bande pivote d'un demi-tour, si bien qu'au bout d'un tour le son est revenu au départ… sur l'autre face. Il faut un deuxième tour pour le retrouver tel quel : c'est la propriété de l'anneau, et c'est elle que le composant rend audible. Face Stéréo : la largeur de la bande est la largeur stéréo ; l'image pivote continûment et gauche et droite sont échangées au bout d'un tour. Elle ne passe pas par le mono à mi-chemin : la composante qui sort du plan gauche/droite est portée par un déphasage de 90°, qui garde la largeur intacte — au centre, les deux canaux ont la même énergie sans être le même signal. Un son mono, ou stéréo aux deux canaux identiques, n'a pas de largeur à faire pivoter : il est posé sur le bord de la bande, part à gauche, passe à droite au premier tour et revient au second. À écouter au casque. Face Phase : l'autre face est le signal retourné. Faire tourner sa phase à vitesse constante revient à le décaler en fréquence d'un demi-hertz divisé par la durée du son — 0,05 Hz pour un son de 10 s. Seul, c'est à peine audible. Avec Mélange à 50 %, les deux faces s'annulent : le son entier s'éteint au bout d'un tour et revient au bout de deux. Ce n'est pas le balayage de creux d'un phaser, parce que l'original passe par le même déphaseur : l'écart de phase est le même à toutes les fréquences. Deux tours referment l'anneau ; un nombre impair finit sur l'autre face. Le son n'étant pas une boucle, chaque couture est cousue par un fondu enchaîné. Le déphasage est exact à ±0,7° de 20 Hz à 20 kHz ; en dessous de 20 Hz il se dégrade. La sortie est limitée à 20 minutes.", en: "Sends the sound around a Möbius strip. One lap lasts the whole sound; as it moves, the strip turns half a revolution, so after one lap the sound is back where it started… on the other side. A second lap is needed to find it unchanged: that is the strip's property, and the node makes it audible. Stereo side: the strip's width is the stereo width; the image turns continuously and left and right are swapped after one lap. It does not collapse to mono halfway: the component that leaves the left/right plane is carried by a 90° phase shift, which keeps the width intact — at the centre, both channels have the same energy without being the same signal.\n\nA mono sound, or a stereo one with identical channels, has no width to turn: it is placed on the strip's edge, starts left, moves right during the first lap and returns during the second. Best heard on headphones. Phase side: the other side is the inverted signal. Rotating its phase at a constant speed amounts to shifting it in frequency by half a hertz divided by the sound's length — 0.05 Hz for a 10 s sound. On its own it is barely audible. With Mix at 50%, the two sides cancel: the whole sound fades out after one lap and returns after two.\n\nThis is not a phaser's sweep of notches, because the original goes through the same phase shifter: the phase difference is the same at every frequency. Two laps close the strip; an odd number ends on the other side. Since the sound is not a loop, each seam is sewn with a crossfade. The phase shift is accurate to ±0.7° from 20 Hz to 20 kHz; below 20 Hz it degrades. Output is limited to 20 minutes." },
  "abc-vers-midi": { fr: "Lit une partition en notation ABC et la rend en MIDI et en audio. L'abc est une notation musicale en texte standardisée (ABC 2.1) : des milliers d'airs traditionnels circulent sous cette forme, les modèles de langage la connaissent, et c'est la langue des partitions de YuE2. Contrairement au format de « Texte → MIDI », elle porte la métrique (M:), la tonalité et les modes (K:), l'unité de durée (L:), le tempo (Q:), les mesures, les reprises et fins alternatives, les accords chiffrés et plusieurs voix (V:). Le MIDI produit en garde tout ce qui s'y écrit : une piste par voix sur son canal, une piste d'accompagnement pour les accords chiffrés sur un autre, la métrique, l'armure et le silence de début. La sortie Tonalité (« G major », « A dorian ») se branche sur les composants d'harmonie. Branché derrière « LLM Ollama », le composant rend ce que le modèle compose : les blocs de code et la phrase de présentation sont ignorés. Ce qui n'est pas lu est nommé dans le message plutôt qu'ignoré en silence : notes d'ornement, changements de tempo en cours de morceau, directives %%MIDI, fins alternatives multiples, accords chiffrés inconnus.", en: "Reads a score in ABC notation and renders it to MIDI and audio. ABC is a standardised text music notation (ABC 2.1): thousands of traditional tunes circulate in this form, language models know it, and it is the language of YuE2's scores. Unlike the « Text → MIDI » format, it carries the meter (M:), key and modes (K:), unit length (L:), tempo (Q:), bars, repeats and alternate endings, chord symbols and several voices (V:). The MIDI produced keeps everything that can be written there: one track per voice on its own channel, an accompaniment track for chord symbols on another, the meter, key signature and leading rest. The Key output (« G major », « A dorian ») connects to the harmony nodes. Placed after « LLM Ollama », the node renders what the model composes: code blocks and the introductory sentence are ignored. What is not read is named in the message rather than silently dropped: grace notes, mid-tune tempo changes, %%MIDI directives, multiple alternate endings, unknown chord symbols." },
  "reprise-abc": { fr: "Reprend une partition ABC dans un autre style : la mélodie et les accords chiffrés restent ceux de la partition, et le composant y ajoute une voix d'accompagnement et une ligne de basse qui suivent l'harmonie selon un motif — accords tenus, arpèges de ballade, accords sur les temps en pop, basse–accord–accord de valse, basse–accord de marche, bossa nova. Il rend l'audio, le MIDI à trois pistes (un instrument chacune) et l'ABC arrangé. C'est la reprise au sens de YuE2, en symbolique : même mélodie, autre habillage. Aucun modèle de langage n'intervient : les motifs sont déterministes, parce que la mesure faite pour « Édition ABC par LLM » a montré que les modèles locaux se trompent dès qu'ils écrivent des durées — et un accompagnement n'est fait que de durées. L'harmonie, elle, n'est pas touchée : elle relève d'une réharmonisation préalable. La mélodie d'origine est recopiée telle quelle, et son intégrité contrôlée à la fin. Chaque frappe s'arrête au changement d'accord suivant : un accord ne déborde jamais sur le suivant. Une partition sans accords chiffrés est refusée, avec l'indication de quoi faire ; un style qui ne s'applique pas à la métrique aussi — pas de bossa nova en 3/4, pas de marche sur un nombre impair de temps. Les morceaux qui commencent par une levée ne sont pas gérés.", en: "Covers an ABC score in another style: melody and chord symbols stay those of the score, and the node adds an accompaniment voice and a bass line that follow the harmony with a pattern — held chords, ballad arpeggios, pop chords on the beats, waltz bass–chord–chord, march bass–chord, bossa nova. It outputs the audio, a three-track MIDI (one instrument each) and the arranged ABC. This is a cover in YuE2's sense, symbolically: same melody, different arrangement. No language model is involved: the patterns are deterministic, because the measurement made for « ABC Editing by LLM » showed that local models go wrong as soon as they write durations — and an accompaniment is made of nothing but durations. To change the harmony too, first place « ABC Editing by LLM » in reharmonization. The original melody is copied as is, and its integrity checked at the end. Each hit stops at the next chord change: a chord never spills over the next one. A score without chord symbols is refused, with an indication of what to do; so is a style that does not fit the meter — no bossa nova in 3/4, no march on an odd number of beats. Tunes starting with a pickup are not handled." },
  "contraintes-abc": { fr: "Compare une partition ABC d'origine et une version retouchée, et dit si ce qui devait rester fixe l'est resté : nombre et durée des mesures, métrique, tonalité, mélodie ou rythme de la première voix, accords chiffrés, ambitus. Chaque violation est nommée et située — « mesure 4 : 3.5 temps au lieu de 4 », « mélodie modifiée à partir de la mesure 4 (note 29 : A4 → F#4) ». La sortie « ABC validé » ne transmet la retouche que si elle est conforme : branchée avant « ABC → MIDI », elle empêche une retouche fautive d'être jouée. Les comparaisons portent sur ce qui est joué, reprises déroulées : des reprises réécrites en toutes lettres ne sont pas une faute. Pourquoi ce composant : mesuré sur des modèles de langage locaux qui réécrivaient un morceau entier, aucune retouche n'était correcte sur 19, et l'une d'elles, qui semblait juste, avait perdu une note en posant un accord. Rien ne le signalait. Le composant ne dépend d'aucun modèle : il vaut autant pour une retouche faite à la main. Deux indicateurs de qualité accompagnent le verdict — part des temps forts dont la note appartient à l'accord, part des notes dans la gamme —, parce que la structure garantie ne dit rien de la musique.", en: "Compares an original ABC score with an edited version, and says whether what had to stay fixed did: number and length of bars, meter, key, melody or rhythm of the first voice, chord symbols, range. Each violation is named and located — « bar 4: 3.5 beats instead of 4 », « melody modified from bar 4 (note 29: A4 → F#4) ». The « Validated ABC » output only passes the edit on if it complies: placed before « ABC → MIDI », it prevents a faulty edit from being played. Comparisons apply to what is played, repeats unrolled: repeats rewritten in full are not a fault. Why this node: measured on local language models rewriting a whole tune, none of 19 edits was correct, and one that looked right had lost a note while placing a chord. Nothing flagged it. The node depends on no model: it applies just as well to a hand-made edit. Two quality indicators accompany the verdict — share of strong beats whose note belongs to the chord, share of notes in the scale — because guaranteed structure says nothing about the music." },
  "edition-abc-llm": { fr: "Retouche une partition ABC avec un modèle de langage local (Ollama), d'une façon qui l'empêche de casser ce qui doit rester fixe. La conception vient d'une mesure faite avant le développement : des modèles locaux à qui l'on demandait de réécrire le morceau entier ont échoué 19 fois sur 19, même relancés avec la liste de leurs erreurs — copie inchangée, en-tête perdu, mesures faussées, note disparue. Les mêmes modèles, à qui l'on ne demande que ce qui change, dans un format JSON imposé côté Ollama, ont réussi 20 fois sur 20.\n\nD'où deux opérations. Réharmoniser : le modèle rend un ou deux accords par mesure, que le composant pose sur la mélodie d'origine. Réécrire les hauteurs : il rend exactement une hauteur par note, que le composant pose sur le rythme d'origine, dans la tonalité choisie. Une réponse refusée — JSON illisible, accord inconnu, simple copie de l'original — est renvoyée au modèle avec la liste précise des problèmes, jusqu'au nombre d'essais choisi. Le résultat est ensuite vérifié comme par « Contraintes ABC ».\n\nCe qui n'est pas proposé : la variation libre du rythme, mesurée à 0 réussite sur 10, les modèles se trompant sur la durée des mesures. Ce qui n'est pas garanti : la qualité musicale — les accords proposés peuvent être plats ou étranges ; les deux indicateurs du rapport aident à le voir. Les morceaux qui commencent par une levée ne sont pas gérés. Nécessite Ollama et le modèle installés (« ollama pull gemma4:12b »).", en: "Edits an ABC score with a local language model (Ollama), in a way that prevents it from breaking what must stay fixed. The design comes from a measurement made before development: local models asked to rewrite the whole tune failed 19 times out of 19, even when sent back the list of their errors — unchanged copy, lost header, broken bars, missing note. The same models, asked only for what changes, in a JSON format enforced by Ollama, succeeded 20 times out of 20. Hence two operations. Reharmonize: the model returns one or two chords per bar, which the node places on the original melody. Rewrite pitches: it returns exactly one pitch per note, which the node places on the original rhythm, in the chosen key. A rejected answer — unreadable JSON, unknown chord, mere copy of the original — is sent back to the model with the precise list of problems, up to the chosen number of attempts. The result is then checked as by « ABC Constraints ». What is not offered: free rhythmic variation, measured at 0 successes out of 10, the models getting bar lengths wrong. What is not guaranteed: musical quality — the proposed chords may be bland or odd; the report's two indicators help see it. Tunes starting with a pickup are not handled. Requires Ollama and the model installed (« ollama pull gemma4:12b »)." },
  "midi-vers-abc": { fr: "Écrit un fichier MIDI en notation ABC, pour qu'une mélodie produite ici — Groove Box, séquenceurs, Magenta, capture — devienne une partition en texte qu'on peut lire, corriger, et donner à un modèle de langage, qui ne sait pas lire un MIDI. Le MIDI dit quand sonnent les notes, pas comment les écrire : quatre décisions sont prises, et le message les donne. La métrique : les composants écrivent tous 4/4 dans leurs fichiers, même pour une valse ; elle se choisit donc à la main, et n'est pas devinée.\n\nLa tonalité : déduite des notes par la méthode de Krumhansl, ou imposée ; elle fixe l'armure, donc l'écriture fa dièse ou sol bémol. La déduction n'est fiable que sur de l'harmonie — mesuré sur le Groove Box : juste 24 fois sur 24 sur la partie d'accords, 4 sur 24 sur la mélodie seule, 0 sur 24 sur la basse seule, sans que la confiance le laisse voir. Une ligne seule est signalée : imposez alors la tonalité, ou convertissez le fichier complet. La grille : la plus grossière sur laquelle toutes les notes tombent exactement — un MIDI généré ne bouge alors pas d'un tick —, ou à défaut une grille choisie, le message comptant les notes déplacées.\n\nLes voix : des notes qui commencent et finissent ensemble forment un accord, une basse tenue sous une mélodie en mouvement crée une seconde voix — ou, avec « Raccourcir en une ligne », la note tenue est coupée à l'attaque suivante, ce qui garde une mélodie legato lisible sur une seule ligne au prix de l'exactitude. Chaque canal est écrit à part ; la batterie (canal 10) est ignorée, l'ABC n'ayant pas de notation de percussion standard. Les notes qui passent une barre sont coupées et liées, les triolets écrits en (3.\n\nSeul le premier tempo est écrit, les instruments figurent en commentaire, les nuances ne sont pas écrites. Relue par « ABC → MIDI », la partition redonne exactement les mêmes notes sur du matériau calé sur la grille.", en: "Writes a MIDI file in ABC notation, so that a melody produced here — Groove Box, sequencers, Magenta, capture — becomes a readable text score, correctable, and usable by a language model, which cannot read MIDI. MIDI says when notes sound, not how to write them: four decisions are made, and the message states them. The meter: the nodes all write 4/4 into their files, even for a waltz; it is therefore picked by hand, not guessed. The key: inferred from the notes by Krumhansl's method, or imposed; it sets the key signature, hence F sharp or G flat.\n\nInference is only reliable on harmony — measured on the Groove Box: right 24 times out of 24 on the chord part, 4 out of 24 on the melody alone, 0 out of 24 on the bass alone, without the confidence revealing it. A single line is flagged: impose the key then, or convert the full file. The grid: the coarsest one on which every note falls exactly — a generated MIDI then does not move by a single tick — or failing that a chosen grid, the message counting moved notes.\n\nThe voices: notes starting and ending together form a chord, a bass held under a moving melody creates a second voice — or, with « Shorten into one line », the held note is cut at the next attack, keeping a legato melody readable on a single line at the cost of exactness. Each channel is written separately; drums (channel 10) are ignored, ABC having no standard percussion notation. Notes crossing a bar line are split and tied, triplets written as (3.\n\nOnly the first tempo is written, instruments appear as comments, dynamics are not written. Read back by « ABC → MIDI », the score gives exactly the same notes on grid-aligned material." },
  "tore": { fr:"Fait parcourir au son un tore, le produit de deux cercles, sur lesquels il avance à deux vitesses. Premier cercle, la position : l'image stéréo fait un tour complet par tour — gauche, centre, droite, centre, gauche —, un tour durant le son entier. Second cercle, le niveau : le son se mêle à une version de lui-même dont la phase tourne, si bien que tout le niveau respire, plein puis éteint puis plein. Le Rapport fixe la vitesse du niveau par rapport à la position. En p:q, les deux cercles ne retombent ensemble en place qu'au tour q : 2:3 au troisième, 5:8 au huitième. Le Nombre d'or ne se referme jamais — il frôle son départ aux termes de Fibonacci, 5, 8, 13 tours. Le message dit si la trajectoire s'est refermée, ou à quel tour et de combien de degrés elle est passée le plus près. Un son mono est posé sur un bord pour pouvoir tourner. À écouter au casque. La sortie est limitée à 20 minutes.", en: "Sends the sound around a torus, the product of two circles, along which it moves at two speeds. First circle, position: the stereo image turns one full revolution per lap — left, centre, right, centre, left — one lap lasting the whole sound. Second circle, level: the sound mixes with a version of itself whose phase rotates, so the whole level breathes, full then silent then full. The Ratio sets the level's speed relative to the position. With p:q, the two circles only fall back into place together at lap q: 2:3 at the third, 5:8 at the eighth. The Golden ratio never closes — it comes near its start at Fibonacci numbers, 5, 8, 13 laps. The message says whether the trajectory closed, or at which lap and by how many degrees it came closest. A mono sound is placed on an edge so it can turn. Best on headphones. Output is limited to 20 minutes." },
  "bouteille-klein": { fr: "Une bouteille de Klein se construit comme un tore — un cercle de base, et au-dessus de chaque point un cercle « fibre » — à une différence près : en faisant le tour de la base, la fibre revient retournée comme dans un miroir, et il faut deux tours pour qu'elle revienne à l'endroit. Ici, la base est l'étendue d'un Glissando de Risset, dont le haut est recollé au bas : une voix qui sort par l'aigu renaît dans le grave. La fibre est la position gauche/droite, et chaque voix recollée renaît de l'autre côté. Le miroir n'étant pas continu, il est caché là où Risset cache déjà le saut d'octave : dans le silence, la voix étant muette au moment où elle est recollée. Toutes les voix partent du même côté ; le glissando monte sans fin, et le son migre d'un côté à l'autre voix par voix, par le registre, avant de revenir. Le retour complet demande que chaque voix ait fait deux fois le tour de l'étendue : 2 × octaves × cycle, et le message dit si la durée choisie le laisse entendre. Pourquoi un miroir et non une rotation : une rotation peut se défaire, et l'objet obtenu ne serait qu'un tore. Chaque voix étant un point, une entrée stéréo est ramenée en mono. Comme pour le Glissando de Risset, une source riche et peu rythmée fonctionne le mieux.", en: "A Klein bottle is built like a torus — a base circle, and above each point a « fibre » circle — with one difference: going around the base, the fibre comes back flipped as in a mirror, and it takes two laps to come back the right way. Here the base is the range of a Risset glissando, whose top is glued to its bottom: a voice leaving through the high end is reborn in the low end. The fibre is the left/right position, and each glued voice is reborn on the other side. The mirror not being continuous, it is hidden where Risset already hides the octave jump: in silence, the voice being mute at the moment it is glued. All voices start on the same side; the glissando rises endlessly, and the sound migrates from one side to the other voice by voice, through the register, before coming back. The full return requires every voice to have gone around the range twice: 2 × octaves × cycle, and the message says whether the chosen length lets you hear it. Why a mirror and not a rotation: a rotation can be undone, and the object would only be a torus. Each voice being a point, a stereo input is mixed down to mono. As with the Risset glissando, a rich, loosely rhythmic source works best." },
  "tresse": { fr: "Découpe le son en 3 ou 4 bandes de fréquence — graves, médiums, aigus — et en fait les brins d'une tresse. Chaque bande occupe une place dans l'espace stéréo, la plus grave à gauche, la plus aiguë à droite. Le Mot décrit le motif : « 1 » fait passer le brin de la place 1 dessus celui de la place 2, « -1 » dessous, « 2 » concerne les places 2 et 3. À chaque croisement, deux bandes glissent l'une vers la place de l'autre ; celle qui passe dessus monte de 3 dB au milieu du croisement, celle qui passe dessous descend de 6 dB. Répété, un motif ramène chaque bande à sa place au bout d'un nombre de répétitions fixé par la permutation qu'il produit — 3 pour la natte classique « 1 -2 », 2 pour « 1 », 4 pour « 1 2 3 » sur quatre brins. Le message dit si les brins sont revenus. Les bandes sont découpées par des masques dont la somme vaut exactement 1 : sans croisement, elles redonnent le son d'origine. Chaque brin étant un point, une entrée stéréo est ramenée en mono. La tresse s'étale sur la durée du son, qui n'est pas bouclé.", en: "Splits the sound into 3 or 4 frequency bands — low, mid, high — and makes them the strands of a braid. Each band occupies a place in the stereo field, the lowest on the left, the highest on the right. The Word describes the pattern: « 1 » makes the strand in place 1 go over the one in place 2, « -1 » under, « 2 » concerns places 2 and 3. At each crossing, two bands glide towards each other's place; the one going over rises 3 dB mid-crossing, the one going under drops 6 dB. Repeated, a pattern brings each band back to its place after a number of repeats set by the permutation it produces — 3 for the classic plait « 1 -2 », 2 for « 1 », 4 for « 1 2 3 » on four strands. The message says whether the strands came back. Bands are cut by masks summing exactly to 1: without crossings, they give back the original sound. Each strand being a point, a stereo input is mixed down to mono. The braid is spread over the sound's length, which is not looped." },
  "ceinture-dirac": { fr: "Tenez un objet attaché à une ceinture et faites-le tourner d'un tour : il est revenu à sa place, mais la ceinture reste tordue. Il faut un second tour pour la dénouer. C'est la propriété des rotations dans l'espace que portent les spineurs : 360° changent leur signe, 720° le rétablissent. Ici, le son fait le tour de l'auditeur — devant, droite, derrière, gauche — pendant que sa phase tourne deux fois moins vite. Au bout d'un tour il est revenu devant, mais inversé ; au bout de deux, intact. Un signal inversé ne se distingue pas de l'original à l'oreille : le composant place donc devant l'auditeur une copie fixe du son, le Témoin. Quand le son qui tourne revient devant après un tour, il s'annule entièrement contre elle : le silence tombe au moment exact où il « est revenu ». Au second tour, les deux s'additionnent. Sans témoin, le tour s'entend mais pas la ceinture. Limite de la stéréo : deux haut-parleurs ne savent pas placer un son derrière soi ; l'arrière est simulé par un son plus faible (Arrière) et plus sourd (Coupure). Sans fonctions de transfert de tête, c'est une approximation. Une entrée stéréo est ramenée en mono.", en: "Hold an object attached to a belt and turn it one revolution: it is back in place, but the belt stays twisted. A second revolution is needed to untwist it. That is the property of rotations in space carried by spinors: 360° flips their sign, 720° restores it. Here the sound circles the listener — front, right, back, left — while its phase turns half as fast. After one lap it is back in front, but inverted; after two, intact. An inverted signal cannot be told from the original by ear: the node therefore places a fixed copy of the sound in front of the listener, the Witness. When the circling sound comes back to the front after one lap, it cancels out completely against it: silence falls at the exact moment it « has come back ». On the second lap, the two add up. Without a witness you hear the circling but not the belt. Stereo limitation: two speakers cannot place a sound behind you; the rear is simulated by a quieter (Rear) and duller (Cutoff) sound. Without head-related transfer functions, this is an approximation. A stereo input is mixed down to mono." },
  "miroir-inversion": { fr: "L'inversion géométrique échange l'intérieur et l'extérieur d'un cercle ; le cercle ne bouge pas, et appliquée deux fois elle rend chaque point à sa place. Ici, le cercle est une fréquence Pivot, et une composante à f va à pivot²/f : sur une échelle logarithmique, c'est un miroir exact. À 632 Hz, la bande audible est renvoyée sur elle-même — 100 Hz ↔ 4 kHz, 440 Hz ↔ 908 Hz — et une voix devient un sifflement dont les graves sont en haut. Le traitement est un vocodeur de phase qui déplace chaque partiel selon sa fréquence instantanée mesurée, ce qui garde les partiels nets au lieu de les poser sur une grille. Ce que le miroir coûte : une composante sous pivot²/Nyquist est renvoyée au-delà de la bande et disparaît — sous 18 Hz au pivot par défaut à 44,1 kHz, sous 17 Hz à 48 kHz — et le message chiffre l'énergie perdue ; le niveau est ramené à celui de l'énergie conservée. Contrairement à l'anneau de Möbius, il n'existe pas de passage continu entre l'original et son miroir : glisser de l'un à l'autre écraserait tout le spectre sur le pivot. D'où les Tours, qui alternent miroir et original par fondu enchaîné. Chaque canal est traité séparément.", en: "Geometric inversion swaps the inside and outside of a circle; the circle stays put, and applied twice it returns every point to its place. Here the circle is a Pivot frequency, and a component at f goes to pivot²/f: on a logarithmic scale, an exact mirror. At 632 Hz the audible band maps onto itself — 100 Hz ↔ 4 kHz, 440 Hz ↔ 908 Hz — and a voice becomes a whistle with its lows on top. The processing is a phase vocoder that moves each partial according to its measured instantaneous frequency, keeping partials sharp instead of snapping them to a grid. What the mirror costs: a component below pivot²/Nyquist is sent beyond the band and disappears — below 18 Hz at the default pivot at 44.1 kHz, below 17 Hz at 48 kHz — and the message states the energy lost; the level is brought back to that of the energy kept. Unlike the Möbius strip, there is no continuous path between the original and its mirror: sliding from one to the other would crush the whole spectrum onto the pivot. Hence the Laps, which alternate mirror and original with a crossfade. Each channel is processed separately." },
  "poussiere-cantor": { fr: "On retire le tiers central d'un segment, puis le tiers central de chacun des deux morceaux restants, et ainsi de suite. À l'étage n il reste 2ⁿ fragments de 1/3ⁿ de la durée, soit (2/3)ⁿ du son : une infinité de fragments pour une durée qui tend vers zéro. Et l'ensemble est auto-similaire : son premier tiers est l'ensemble entier, réduit trois fois. Ici, le son est gardé sur les fragments et rendu au silence ailleurs. Un étage seul s'entend comme un bégaiement ; la propriété s'entend en comparant les étages, d'où le mode Construction, qui joue les étages 0, 1, 2… à la suite : chaque fragment reprend en réduction le geste de l'étage précédent. Les parties retirées sont exactement silencieuses ; le Fondu est posé à l'intérieur des fragments gardés et borné à leur moitié, car aux étages profonds un fragment ne dure que quelques millisecondes. Le message donne le nombre de fragments, leur durée et la part du son gardée. Fonctionne sur tout son, et de façon particulièrement lisible sur une phrase parlée ou une boucle continue.", en: "Remove the middle third of a segment, then the middle third of each of the two remaining pieces, and so on. At level n there remain 2ⁿ fragments of 1/3ⁿ of the length, i.e. (2/3)ⁿ of the sound: infinitely many fragments for a length tending to zero. And the set is self-similar: its first third is the whole set, shrunk three times. Here the sound is kept on the fragments and silenced elsewhere. A single level sounds like a stutter; the property is heard by comparing levels, hence the Construction mode, which plays levels 0, 1, 2… one after the other: each fragment repeats the previous level's gesture in miniature. Removed parts are exactly silent; the Fade is placed inside the kept fragments and capped at half of them, since at deep levels a fragment lasts only a few milliseconds. The message gives the number of fragments, their length and the share of the sound kept. Works on any sound, and is especially readable on a spoken phrase or a continuous loop." },
  "score-esthetique": { fr: "Note un son avec Audiobox Aesthetics (Meta, 2025), un modèle entraîné sur 97 000 extraits de parole, de musique et d'effets notés par des auditeurs, sur quatre axes de 1 à 10. Plaisir (CE) : le plaisir d'écoute, l'impact émotionnel. Intérêt (CU) : la probabilité de réutiliser le son comme matière pour créer. Complexité (PC) : le nombre de composantes de la scène sonore. Qualité (PQ) : la qualité technique de la production — clarté, dynamique, spectre, spatialisation.\n\nLe modèle écoute par tranches de 10 s ; le score global est leur moyenne, pondérée par la durée réelle de chaque tranche, et la vue montre la courbe de chaque axe : elle dit où un morceau faiblit, ce que la moyenne cache — sur la collection de démonstration, un morceau de PQ global 7,7 a une tranche à 5,6. Le rapport donne, par axe, la tranche la plus basse et son écart au global. À savoir avant d'interpréter. PQ juge la netteté technique, pas la musique : un sinus pur obtient 7,0 en qualité et 2,9 en plaisir.\n\nPQ a appris qu'un bon son est propre et naturel : un effet volontairement destructeur (distorsion, poussière de Cantor, miroir d'inversion) sera noté bas, ce qui ne dit rien de sa valeur artistique. PC n'est pas corrélée à la qualité perçue de la parole, d'après l'article : pour une voix, ignorez-la. CE et CU sont des moyennes de goûts d'annotateurs, des tendances et non des verdicts. Le calcul prend environ 0,6 s par tranche sur processeur, soit une dizaine de secondes pour une chanson de 3 minutes.\n\nLe modèle est exécuté tel que publié, et mesuré contre le code PyTorch de Meta : mêmes scores à 0,00002 près sur 317 tranches, et un passage à 16 kHz identique à celui de torchaudio à 2·10⁻⁷ près — ce qui compte, une interpolation plus grossière déplaçant les scores jusqu'à 0,13. Dans l'application, deux fichiers de la collection de démonstration rendent les scores de référence au centième. Poids sous licence CC-BY 4.0 (Meta Platforms).", en: "Scores a sound with Audiobox Aesthetics (Meta, 2025), a model trained on 97,000 speech, music and sound-effect clips rated by listeners, on four axes from 1 to 10. Enjoyment (CE): listening pleasure, emotional impact. Usefulness (CU): how likely the sound is to be reused as material for creation. Complexity (PC): the number of components in the sound scene. Quality (PQ): the technical quality of the production — clarity, dynamics, spectrum, spatialization.\n\nThe model listens in 10 s windows; the overall score is their average, weighted by each window's actual length, and the view shows each axis' curve: it tells where a track weakens, which the average hides — in the demo collection, a track with an overall PQ of 7.7 has a window at 5.6. The report gives, per axis, the lowest window and its difference from the overall score. Worth knowing before interpreting. PQ judges technical cleanliness, not music: a pure sine scores 7.0 in quality and 2.9 in enjoyment.\n\nPQ has learned that a good sound is clean and natural: a deliberately destructive effect (distortion, Cantor dust, inversion mirror) will score low, which says nothing about its artistic value. According to the paper, PC does not correlate with perceived speech quality: for a voice, ignore it. CE and CU are averages of annotators' tastes, tendencies rather than verdicts. Scoring takes about 0.6 s per window on CPU, around ten seconds for a 3-minute song.\n\nThe model runs as published, and was measured against Meta's PyTorch code: the same scores within 0.00002 over 317 windows, and a conversion to 16 kHz identical to torchaudio's within 2·10⁻⁷ — which matters, as a coarser interpolation shifts the scores by up to 0.13. In the app, two files of the demo collection give the reference scores to the hundredth. Weights licensed CC-BY 4.0 (Meta Platforms)." },
  "comparaison-esthetique": { fr: "Compare deux versions d'un même son — un mix contre un autre, un son avant et après un traitement — sur les quatre axes d'Audiobox Aesthetics (voir « Score esthétique » pour leur sens et leurs limites). Chaque version est notée par tranches de 10 s, et le message donne l'écart B − A de chaque axe. L'entrée A tient l'original, l'entrée B la version traitée : pour CE, CU et PQ, un écart positif est un gain, que la vue colore en vert. Pas pour PC, qui compte des composantes et n'a pas de bon sens — elle reste en gris. Mesuré : un Bitcrusher 8 bits sur une annonce parlée fait perdre 0,25 en PQ et gagner 0,60 en PC, son bruit de quantification comptant comme une composante de plus. Même prudence que pour le score seul : sur un traitement créatif, une baisse de PQ ne veut pas dire « moins bien », et PC ne vaut rien pour la parole. Les deux sons n'ont pas besoin d'avoir la même durée. Le calcul prend environ 0,6 s par tranche de chaque version.", en: "Compares two versions of the same sound — one mix against another, a sound before and after processing — on the four Audiobox Aesthetics axes (see « Aesthetic Score » for their meaning and limits). Each version is scored in 10 s windows, and the message gives the B − A difference for each axis: connect the original to A and the processed version to B: for CE, CU and PQ, a positive difference is a gain, which the view colours green. Not for PC, which counts components and has no better direction — it stays grey. An 8-bit bitcrusher on a spoken announcement loses 0.25 in PQ and gains 0.60 in PC, its quantization noise counting as one more component. Same caution as for the single score: on a creative treatment, a lower PQ does not mean « worse », and PC is meaningless for speech. The two sounds need not have the same length. Scoring takes about 0.6 s per window of each version." },
  "debruitage-ia": { fr:"Débruite la parole avec GTCRN, un modèle appris de 344 ko (Xiaobin-Rong/gtcrn, licence MIT). Contrairement au nœud « Réduction de bruit », il n'a besoin d'aucun profil : rien à capturer sur un passage silencieux, et il suit un bruit qui varie. Deux limites à connaître, qui viennent du modèle et non de son intégration. Il travaille à 16 kHz : le résultat est rééchantillonné vers la fréquence d'entrée pour rester raccordable, mais rien n'est restitué au-dessus de 8 kHz. Et il a été entraîné sur de la parole : sur de la musique, il retire aussi ce qui n'est pas une voix. Le paramètre Force dose le mélange avec l'original — en dessous de 100 %, un peu de souffle et de réverbération reviennent, ce qui sonne souvent plus naturel que le silence complet entre les mots. Le message indique le niveau retiré, de quoi voir tout de suite si le modèle a agi : sur un enregistrement déjà propre il n'agit presque pas, ce qui est le bon comportement.", en: "Denoises speech with GTCRN, a 344 kB learned model (Xiaobin-Rong/gtcrn, MIT licence). Unlike the « Noise Reduction » node it needs NO profile: nothing to capture on a silent passage, and it follows noise that changes. Two limits worth knowing, both from the model rather than its integration. It works at 16 kHz: the result is resampled back to the input rate so it stays connectable, but nothing above 8 kHz is restored. And it was trained on speech: on music it also removes what is not a voice. The Strength parameter blends with the original — below 100%, some hiss and reverb come back, which often sounds more natural than complete silence between words. The message reports the level removed, which states at once whether the model acted: on an already clean recording it barely does, which is the right behaviour." },
  "reinserer-zone": { fr: "Replace une zone traitée à sa position d'origine dans la piste complète, avec un fondu enchaîné aux raccords. L'entrée « Zone traitée » reçoit l'extrait traité, « Piste » la piste complète, et « Zone » l'objet {debut, duree} qui dit où le replacer.", en: "Puts a processed zone back at its original position in the full track, with a crossfade at the joins. Connect the treated extract to the « Processed zone » input, the full track to « Track », and the zone object {start, duration} (for instance from the « Zones » output of the « Multi-Zone Selector » when a single zone is selected) to the « Zone » input." },
  "selecteur-multi-zones": { fr: "Affiche la forme d'onde et permet de sélectionner plusieurs zones (glisser puis « Ajouter »). La liste des zones est transmise sur la sortie « Zones ».", en: "Displays the waveform and lets you select several zones (drag then « Add »). The list of zones is passed on the « Zones » output." },
  "noms-instruments": { fr: "Émet sur sa sortie « Texte » une liste de noms d'instruments de musique (une centaine, réparties par famille : cordes, bois, cuivres, percussions, claviers, électronique, voix & monde). Réglages : une famille pour filtrer, et le format (virgule, retour ligne, puces). Utile comme source de texte ou de référence.", en: "Outputs a list of musical instrument names on its « Text » output (about a hundred, grouped by family: strings, woodwinds, brass, percussion, keyboards, electronic, voice & world). Settings: a family to filter, and the format (comma, newline, bullets). Handy as a text or reference source." },
  "styles-musicaux": { fr: "Émet sur sa sortie « Texte » une large collection de styles musicaux (plus de 200, répartis par catégorie : rock, métal, pop, électronique, hip-hop/rap, jazz, blues/soul/funk, country/folk, reggae/latin, classique/contemporain, world/traditionnel). Réglages : une catégorie pour filtrer, et le format (virgule, retour ligne, puces). Utile comme source de texte, pour l'étiquetage ou la classification.", en: "Outputs a large collection of musical styles on its « Text » output (over 200, grouped by category: rock, metal, pop, electronic, hip-hop/rap, jazz, blues/soul/funk, country/folk, reggae/latin, classical/contemporary, world/traditional). Settings: a category to filter, and the format (comma, newline, bullets). Handy as a text source, for tagging or classification." },
  "emotions": { fr: "Émet sur sa sortie « Texte » une collection d'émotions humaines (environ 160, réparties par catégorie : joie/bonheur, tristesse/mélancolie, colère/frustration, peur/anxiété, amour/tendresse, surprise/émerveillement, dégoût/rejet, mixte/complexe). Utile pour l'étiquetage de morceaux, la classification de sentiments ou comme source de texte.", en: "Outputs a collection of human emotions on its « Text » output (about 160, grouped by category: joy/happiness, sadness/melancholy, anger/frustration, fear/anxiety, love/tenderness, surprise/wonder, disgust/rejection, mixed/complex). Handy for track tagging, sentiment classification or as a text source." },
  "tessitures-voix": { fr: "Émet sur sa sortie « Texte » une collection de tessitures vocales classées par groupe (hommes, femmes, enfants). Chaque tessiture est accompagnée de sa plage approximative en notes (du grave à l'aigu). Inclut les catégories lyriques classiques (basse, baryton, ténor, contralto, mezzo-soprano, soprano et leurs sous-types) ainsi que les voix d'enfants.", en: "Outputs a collection of vocal ranges on its « Text » output, grouped by category (men, women, children). Each range includes its approximate note span (low to high). Covers classical lyric categories (bass, baritone, tenor, contralto, mezzo-soprano, soprano and their subtypes) as well as children's voices." },
  "generateur-script-ia": { fr: "Génère un prompt structuré pour un applicatif IA de génération musicale (Suno, Udio…). Les quatre entrées texte reçoivent un nom d'instrument, un style musical, une émotion et une tessiture de voix. Le node pioche aléatoirement un nombre configurable d'éléments dans chaque liste et compose un script avec : style, instruments, émotions, voix, un prompt en phrase et des tags. Une graine permet de reproduire un tirage. Les entrées sont facultatives — si une n'est pas branchée, elle est simplement ignorée.", en: "Generates a structured prompt for a music AI app (Suno, Udio…). Connect the text outputs of « Instrument Names », « Musical Styles », « Emotions » and « Vocal Ranges » nodes to the 4 corresponding inputs. The node randomly picks a configurable number of items from each list and composes a script with: style, instruments, emotions, vocals, a sentence prompt and tags. A seed allows reproducing a draw. Inputs are optional — if one is not connected, it is simply ignored." },
  "musicgen": { fr: "Génère de la musique depuis un prompt texte en utilisant MusicGen-small (facebook/musicgen-small, 300M de paramètres), exécuté en ONNX via Transformers.js. Le modèle se télécharge automatiquement depuis HuggingFace lors de la première utilisation (~300 MB, mis en cache par le navigateur). La génération est auto-régressive (séquentielle) et tourne dans un Web Worker pour ne pas bloquer l'interface. Écrivez un prompt descriptif en anglais (ex. « A happy upbeat pop song with electric guitars »), choisissez la durée (3-30 s) et le guidance (force du conditionnement). La première exécution est plus longue (téléchargement + chargement du modèle). Idéalement branché sur un node « Sortie audio » pour écouter le résultat.", en: "Generates music from a text prompt using MusicGen-small (facebook/musicgen-small, 300M parameters), run in ONNX via Transformers.js. The model auto-downloads from HuggingFace on first use (~300 MB, cached by the browser). Generation is auto-regressive (sequential) and runs in a Web Worker to avoid blocking the UI. Write a descriptive prompt in English (e.g. « A happy upbeat pop song with electric guitars »), set the duration (3-30 s) and guidance (conditioning strength). First run is slower (download + model loading). Ideally connected to an « Audio Output » node to listen to the result." },
  "source-texte": { fr: "Émet un texte saisi par l'utilisateur sur sa sortie texte (port bleu). Sa sortie alimente n'importe quelle entrée texte du graphe.", en: "Outputs user-entered text on its text output (blue port). Its output feeds any text input in the graph." },
  "tts-speecht5": { fr: "Synthèse vocale haute qualité utilisant Microsoft SpeechT5. L'entrée texte (port bleu) reçoit le texte à dire. Le modèle génère de la parole en anglais avec une voix naturelle. Réglages :\n• l'une des 7 voix prédéfinies (embeddings CMU Arctic) : 2 femmes américaines (SLT, CLB)\n• 2 hommes américains (BDL, RMS)\n• 1 homme canadien (JMK)\n• 1 homme écossais (AWB)\n• 1 homme indien (KSP).\nLe modèle se télécharge depuis HuggingFace au premier usage (~150 MB, mis en cache). Tourne dans un Web Worker.", en: "High-quality text-to-speech using Microsoft SpeechT5. Connect a « Text Source » node to the text input (blue port). The model generates English speech with a natural voice. Settings:\n• one of 7 preset voices (CMU Arctic embeddings): 2 US females (SLT, CLB)\n• 2 US males (BDL, RMS)\n• 1 Canadian male (JMK)\n• 1 Scottish male (AWB)\n• 1 Indian male (KSP).\nThe model downloads from HuggingFace on first use (~150 MB, cached). Runs in a Web Worker." },
  "tts-mms": { fr: "Synthèse vocale multilingue utilisant Meta MMS (Massively Multilingual Speech). L'entrée texte (port bleu) reçoit le texte à dire. Réglages : la langue parmi 10+ options (anglais, français, espagnol, allemand, italien, portugais, néerlandais, roumain, polonais, russe). Chaque langue utilise un modèle MMS dédié qui se télécharge au premier usage (~60 MB chacun, mis en cache). Tourne dans un Web Worker.", en: "Multilingual text-to-speech using Meta MMS (Massively Multilingual Speech). Connect a « Text Source » node to the text input (blue port). Settings: the language, among 10+ (English, French, Spanish, German, Italian, Portuguese, Dutch, Romanian, Polish, Russian). Each language uses a dedicated MMS model that downloads on first use (~60 MB each, cached). Runs in a Web Worker." },
  "whisper-en": { fr: "Transcription vocale en anglais utilisant OpenAI Whisper (base). L'entrée audio (port vert) reçoit le signal à transcrire. Le modèle transcrit le discours en texte et l'émet sur la sortie texte (port bleu). Le modèle se télécharge depuis HuggingFace au premier usage (~75 MB, mis en cache). Tourne dans un Web Worker. L'audio est automatiquement mixé en mono et rééchantillonné à 16 kHz.", en: "English speech recognition using OpenAI Whisper (base). Connect an audio signal (green port) — e.g. an « Audio Input » or « Recorder » node. The model transcribes the speech to text and outputs it on the text output (blue port). The model downloads from HuggingFace on first use (~75 MB, cached). Runs in a Web Worker. Audio is automatically mixed to mono and resampled to 16 kHz." },
  "sherpa-asr": { fr: "Reconnaissance vocale locale via Sherpa-ONNX (Whisper tiny multilingue). L'entrée verte reçoit l'audio à transcrire. Le texte transcrit est émis sur la sortie bleue. Le modèle ONNX (~100 MB) se télécharge depuis HuggingFace au premier usage. Exécute dans un Web Worker dédié.", en: "Local speech recognition via Sherpa-ONNX (multilingual Whisper tiny). Connect audio to the green input. Transcribed text is emitted on the blue output. The ONNX model (~100 MB) downloads from HuggingFace on first use. Runs in a dedicated Web Worker." },
  "traduction-opus": { fr: "Traduit un texte entre paires de langues en utilisant OPUS-MT (Helsinki-NLP, modèles Marian). L'entrée (port bleu) reçoit le texte à traduire. Réglages : la paire de langues (18 paires disponibles : français↔anglais, anglais↔espagnol, allemand, italien, japonais, chinois, russe, portugais, néerlandais, arabe, hindi). Chaque paire utilise un modèle dédié léger (~30 MB) qui se télécharge au premier usage et est mis en cache. Tourne dans un Web Worker. Traduction rapide et directe texte→texte.", en: "Translates text between language pairs using OPUS-MT (Helsinki-NLP, Marian models). Connect a « Text Source » node to the input (blue port). Settings: the language pair (18 pairs available: French↔English, English↔Spanish, German, Italian, Japanese, Chinese, Russian, Portuguese, Dutch, Arabic, Hindi). Each pair uses a dedicated lightweight model (~30 MB) that downloads on first use and is cached. Runs in a Web Worker. Fast direct text→text translation." },
  "prompt-vers-graphe": { fr: "Génère un graphe de nodes sur le canevas depuis un prompt en langage naturel. La description vient du champ du composant ou de l'entrée texte — par exemple « delay stéréo avec feedback court sur une réverbération hall puis compresseur et sortie ». Deux méthodes (paramètre Méthode) : Mots-clés (par défaut, hors-ligne, reconnaît ~40 mots-clés en français et anglais parmi sources, effets, analyse et sorties) ou Ollama (IA) — un modèle local interprète des tournures libres et choisit lui-même les blocs pertinents dans tout le catalogue installé ; nécessite « ollama serve » et retombe automatiquement sur Mots-clés en cas d'échec. Les nodes détectés sont connectés en chaîne (source → effets → analyse → sortie) et ajoutés au canevas. Sert à explorer les possibilités sans connaître le catalogue par cœur.", en: "Generates a node graph on the canvas from a natural language prompt. Enter a description (e.g. « stereo delay with short feedback on a hall reverb then compressor and output ») or connect a « Text Source » node. Two methods (Method parameter): Keywords (default, offline, recognizes ~40 keywords in French and English across sources, effects, analysis and outputs) or Ollama (AI) — a local model interprets free-form phrasing and picks the relevant blocks from the whole installed catalog itself; requires « ollama serve » and automatically falls back to Keywords on failure. Detected nodes are chained (source → effects → analysis → output) and added to the canvas. Magical for discovering the app's possibilities without knowing the catalog." },
  "generateur-bruit": { fr: "Génère du bruit — un signal aléatoire utile pour tester filtres et enveloppes, ou comme matière sonore. Blanc : toutes les fréquences au même niveau (spectre plat, sifflant). Rose : −3 dB par octave, perçu équilibré (proche de la pluie). Brownien : −6 dB par octave, grave et sourd. La coloration se lit sur une analyse spectrale.", en: "Generates noise — a random signal handy for testing filters and envelopes, or as raw sound material. White: all frequencies at equal level (flat, hissy spectrum). Pink: −3 dB per octave, perceptually balanced (rain-like). Brownian: −6 dB per octave, dark and muffled. The coloration can be read on a spectral analysis." },
  "generateur-frequence": { fr: "Génère une tonalité pure à une fréquence précise. Deux modes de saisie : en Hertz (20-20000 Hz) ou en note musicale (format A4, C#5, Bb3). Quatre formes d'onde : sinus (une seule fréquence, pur), carré (harmoniques impaires, son riche), dent de scie (toutes les harmoniques, brillant) et triangle (harmoniques impaires douces). Un fondu entrée/sortie de 10 ms évite les clics. Sert à étalonner l'oreille, éprouver des filtres, accorder un instrument, ou de référence. La forme d'onde et le spectre se lisent sur une analyse.", en: "Generates a pure tone at a precise frequency. Two input modes: in Hertz (20-20000 Hz) or as a musical note (format A4, C#5, Bb3). Four waveforms: sine (single frequency, pure), square (odd harmonics, rich), sawtooth (all harmonics, bright) and triangle (soft odd harmonics). A 10 ms fade in/out avoids clicks. Used for ear training, testing filters, tuning an instrument, or as a reference. The waveform and spectrum can be read on an analysis." },
  "metronome": { fr: "Génère un signal audio de métronome : un clic régulier à un tempo donné (40-240 BPM), avec signature rythmique (4/4, 3/4, 2/4, 6/8, 5/4, 7/8). Le premier temps de chaque mesure est accentué (plus fort et plus aigu). Trois timbres au choix : Clic (transitoire court, bruit), Woodblock (résonance bois) et Bip (sinus bref). Utile pour s'entraîner, caler un tempo de référence ou générer une piste de clic pour un enregistrement.", en: "Generates a metronome audio signal: a steady click at a given tempo (40-240 BPM), with time signature (4/4, 3/4, 2/4, 6/8, 5/4, 7/8). The first beat of each bar is accented (louder and higher). Three timbres: Click (short transient, noise), Woodblock (woody resonance) and Beep (brief sine). Useful for practice, setting a reference tempo or generating a click track for recording." },
  "membrane-synth": { fr: "Génère un coup de grosse caisse synthétique à l'aide de Tone.js MembraneSynth. Le son est rendu en offline pour produire directement un buffer audio. Réglages :\n• la note (hauteur)\n• la durée\n• le volume\n• la chute de hauteur (pitch decay)\n• la portée en octaves\n• le decay\n• le release.", en: "Generates a synthetic kick drum using Tone.js MembraneSynth.\nThe sound is rendered offline to directly produce an audio buffer. Settings:\n• the note (pitch)\n• duration\n• volume\n• pitch decay\n• octave range\n• decay\n• release." },
  "metal-synth": { fr: "Génère un son métallique inharmonique (hi-hat, cloche, cymbale) avec Tone.js MetalSynth.\nLe son est rendu en offline pour produire directement un buffer audio. Réglages :\n• la note (hauteur)\n• la durée\n• le volume\n• l'harmonicité\n• l'index de modulation\n• la résonance\n• les octaves de filtre\n• l'enveloppe.", en: "Generates an inharmonic metallic sound (hi-hat, bell, cymbal) using Tone.js MetalSynth.\nThe sound is rendered offline to directly produce an audio buffer. Settings:\n• the note (pitch)\n• duration\n• volume\n• harmonicity\n• modulation index\n• resonance\n• filter octaves\n• envelope." },
  "poly-synth": { fr: "Génère un accord polyphonique avec Tone.js PolySynth.\nChaque voix utilise un oscillateur simple (sinus, carré, dent de scie, triangle) avec une enveloppe ADSR complète. Saisissez les notes séparées par des virgules. Le son est rendu en offline pour produire directement un buffer audio.", en: "Generates a polyphonic chord using Tone.js PolySynth. Each voice uses a simple oscillator (sine, square, sawtooth, triangle) with a full ADSR envelope. Enter notes separated by commas. The sound is rendered offline to directly produce an audio buffer." },
  "fm-synth": { fr: "Génère une note avec modulation de fréquence (FM) ou d'amplitude (AM) via Tone.js. Réglages :\n• le mode\n• la note\n• la durée\n• l'harmonicité\n• l'index de modulation\n• l'enveloppe ADSR.\nLe son est rendu en offline.", en: "Generates a note using frequency modulation (FM) or amplitude modulation (AM) via Tone.js. Settings:\n• the mode\n• note\n• duration\n• harmonicity\n• modulation index\n• ADSR envelope.\nThe sound is rendered offline." },
  "pluck-synth": { fr: "Génère une note de corde pincée par synthèse Karplus-Strong avec Tone.js PluckSynth. Réglages :\n• la note\n• le bruit d'attaque\n• le dampening\n• la résonance\n• le release.\nLe son est rendu en offline.", en: "Generates a plucked string note using Karplus-Strong synthesis with Tone.js PluckSynth. Settings:\n• the note\n• attack noise\n• dampening\n• resonance\n• release.\nThe sound is rendered offline." },
  "drum-synth": { fr: "Reçoit un fichier MIDI en entrée et le rend en audio avec des synthétiseurs de batterie (MembraneSynth, MetalSynth, NoiseSynth). Les notes General MIDI sont mappées : grosse caisse (36), caisse claire (38), charley (42/46), crash (49), toms (45/47/48/50). Sortie audio + sortie MIDI identique pour chaîner vers d'autres nodes. Ne dépend d'aucun SoundFont de batterie.", en: "Receives a MIDI file as input and renders it to audio with drum synthesizers (MembraneSynth, MetalSynth, NoiseSynth). General MIDI notes are mapped: kick (36), snare (38), hi-hat (42/46), crash (49), toms (45/47/48/50). Audio output + identical MIDI output for chaining. Depends on no drum SoundFont." },
  "boite-groove": { fr: "Génère une boucle complète : progression d'accords déterministe (style ou progression romaine personnalisée) + mélodie émergente par réservoir de neurones + batterie. La mélodie du réservoir est quantifiée aux notes de l'accord courant pour rester consonante. Sortie audio stéréo + quatre sorties MIDI séparées (batterie, accords, basse, mélodie). En mode FM, la batterie est synthétisée par le drum-synth interne ; en mode SoundFont, les parties mélodiques sont rendues avec le SoundFont chargé. Même graine = même mélodie aléatoire.", en: "Generates a complete loop: deterministic chord progression (style or custom Roman numeral progression) + emergent melody from a neural reservoir + drums. The reservoir melody is snapped to the current chord tones to stay consonant. Stereo audio output + four separate MIDI outputs (drums, chords, bass, melody). In FM mode, drums are synthesized by the internal drum synth; in SoundFont mode, the melodic parts are rendered with the loaded SoundFont. Same seed = same random melody." },
  "reservoir-musical": { fr: "Génère une mélodie émergente par réseau de neurones aléatoires (Reservoir Computing), inspiré du plugin EVY d'Allendia (startup Inria). Un « réservoir » de quelques neurones à poids aléatoires fixes (non entraînés) fait circuler une impulsion rythmique. Les activations sont mappées sur une gamme pour produire des motifs mélodiques. Aucun entraînement, aucun dataset, aucun copyright — les motifs émergent de la structure aléatoire du réseau, comme un kaléidoscope. Le composant possède maintenant une sortie audio (rendue localement avec le timbre et le volume choisis) et une sortie MIDI (fichier MIDI branchable sur Transposeur/Quantiseur, Arpégiateur ou Sortie MIDI). Paramètres : nombre de neurones (5-50, peu = motifs accrocheurs, beaucoup = complexe), connectivité, mémoire (leaking), rayon spectral (<100% = stable, >100% = chaotique), gamme, clé, octave, tempo, résolution, densité de notes, répétition, silence, graine, timbre, volume et instrument. Graine non nulle = même réseau = même mélodie. Graine 0 = nouveau réseau aléatoire à chaque exécution.", en: "Generates emergent melody via random neural networks (Reservoir Computing), inspired by Allendia's EVY plugin (Inria startup). A \"reservoir\" of a few neurons with fixed random weights (untrained) circulates a rhythmic impulse. Activations are mapped to a scale to produce melodic patterns. No training, no dataset, no copyright — patterns emerge from the random network structure, like a kaleidoscope. The node now has an audio output (rendered locally with the chosen timbre and volume) and a MIDI output (a MIDI file that can be connected to a Transposer/Quantizer, Arpeggiator or MIDI Output). Parameters: neuron count (5-50, few = catchy patterns, many = complex), connectivity, memory (leaking), spectral radius (<100% = stable, >100% = chaotic), scale, key, octave, tempo, resolution, note density, repetition, silence, seed, timbre, volume and instrument. Non-zero seed = same network = same melody. Seed 0 = new random network each run." },
  "multi-reservoirs": { fr: "Quatre réservoirs neuronaux en réseau, chacun avec un rôle musical distinct : mélodie (voix principale, octave 4), basse (octave grave, mémoire longue), harmonie (notes tenues, peu denses) et rythme (détermine quand les autres jouent). Les réservoirs s'influencent mutuellement via le paramètre « Influence » : le rythme filtre les pas actifs des autres voix, créant une cohérence polyphonique émergente. Le composant sort un mix audio stéréo + quatre fichiers MIDI indépendants (mélodie, basse, harmonie, rythme) pour piloter d'autres synthétiseurs ou boîtes à rythmes.\n\nLa piste rythme MIDI utilise les notes de batterie General MIDI (grosse caisse, caisse claire, charley, etc.) et le paramètre « Kit de batterie » sélectionne le preset du SoundFont à utiliser. Chaque réservoir a ses propres paramètres (neurones, connectivité) + paramètres globaux (clé, gamme, tempo, timbre, graine). Aucun entraînement — l'émergence naît de l'interaction entre réseaux aléatoires. Inspiré d'Allendia/EVY, poussé vers le polyphonique.\n\nChaque sortie MIDI porte son propre instrument, écrit dans le fichier pour qu'un composant qui le rend en aval le suive, et chaque partie a son canal — mélodie 0, basse 1, harmonie 2, rythme 9. « Suivre le MIDI » n'écrit rien. Au SoundFont — le mode « Automatique » le choisit dès qu'un SF2 est chargé — ces instruments sont aussi ceux qu'on entend : les quatre parties sont réunies et jouées comme un seul MIDI. En synthèse interne, le composant garde ses timbres d'oscillateur, et les choix ne valent que pour les fichiers MIDI.", en: "Four neural reservoirs in network, each with a distinct musical role: melody (lead voice, octave 4), bass (low octave, long memory), harmony (held notes, sparse) and rhythm (determines when others play). The reservoirs influence each other via the « Influence » parameter: rhythm filters the active steps of other voices, creating emergent polyphonic coherence. The node outputs a stereo audio mix + four independent MIDI files (melody, bass, harmony, rhythm) to drive other synthesizers or drum machines. The rhythm MIDI track uses standard GM drum notes (kick, snare, hi-hat, etc.) and the « Drum kit » parameter selects the SoundFont preset for it. Each reservoir has its own parameters (neurons, connectivity) + global parameters (key, scale, tempo, timbre, seed). No training — emergence arises from interaction between random networks. Inspired by Allendia/EVY, pushed towards polyphony. Each MIDI output carries its own instrument, written into the file so a node rendering it downstream follows it, and each part has its own channel — melody 0, bass 1, harmony 2, rhythm 9. « Follow MIDI » writes nothing. With the SoundFont — « Auto » picks it as soon as an SF2 is loaded — these instruments are also what you hear: the four parts are merged and played as a single MIDI. With the built-in synthesis, the node keeps its oscillator timbres and the choices only apply to the MIDI files." },
  "enveloppe-adsr": { fr: "Modèle le volume du son au cours du temps selon quatre réglages : Attaque (temps de montée au maximum), Déclin (descente vers le maintien), Maintien (niveau tenu, pas une durée) et Relâchement (retour au silence en fin de son). Attaque courte = son percussif ; longue = son qui gonfle. La courbe se met à jour en direct.", en: "Shapes the sound's volume over time with four controls: Attack (rise time to peak), Decay (fall to the sustain level), Sustain (held level, not a duration) and Release (return to silence at the end). Short attack = percussive; long = swelling. The curve updates live." },
  "sampler-midi": { fr: "Reçoit des notes MIDI en entrée et les joue avec un échantillon audio chargé dans l'inspecteur. Chaque note MIDI est transposée à partir de la « Note référence » (la hauteur d'origine de l'échantillon). La sortie audio contient la mélodie jouée avec le timbre de l'échantillon. La sortie MIDI passe les notes à travers inchangées, permettant de chaîner vers d'autres nodes MIDI. L'entrée reçoit le MIDI qui déclenche les notes, et l'inspecteur tient l'échantillon — percussion, voix, instrument.", en: "Receives MIDI notes at the input and plays them with an audio sample loaded from the inspector. Each MIDI note is transposed from the « Reference note » (the original pitch of the sample). The audio output contains the melody played with the sample's timbre. The MIDI output passes notes through unchanged, allowing chaining to other MIDI nodes. Connect a MIDI Player, a sequencer or a MIDI reservoir to the input, then load a short audio file (percussion, voice, instrument) in the inspector." },
  "point-ecoute-midi": { fr: "Point d'écoute intermédiaire pour le MIDI : permet d'auditionner le signal MIDI à un endroit de la chaîne sans l'interrompre. Le MIDI reçu est transmis tel quel sur la sortie.", en: "Intermediate listening point for MIDI: lets you audition the MIDI signal at a spot in the chain without interrupting it. The received MIDI is passed through unchanged to the output." },
  "sequenceur-batterie-avance": { fr: "Programme un motif de batterie avancé sur 8 pistes (grosse caisse, caisse claire, charley fermé, charley ouvert, clap, crash, tom grave, tom aigu). Une case cliquée s'allume ou s'éteint, comme dans les autres séquenceurs ; la nuance est sur les modificateurs — Maj+clic monte la velocity d'un cran (0 à 9), Alt+clic la descend. Une case allumée au clic reprend la velocity qu'elle avait avant d'être éteinte, ou 6 si elle n'en a jamais eu. Plus la velocity est élevée, plus la case est lumineuse et le son fort. Les sons sont synthétisés (style boîte à rythmes), sans SoundFont. Réglages :\n• le tempo\n• le nombre de pas (16 ou 32)\n• le swing\n• le nombre de mesures ; la sortie audio boucle le motif.\nUne seconde sortie donne le même rythme en MIDI, sur le canal 10 des percussions et aux numéros du General MIDI (36 grosse caisse, 38 caisse claire, 42 charley fermé…) : le même rythme se rejoue ainsi avec d'autres sons. Les nuances de la grille y deviennent des vélocités et le swing y est appliqué : le groove survit au changement de sons.", en: "Programs an advanced drum pattern on 8 tracks (kick, snare, closed hi-hat, open hi-hat, clap, crash, low tom, high tom). A clicked cell turns on or off, as in the other sequencers; nuance is on the modifiers — Shift+click raises velocity one step (0 to 9), Alt+click lowers it. A cell turned back on recovers the velocity it had before being cleared, or 6 if it never had one. Higher velocity makes the cell brighter and the sound louder. Sounds are synthesized (drum-machine style), no SoundFont. Settings:\n• tempo\n• number of steps (16 or 32)\n• swing\n• bars; the audio output loops the pattern.\nA second output gives the same rhythm as MIDI, on percussion channel 10 and at the General MIDI numbers (36 kick, 38 snare, 42 closed hi-hat…): the same rhythm can thus be played with other sounds. The grid's nuances become velocities there and swing is applied: the groove survives the change of sounds." },
  "sequenceur-melodique": { fr: "Programme une mélodie sur une grille piano-roll pas-à-pas : chaque rangée est une note de la gamme (aigu en haut, grave en bas), chaque colonne est un pas. Les cases cliquées activent les notes. Les notes sont synthétisées au choix en triangle, carré, dent de scie ou sinus, ou avec un SoundFont global chargé. Réglages :\n• la clé\n• la gamme (majeur, mineur, pentatonique, blues)\n• l'octave de départ\n• le tempo\n• le swing\n• le nombre de mesures ; la sortie audio boucle le motif.\nEn mode SoundFont, un paramètre Instrument permet de choisir le preset (programme 0 par défaut). La sortie MIDI reproduit le même motif pour le chaîner vers d'autres nodes MIDI. La fondamentale est surlignée en jaune dans les étiquettes.", en: "Programs a melody on a step-by-step piano-roll grid: each row is a scale note (high at top, low at bottom), each column is a step. Clicked cells activate notes. Notes are synthesized with a choice of triangle, square, sawtooth or sine waveform, or with a loaded global SoundFont. Settings:\n• the key\n• scale (major, minor, pentatonic, blues)\n• starting octave\n• tempo\n• swing\n• number of bars; the audio output loops the pattern.\nIn SoundFont mode, an Instrument parameter lets you pick the preset (default program 0). The MIDI output reproduces the same pattern for chaining to other MIDI nodes. The root note is highlighted in yellow in the labels." },
  "sequenceur-accords": { fr: "Programme une progression d'accords sur une grille pas-à-pas : 21 rangées = 7 degrés × 3 lignes (triade, 7e, 6e). Les étiquettes sont les noms d'accords dans la tonalité choisie (ex. C, Cmaj7, C6, Dm, Dm7, Dm6…). Chaque colonne active un seul accord à la fois. Une case cliquée donne l'accord joué à ce pas. Réglages :\n• le mode Harmonie (accord en bloc) ou Arpège (notes légèrement décalées)\n• ainsi que la clé\n• la gamme\n• l'octave\n• le tempo\n• le swing\n• le nombre de mesures\n• le mode de synthèse (FM ou SoundFont).\nLa sortie audio boucle le motif ; la sortie MIDI reproduit le même motif pour le chaîner vers d'autres nodes MIDI.", en: "Programs a chord progression on a step grid: 21 rows = 7 degrees × 3 rows (triad, 7th, 6th). Labels are chord names in the chosen key (e.g. C, Cmaj7, C6, Dm, Dm7, Dm6…). Each column activates only one chord at a time. A clicked cell gives the chord played at that step. Settings:\n• Harmony mode (block chord) or Arpeggio (notes slightly staggered)\n• plus the key\n• scale\n• octave\n• tempo\n• swing\n• number of bars\n• synthesis mode (FM or SoundFont).\nThe audio output loops the pattern; the MIDI output reproduces the same pattern for chaining to other MIDI nodes." },
  "masque-zones": { fr: "Applique la liste de zones (venue du « Sélecteur multi-zones ») comme un masque sur l'audio. Option « Supprimer les zones » : le son est coupé dans les zones, le reste est conservé. Option « Conserver les zones » : seules les zones sont gardées, le reste est coupé. La piste garde sa durée ; un fondu aux bords évite les clics.", en: "Applies the zone list (from the « Multi-Zone Selector ») as a mask on the audio. « Mute zones » option: sound is cut inside the zones, the rest is kept. « Keep zones » option: only the zones are kept, the rest is cut. The track keeps its duration; an edge fade avoids clicks." },
  "extraire-zones-selecteur": { fr: "Découpe et assemble les zones choisies dans le « Sélecteur multi-zones ». Les entrées « Zones » et « Audio » reçoivent les zones et la piste dont elles ont été tirées. Le mode par défaut conserve les zones sélectionnées et les raboute les unes aux autres (les parties non sélectionnées disparaissent). Le mode inverse ne conserve que les parties entre les zones sélectionnées. Un fondu aux bords de chaque zone extraite évite les clics. Sortie « Audio » = l'assemblage ; sortie « Zones » = la liste des segments conservés avec leur position dans le nouvel audio.", en: "Cuts and joins the zones chosen in the « Multi-Zone Selector ». Connect the selector's « Zones » output to this node's « Zones » input, and the selector's « Audio » output to the « Audio » input. Default mode keeps the selected zones and concatenates them (unselected parts disappear). Invert mode keeps only the parts between the selected zones. A fade at the edges of each extracted zone prevents clicks. « Audio » output = the joined clip; « Zones » output = the list of kept segments with their position in the new audio." },
  "placer-sons-zones": { fr: "Insère une copie du son reçu sur l'entrée « Son » au centre de chaque zone de la liste. Si une piste est branchée sur l'entrée « Piste », le son est ajouté sur cette piste. Sinon, une piste silencieuse de la durée fournie est créée. Les entrées « Zones » et « Durée » reçoivent les zones à remplir et la durée totale.", en: "Inserts a copy of the sound received on the « Sound » input at the center of each zone in the list. If a track is connected to the « Track » input, the sound is added onto that track. Otherwise, a silent track of the given duration is created. Connect the « Zones » and « Duration » outputs of the « Multi-Zone Selector » to get the zones and duration." },
  // ── Théorie musicale ──
  "tonal-accord": { fr: "Détecte le nom d'un accord à partir d'une liste de notes. Exemple : C E G → C major. Accepte des notes séparées par des espaces, virgules ou points-virgules.", en: "Detects a chord name from a list of notes. Example: C E G → C major. Accepts notes separated by spaces, commas or semicolons." },
  "tonal-gamme": { fr: "Liste les notes d'une gamme choisie. Exemple : C major → C D E F G A B. Les types disponibles incluent major, minor, dorian, mixolydian, lydian, phrygian et locrian.", en: "Lists the notes of a chosen scale. Example: C major → C D E F G A B. Available types include major, minor, dorian, mixolydian, lydian, phrygian and locrian." },
  "tonal-transposer": { fr: "Transpose une note d'un intervalle donné. Exemple : C4 + 2M → D4. Utilise la notation d'intervalle de Tonal (1P, 2m, 2M, 3m, 3M, 4P, 5P, 6m, 6M, 7m, 7M, 8P).", en: "Transposes a note by a given interval. Example: C4 + 2M → D4. Uses Tonal interval notation (1P, 2m, 2M, 3m, 3M, 4P, 5P, 6m, 6M, 7m, 7M, 8P)." },
  "tonal-progression": { fr: "Génère une progression d'accords à partir d'une tonalité et de chiffres romains. Exemple : C + I V vi IV → C G Am F. Les chiffres romains acceptent les majuscules (accords majeurs) et les minuscules (accords mineurs).", en: "Generates a chord progression from a key and roman numerals. Example: C + I V vi IV → C G Am F. Roman numerals accept uppercase (major chords) and lowercase (minor chords)." },
  "tonal-grille": { fr: "Génère un accompagnement complet au format texte-vers-midi. Sa sortie « Notation » alimente une conversion vers le MIDI. Accepte une progression en chiffres romains (I V vi IV) ou en symboles d'accords (C Am F G). Paramètres : tonalité, tempo, durée par accord, octave et mode Bloc/Arpège.", en: "Generates a full accompaniment in text-to-MIDI format. Connect its « Notation » output to the « Text → MIDI » node to get a MIDI/audio file. Accepts a progression in roman numerals (I V vi IV) or chord symbols (C Am F G). Parameters: key, tempo, duration per chord, octave and Block/Arpeggio mode." },
  "tonal-analyse": { fr: "Analyse un audio et estime sa tonalité globale, puis suggère une progression adaptée (Pop, Jazz, Blues). Sortie « Tonalité » = tonalité estimée avec confiance, « Progression » = chiffres romains suggérés, « Accords détectés » = accords détectés dans le temps. La sortie « Progression » alimente une grille d'accords.", en: "Analyses audio and estimates its global key, then suggests a fitting progression (Pop, Jazz, Blues). « Key » output = estimated key with confidence, « Progression » = suggested roman numerals, « Detected chords » = chords detected over time. Connect the « Progression » output to « Chord Grid » to generate an accompaniment." },
  "vexflow-portee": { fr: "Génère une portée de notation musicale (SVG) à partir d'une notation texte. Format : note/octave/durée, ex. « C4/q D4/8 E4/8 F4/q G4/q ». Les durées sont w, h, q, 8, 16, 32. Les accords s'écrivent avec des + : « C4+E4+G4/q ». La portée s'affiche dans le composant, et son SVG est disponible sur la sortie texte.", en: "Generates a musical staff (SVG) from a text notation. Format: note/octave/duration, e.g. « C4/q D4/8 E4/8 F4/q G4/q ». Durations are w, h, q, 8, 16, 32. Chords use +: « C4+E4+G4/q ». Connect the SVG output to a « Text output » node or view it directly in the node." },
  "vexflow-tab": { fr: "Génère une tablature (SVG) à partir d'une notation texte corde-fret. Format : « corde-fret/durée », ex. « 6-3/q 5-0/q 5-2/q 4-0/q 5-3/q ». Le paramètre « Accordage » affiche le titre (guitare, ukulélé, basse).", en: "Generates a tablature (SVG) from a string-fret text notation. Format: « string-fret/duration », e.g. « 6-3/q 5-0/q 5-2/q 4-0/q 5-3/q ». The « Tuning » parameter sets the title (guitar, ukulele, bass)." },
  "vexflow-grille": { fr: "Génère une grille d'accords (SVG) à partir d'une liste de symboles ou d'une progression en chiffres romains. Règle « Mesures par ligne » pour contrôler la mise en page. L'entrée reçoit une suite d'accords, telle qu'une analyse harmonique en produit.", en: "Generates a chord chart (SVG) from a list of chord symbols or a roman numeral progression. Settings: « Measures per line » to control the layout. Connect the « Chords » output of a Tonal node or harmonic analysis." },
  "vexflow-partition": { fr: "Génère une partition simple (SVG) à partir d'une progression d'accords. Accepte les chiffres romains (I V vi IV) ou les symboles d'accords (C Am F G). Les accords sont affichés comme des accords bloqués sur la portée.", en: "Generates a simple score (SVG) from a chord progression. Accepts roman numerals (I V vi IV) or chord symbols (C Am F G). Chords are displayed as block chords on the staff." },
  "vexflow-midi": { fr: "Génère une portée de notation (SVG) à partir d'un fichier MIDI. L'entrée reçoit un fichier MIDI. Paramètres : Tempo (0 = détecté dans le MIDI), canal MIDI (-1 = tous), quantification rythmique et clé. La sortie SVG peut être exportée avec le composant « Export SVG ».", en: "Generates a musical staff (SVG) from a MIDI file. Connect a MIDI file (output from MIDI Transcriber, MIDI Player, etc.). Parameters: Tempo (0 = detected from MIDI), MIDI channel (-1 = all), rhythmic quantization and clef. The SVG output can be saved with the « SVG Export » node." },
  "soundtouch-tempo": { fr: "Change le tempo de l'audio en préservant la hauteur, grâce à l'algorithme SoundTouch (phase vocoder avancé). Alternative de meilleure qualité au node « Changement de tempo » natif, en particulier sur la voix et les signaux harmoniques.", en: "Changes audio tempo while preserving pitch, using the SoundTouch algorithm (advanced phase vocoder). Higher-quality alternative to the native « Tempo Change » node, especially on voice and harmonic signals." },
  "pitch-progressif": { fr: "Répète le son n+1 fois en le transposant d'un cran de plus à chaque reprise, des silences les séparant. Avec 3 boucles, 10 s de pause et −5 demi-tons : l'original, puis −5, puis −10, puis −15 st. La sortie dure 4 fois la source + 30 s, le pitch-shift de SoundTouch préservant la durée de chaque passage. Il n'y a pas de silence après le dernier passage : 3 boucles donnent trois pauses, pas quatre. Chaque reprise est calculée depuis l'original avec k fois le pas, jamais en ré-appliquant le décalage au résultat précédent : les deux donnent la même hauteur, mais un pitch-shift est une opération avec pertes, et l'enchaîner accumulerait ses artefacts au point que la dernière reprise sonnerait nettement moins bien que la première sans que le réglage l'explique. Le palier 0 ne passe pas du tout par le transposeur, qui dégraderait le signal pour un décalage nul. À savoir : au-delà de 12 demi-tons de descente cumulée, le timbre se creuse fortement — c'est l'effet recherché pour une chute progressive, moins pour une simple transposition, où le composant SoundTouch Tonalité convient mieux.", en: "Repeats the sound n+1 times, shifting it one step further each time, with silences in between. With 3 loops, a 10 s gap and -5 semitones: the original, then -5, then -10, then -15 st. The output lasts 4 times the source + 30 s, since SoundTouch's pitch-shift preserves each pass's duration. There is NO silence after the last pass: 3 loops give three gaps, not four. Each repeat is computed from the original using k times the step, never by re-applying the shift to the previous result: both give the same pitch, but a pitch-shift is lossy, and chaining it would accumulate artefacts until the last repeat sounded markedly worse than the first with nothing in the settings to explain it. Step 0 does not go through the shifter at all, which would degrade the signal for a zero shift. Note: past 12 cumulative semitones down the timbre hollows out considerably — the point of a progressive fall, less so for a plain transposition, where the SoundTouch Pitch node is a better fit." },
  "soundtouch-tonalite": { fr: "Transpose la hauteur de l'audio en préservant la durée, grâce à l'algorithme SoundTouch (phase vocoder avancé). Alternative de meilleure qualité au node « Changement de tonalité » natif, en particulier sur la voix.", en: "Transposes audio pitch while preserving duration, using the SoundTouch algorithm (advanced phase vocoder). Higher-quality alternative to the native « Pitch Change » node, especially on voice." },
  "soundtouch-rate": { fr: "Change la vitesse de lecture de l'audio (tempo + hauteur ensemble), comme un lecteur magnétique ou un sampler. Utilise l'algorithme SoundTouch. À 2×, la piste dure deux fois moins longtemps et sonne une octave plus haut.", en: "Changes audio playback rate (tempo + pitch together), like a tape player or sampler. Uses the SoundTouch algorithm. At 2×, the track lasts half as long and sounds one octave higher." },
  "phase-vocoder-tempo": { fr: "Change le tempo par phase vocoder (traitement fréquentiel FFT). L'option « transients » active la détection de transitoires pour préserver les attaques de percussions/plucks. Alternative au time-stretch natif et à SoundTouch pour un rendu plus lisse sur les ratios extrêmes.", en: "Changes tempo via phase vocoder (FFT frequency-domain processing). The « transients » option enables transient detection to preserve drum/pluck attacks. Alternative to native time-stretch and SoundTouch for smoother results at extreme ratios." },
  "phase-vocoder-tonalite": { fr: "Transpose la hauteur par phase vocoder (traitement fréquentiel FFT), sans modifier la durée de la piste. L'algorithme étire le signal dans le temps puis le rééchantillonne à la longueur d'origine. Alternative au pitch-shift natif pour les effets créatifs.", en: "Transposes pitch via phase vocoder (FFT frequency-domain processing), without changing the track duration. The algorithm stretches the signal in time then resamples it back to the original length. Alternative to native pitch-shift for creative effects." },
  "ddsp-tone-transfer": { fr: "Transfère le timbre d’un audio vers un autre instrument par DDSP (Differentiable Digital Signal Processing). Le modèle spice extrait la hauteur et le volume de l’audio d’entrée, puis un modèle DDSP pré-entraîné resynthétise le signal avec le timbre choisi (violon, flûte, saxophone ténor, trompette). Nécessite une connexion Internet pour télécharger spice et le modèle d’instrument (~3-4 MB). Sortie mono à 48 kHz.", en: "Transfers the timbre of an audio clip to another instrument via DDSP (Differentiable Digital Signal Processing). The spice model extracts pitch and loudness from the input audio, then a pretrained DDSP model resynthesizes the signal with the chosen timbre (violin, flute, tenor saxophone, trumpet). Requires an Internet connection to download spice and the instrument model (~3-4 MB). Output is mono at 48 kHz." },
  "magenta-drums": { fr: "Génère une boucle de batterie neuronale avec @magenta/music (MusicVAE drums_2bar_nade_9_q2). Le modèle se télécharge au premier usage (~28 MB). Le résultat est émis sur la sortie MIDI. Les paramètres Température, Tempo et Mesures permettent de contrôler le style et la longueur.", en: "Generates a neural drum loop with @magenta/music (MusicVAE drums_2bar_nade_9_q2). The model downloads on first use (~28 MB). MIDI output; connect to a MIDI Output to listen. Temperature, Tempo and Bars parameters control the style and length." },
  "magenta-continuation": { fr: "Continue une mélodie MIDI avec @magenta/music (MusicRNN melody_rnn). Le modèle se télécharge au premier usage (~3-4 MB). L’entrée reçoit un fichier MIDI ; le composant ajoute les pas demandés après la mélodie. Température, nombre de pas et quantification réglables.", en: "Continues a MIDI melody with @magenta/music (MusicRNN melody_rnn). The model downloads on first use (~3-4 MB). Connect a MIDI file to the input; the node appends the requested steps after the input melody. Adjustable temperature, steps and quantization." },
  "magenta-improvisation": { fr: "Génère une improvisation au piano avec @magenta/music (Piano Genie). Le modèle se télécharge au premier usage (~100 MB). Huit boutons virtuels sont pilotés par un motif (aléatoire, marche, montant, descendant, arpège) et mappés vers 88 touches de piano. Le résultat est émis sur la sortie MIDI. Réglable : durée, tempo, température, mode et graine.", en: "Generates a piano improvisation with @magenta/music (Piano Genie). The model downloads on first use (~100 MB). Eight virtual buttons are driven by a pattern (random, walk, up, down, arpeggio) and mapped to 88 piano keys. MIDI output; connect to a MIDI Output to listen. Adjustable: duration, tempo, temperature, mode and seed." },
  "magenta-generer-melodie": { fr: "Génère une mélodie à partir d’un fichier MIDI de départ avec @magenta/music (MusicRNN melody_rnn). Le modèle se télécharge au premier usage (~13 MB). L’entrée reçoit un MIDI ; le composant ajoute les pas demandés après l’amorce. Température, nombre de pas et quantification réglables.", en: "Generates a melody from a seed MIDI file with @magenta/music (MusicRNN melody_rnn). The model downloads on first use (~13 MB). Connect a MIDI to the input; the node appends the requested steps after the seed. Adjustable temperature, steps and quantization." },
  "magenta-interpoler-midi": { fr: "Génère un MIDI intermédiaire entre deux fichiers MIDI avec @magenta/music (MusicVAE mel_2bar_small). Le modèle se télécharge au premier usage (~18 MB). Les entrées A et B reçoivent deux MIDI ; les réglages donnent le nombre d’interpolations et la position. Sortie MIDI.", en: "Generates an intermediate MIDI file between two MIDI files with @magenta/music (MusicVAE mel_2bar_small). The model downloads on first use (~18 MB). Connect two MIDI files to inputs A and B; choose the number of interpolations and the position. MIDI output." },
  "magenta-generer-batterie": { fr: "Génère une boucle de batterie avec @magenta/music (MusicVAE drums_2bar_nade). Le modèle se télécharge au premier usage (~28 MB). Sans entrée, le composant génère un pattern aléatoire. Avec un seed MIDI, il produit une variation. Réglable : température, tempo, mesures, similarité.", en: "Generates a drum loop with @magenta/music (MusicVAE drums_2bar_nade). The model downloads on first use (~28 MB). Without input, the node generates a random pattern. With a MIDI seed, it produces a variation. Adjustable: temperature, tempo, bars, similarity." },
  "magenta-humaniser-groove": { fr: "Humanise un pattern de batterie MIDI avec @magenta/music (GrooVAE). Le modèle se télécharge au premier usage (~16 MB). L’entrée reçoit un MIDI de batterie ; le composant ajoute des variations de vélocité et de placement. Température et quantification réglables.", en: "Humanizes a MIDI drum pattern with @magenta/music (GrooVAE). The model downloads on first use (~16 MB). Connect a drum MIDI to the input; the node adds velocity and timing variations. Adjustable temperature and quantization." },
  "echo": { fr: "Delay/écho ping-pong avec feedback. Le temps règle l'intervalle entre les répétitions, le feedback contrôle leur nombre et la répartition contrôle le balayage stéréo. Signal direct + effet humide mélangés en sortie.", en: "Ping-pong delay/echo with feedback. Time sets the interval between repetitions, feedback controls how many repetitions occur, and spread controls the stereo sweep. Dry and wet signals are mixed at the output." },
  "voice-changer": { fr: "Transforme une voix avec des effets prédéfinis accessibles via une liste déroulante : Chipmunk (aigu/cartoon), Monster (grave/démoniaque), Robot (formants abaissés + modulation), Phone (bande téléphonique), Alien, Helium et Ghost. Le traitement combine pitch-shift et décalage formantique pour des résultats naturels.", en: "Transforms a voice with preset effects from a dropdown: Chipmunk (high/cartoon), Monster (low/demonic), Robot (lowered formants + modulation), Phone (telephone bandwidth), Alien, Helium and Ghost. The processing combines pitch-shift and formant shifting for natural-sounding results." },
  // ── Analyse / Visualisation ──
  "analyse-audio": { fr: "Estime le tempo, la tonalité et le type (chanson / instrumental) de la piste et en produit une description texte.", en: "Estimates the tempo, key and type (song / instrumental) of the track and produces a text description." },
  "lecteur-analyse": { fr: "Affiche le résultat d'une analyse et permet d'écouter l'audio associé.", en: "Displays an analysis result and lets you listen to the associated audio." },
  "classificateur-genre": { fr: "Identifie le genre musical de la piste, par modèle ONNX ou par heuristiques sur les caractéristiques audio.", en: "Identifies the musical genre of the track, via an ONNX model or heuristics on audio features." },
  "accords-vers-notation": { fr: "Traduit la sortie d'Analyse harmonique en notation exécutable par Texte → MIDI. Source « Accords détectés » : transcrit l'harmonie réelle en convertissant les durées mesurées (secondes) en temps, via le Tempo. Source « Progression » : développe les chiffres romains suggérés, ce qui exige aussi l'entrée Tonalité.", en: "Translates Harmonic Analysis output into notation playable by Text → MIDI. « Detected chords » source: transcribes the actual harmony, converting the measured durations (seconds) into beats via Tempo. « Progression » source: expands the suggested roman numerals, which also requires the Key input." },
  "transcripteur-midi": { fr: "Transcrit l'audio en notes MIDI, par détection de hauteur monophonique (FFT) ou polyphonique (Basic Pitch ONNX).", en: "Transcribes audio into MIDI notes, via monophonic pitch detection (FFT) or polyphonic (Basic Pitch ONNX)." },
  "detecteur-accords": { fr: "Analyse le signal audio et détecte la progression d'accords au fil du temps. Pour chaque fenêtre d'analyse, un chromagramme (vecteur de 12 classes de hauteur) est calculé puis comparé à des templates d'accords (majeur, mineur, 7ᵉ, mineur 7ᵉ, majeur 7ᵉ, diminué, augmenté, sus2, sus4, mineur 7♭5) par corrélation. Le résultat est une liste d'accords avec leur horodatage et durée. Réglages : la fenêtre d'analyse : courte (0,2-0,5 s) pour détecter les changements rapides, longue (1-2 s) pour plus de stabilité. Le signal audio est retransmis inchangé sur la sortie Audio.", en: "Analyzes the audio signal and detects the chord progression over time. For each analysis window, a chromagram (12 pitch-class vector) is computed and compared against chord templates (major, minor, 7th, minor 7th, major 7th, diminished, augmented, sus2, sus4, minor 7b5) by correlation. The result is a list of chords with their timestamp and duration. Settings: the analysis window — short (0.2-0.5 s) for fast changes, long (1-2 s) for more stability. The audio signal is passed through unchanged on the Audio output." },
  "centroide-spectral": { fr: "Calcule le centroïde spectral du signal avec la bibliothèque Meyda. Le centroïde est le « centre de gravité » du spectre : une valeur élevée indique un son brillant / aigu, une valeur faible un son sombre / grave. L'audio d'entrée est retransmis inchangé sur la sortie Audio ; la sortie Centroïde émet une valeur textuelle en Hz (moyenne, médiane ou maximum des centroïdes par trame).", en: "Computes the spectral centroid of the signal using the Meyda library. The centroid is the « center of gravity » of the spectrum: a high value indicates a bright / trebly sound, a low value a dark / bass-heavy sound. The input audio is passed through unchanged on the Audio output; the Centroid output emits a textual value in Hz (mean, median or maximum of the per-frame centroids)." },
  "rms-meyda": { fr: "Calcule le niveau RMS (Root Mean Square) moyen du signal avec Meyda. Le résultat est converti en dBFS pour une lecture intuitive : 0 dBFS = crête maximale, -60 dBFS = très silencieux. L'audio d'entrée est retransmis inchangé sur la sortie Audio ; la sortie RMS émet une valeur textuelle en dBFS.", en: "Computes the average RMS (Root Mean Square) level of the signal using Meyda. The result is converted to dBFS for intuitive reading: 0 dBFS = maximum peak, -60 dBFS = very quiet. The input audio is passed through unchanged on the Audio output; the RMS output emits a textual value in dBFS." },
  "zcr-meyda": { fr: "Compte le nombre de passages par zéro du signal dans chaque fenêtre d'analyse avec Meyda. Le ZCR est une indication simple de la « brillance » ou du caractère noisé du signal : un ZCR élevé suggère des fréquences aiguës ou du bruit, un ZCR faible suggère des sons graves ou des signaux continus. L'audio d'entrée est retransmis inchangé ; la sortie ZCR émet une valeur textuelle en passages par zéro.", en: "Counts the number of zero crossings of the signal in each analysis frame using Meyda. ZCR is a simple indicator of the « brightness » or noisiness of the signal: a high ZCR suggests high frequencies or noise, a low ZCR suggests low sounds or continuous signals. The input audio is passed through unchanged; the ZCR output emits a textual value in zero crossings." },
  "rolloff-spectral-meyda": { fr: "Calcule le rolloff spectral du signal avec Meyda : la fréquence sous laquelle se concentre une proportion donnée (85 %) de l'énergie spectrale. C'est un indicateur de la brillance globale du son : un rolloff haut = son brillant, un rolloff bas = son sombre. L'audio d'entrée est retransmis inchangé ; la sortie Rolloff émet une valeur textuelle en Hz.", en: "Computes the spectral rolloff of the signal using Meyda: the frequency below which a given proportion (85%) of the spectral energy is concentrated. It is an indicator of the overall brightness of the sound: a high rolloff = bright sound, a low rolloff = dark sound. The input audio is passed through unchanged; the Rolloff output emits a textual value in Hz." },
  "vu-metre": { fr: "Mesure et affiche les niveaux audio en temps réel. Quatre bargraphes verticaux : RMS (niveau moyen en dBFS), Peak (crête en dBFS), True Peak (crête interpolée 4× en dBTP, pour détecter l'inter-échantillon) et LUFS (loudness normalisée ITU-R BS.1770 avec filtre K-weighting). Affiche aussi le facteur de crête (crest factor = peak − RMS, indique la dynamique), la plage dynamique (LRA approximative) et les LUFS min/max momentanées. Le signal est retransmis inchangé. Sert au contrôle des niveaux avant export, à la comparaison de mixages et au calibrage.", en: "Measures and displays audio levels in real time. Four vertical bargraphs: RMS (average level in dBFS), Peak (in dBFS), True Peak (4× interpolated peak in dBTP, to detect inter-sample peaks) and LUFS (ITU-R BS.1770 loudness with K-weighting filter). Also shows the crest factor (peak − RMS, indicates dynamics), dynamic range (approximate LRA) and min/max momentary LUFS. The signal is passed through unchanged. Useful for checking levels before export, comparing mixes or calibrating equipment." },
  "colorsynth": { fr: "L'inverse du node « Combinaison de couleurs » : écoute le signal audio et déduit une palette de 6 couleurs à partir du spectre. Le spectre est divisé en 6 bandes (Sub, Bass, Low-Mid, Mid, High, Air) et chaque bande est mappée vers une couleur HSL : graves = couleurs chaudes (rouge/orange), médiums = vert, aigus = couleurs froides (bleu/violet). L'intensité lumineuse de chaque couleur = l'énergie de la bande. Pédagogique : « voir » le timbre — un son brillant aura des couleurs froides dominantes, un son grave des couleurs chaudes. Placé après un traitement, il en montre l'effet sur le spectre.", en: "The inverse of the « Color Combination » node: listens to the audio signal and derives a palette of 6 colors from the spectrum. The spectrum is divided into 6 bands (Sub, Bass, Low-Mid, Mid, High, Air) and each band is mapped to an HSL color: lows = warm colors (red/orange), mids = green, highs = cool colors (blue/violet). The brightness of each color = the band's energy. Educational: « see » the timbre — a bright sound will have dominant cool colors, a bass-heavy sound warm colors. Placed after a processing node, it shows its effect on the spectrum." },
  "generateur-pochette": { fr: "Génère une pochette d'album procédurale en SVG — hors-ligne, instantané, sans GPU ni téléchargement. Saisissez un prompt (les couleurs sont déduites des mots-clés), un titre et un artiste (insérés dans l'image), choisissez un style visuel (12 styles), une palette (15 préréglages ou auto), la complexité, une bordure, une typographie et les dimensions. La sortie « Image » est un SVG chaînable vers un Rendu image, un Export image ou un Export SVG. La graine permet de reproduire exactement la même pochette.", en: "Generates procedural album cover art in SVG — offline, instant, no GPU or download. Enter a prompt (colors derived from keywords), a title and artist (inserted in the image), choose a visual style (12 styles), a palette (15 presets or auto), complexity, a border, a typography and dimensions. The « Image » output is a chainable SVG that can be connected to an Image Renderer, Image Export or SVG Export. The seed allows reproducing the exact same cover." },
  "gpt2-paroles": { fr: "Génère du texte par IA en utilisant DistilGPT-2 (Transformers.js, ONNX). L'entrée texte reçoit l'amorce, que le champ du composant fournit à défaut. Le modèle génère du texte à partir du prompt (en anglais pour de meilleurs résultats). Réglages :\n• la longueur (30-300 tokens)\n• la créativité (température 0.1-1.5)\n• la pénalité de répétition.\nLe modèle se télécharge depuis HuggingFace au premier usage (~330 MB, mis en cache). Tourne dans un Web Worker. Sert à amorcer une écriture ou à produire du texte inhabituel.", en: "Generates text via AI using DistilGPT-2 (Transformers.js, ONNX). Connect a « Text Source » or enter a prompt directly. The model generates text from the prompt (English for best results). Settings:\n• the length (30-300 tokens)\n• the creativity (temperature 0.1-1.5)\n• repetition penalty.\nThe model downloads from HuggingFace on first use (~330 MB, cached). Runs in a Web Worker. Used to start a text off, or to produce unusual text." },
  "qwen2.5-lyrics": { fr: "Génère du texte par IA avec le modèle Qwen2.5-0.5B (Transformers.js, ONNX). L'entrée texte reçoit l'amorce, que le champ du composant fournit à défaut. Le modèle supporte plusieurs langues, mais l'anglais donne les meilleurs résultats. Réglages :\n• la longueur (30-300 tokens)\n• la créativité (température 0.1-1.5)\n• la pénalité de répétition.\nLe modèle se télécharge depuis HuggingFace au premier usage (~500 MB, mis en cache). Tourne dans un Web Worker. Il s'agit d'un modèle distinct de DistilGPT-2, plus récent et multilingue.", en: "Generates text via AI using the Qwen2.5-0.5B model (Transformers.js, ONNX). Connect a « Text Input » or enter a prompt directly. The model supports several languages, but English works best. Settings:\n• the length (30-300 tokens)\n• the creativity (temperature 0.1-1.5)\n• repetition penalty.\nThe model downloads from HuggingFace on first use (~500 MB, cached). Runs in a Web Worker. This is a separate model from DistilGPT-2, newer and multilingual." },
  "reservoir-textuel": { fr: "Génère du texte par réseau de neurones aléatoires (Reservoir Computing), sans aucun entraînement ni dataset. Un réservoir de quelques neurones à poids aléatoires fait circuler des impulsions. Les activations sont mappées vers des lettres d'un alphabet pour produire des mots émergents. Le résultat est du texte « alien » — des mots qui n'existent pas mais qui ont une structure phonétique cohérente. Inspiré d'Allendia/EVY appliqué au langage. Paramètres : neurones (5-50), connectivité, mémoire, nombre de mots, alphabet (latin, voyelles-first, français avec accents), mot d'amorce et graine. Utile pour générer des noms de chansons, des paroles phonétiques ou de la poésie concrète.", en: "Generates text via random neural networks (Reservoir Computing), with no training or dataset. A reservoir of a few neurons with random weights circulates impulses. Activations are mapped to alphabet letters to produce emergent words. The result is « alien » text — words that don't exist but have a coherent phonetic structure. Inspired by Allendia/EVY applied to language. Parameters: neurons (5-50), connectivity, memory, word count, alphabet (Latin, vowels-first, French with accents), seed word and seed. Useful for generating song titles, phonetic lyrics or concrete poetry." },
  "nllb-paroles": { fr: "Génère des paroles multilingues par IA en deux étapes : (1) DistilGPT-2 génère les paroles en anglais à partir du prompt, (2) OPUS-MT traduit les paroles vers la langue cible choisie (français, espagnol, allemand, italien, portugais, russe, japonais, chinois, arabe, hindi). L'entrée texte reçoit l'amorce, que le champ du composant fournit à défaut. Le modèle est entraîné sur l'anglais. Le premier usage télécharge DistilGPT-2 (~330 MB) puis le modèle de traduction (~30 MB), tous deux mis en cache. Si la traduction échoue, les paroles en anglais sont renvoyées. Tourne dans des Web Workers.", en: "Generates multilingual lyrics via AI in two steps: (1) DistilGPT-2 generates lyrics in English from the prompt, (2) OPUS-MT translates the lyrics to the chosen target language (French, Spanish, German, Italian, Portuguese, Russian, Japanese, Chinese, Arabic, Hindi). Connect a « Text Input » or enter a prompt in English for best results. First use downloads DistilGPT-2 (~330 MB) then the translation model (~30 MB), both cached. If translation fails, the English lyrics are returned. Runs in Web Workers." },
  "galerie-exposition": { fr: "Génère une galerie HTML visuelle avec pochettes depuis un répertoire de MP3. Spécifiez le répertoire source (.mp3 uniquement), un répertoire de sortie et un titre. Le node crée un fichier index.html à la racine + copie les MP3 dans un sous-répertoire mp3/. Chaque piste a une pochette : extraite du tag ID3 du MP3 si disponible, sinon générée procéduralement (SVG). Nécessite Electron.", en: "Generates a visual HTML gallery with cover art from a directory of MP3 files. Each track cover is extracted from the MP3's ID3 tag if available, otherwise procedurally generated (SVG). Requires Electron." },
  "carte-sonore": { fr: "Charge un dossier de fichiers audio et génère à chaque exécution une carte d'une ville fictive. Des points de couleur sont placés sur la carte : cliquez sur un point pour écouter le son associé. Paramètres : Chemin (dossier), Graine (reproductibilité de la ville), Points (nombre maximum de sons affichés). Nécessite Electron.", en: "Loads a folder of audio files and generates a fictional city map on each run. Colored points are placed on the map: click a point to hear the associated sound. Parameters: Path (folder), Seed (reproducibility of the city), Points (maximum number of sounds shown). Requires Electron." },
  "coordonnees-sur-carte": { fr: "Variante de Carte sonore pilotée par des données plutôt qu'un dossier : l'entrée reçoit les coordonnées d'un composant de classification (ex. Classification de pistes) pour positionner les points selon la similarité calculée, au lieu d'un placement aléatoire. Le décor (routes, quartiers, bâtiments) reste procédural — même Style et Esthétique que Carte sonore. Si la sortie « Rapport » du même composant de classification est aussi branchée, chaque point prend la couleur de son groupe plutôt que le cycle de palette habituel. Nécessite Electron.", en: "A Sound Map variant driven by data instead of a folder: connect a classification node's « Coordinates » output (e.g. Track classification) to position points according to computed similarity, instead of random placement. The backdrop (roads, districts, buildings) stays procedural — same Style and Aesthetic as Sound Map. If the same classification node's « Report » output is also connected, each point takes its group's color instead of the usual palette cycle. Requires Electron." },
  "automate-cellulaire": { fr: "Génère une séquence musicale à partir d'un automate cellulaire 1D (règles de Wolfram 30, 90, 110, 126, 150). Chaque génération de cellules devient un pas temporel. Les cellules actives sont projetées sur une gamme et une clé choisies pour former des accords (mode Polyphonie) ou une mélodie (mode Mélodie). Sortie Audio + MIDI. Les règles 90 et 150 produisent des structures fractales ; les règles 30 et 110 donnent des patterns plus chaotiques.\n\nEn 2D (Conway, Highlife), la grille entière évolue, et chaque génération est un pas de la séquence. Chaque cellule vivante sonne : sa colonne donne le degré dans la gamme, sa rangée le registre, sur trois octaves — le haut de la grille à l'aigu. Plusieurs cellules sur la même note s'additionnent, et leur nombre fait la vélocité quand le mapping la demande. On entend ainsi la vie de la grille : une configuration qui croît remplit le spectre, un motif qui se stabilise répète son accord, une grille qui s'éteint se tait. La graine 0 part d'un motif qui vit longtemps : en Conway, le R-pentomino, cinq cellules qui se déploient avant de se stabiliser ; en Highlife, le réplicateur, douze cellules qui se recopient le long d'une diagonale.", en: "Generates a musical sequence from a 1D cellular automaton (Wolfram rules 30, 90, 110, 126, 150). Each cell generation becomes a time step. Active cells are mapped to a chosen scale and key to form chords (Polyphony mode) or a melody (Melody mode). Audio + MIDI output. Rules 90 and 150 produce fractal structures; rules 30 and 110 yield more chaotic patterns.\n\nIn 2D (Conway, Highlife), the whole grid evolves, and each generation is a step of the sequence. Every live cell sounds: its column gives the degree in the scale, its row the register, over three octaves - the top of the grid sounds high. Several cells on the same note add up, and their number sets the velocity when the mapping asks for it. One thus hears the life of the grid: a growing pattern fills the spectrum, a pattern that settles repeats its chord, a grid that dies out falls silent. Seed 0 starts from a long-lived pattern: in Conway, the R-pentomino, five cells that unfold before settling; in Highlife, the replicator, twelve cells that copy themselves along a diagonal." },
  "camelot": { fr: "Parcourt la roue de Camelot pour illustrer les transitions harmoniques utilisées par les DJ. Chaque case (4B, 7A, 12B…) correspond à une tonalité (anneau A = mineur, B = majeur). Le composant génère un parcours audio/MIDI + une visualisation SVG : tour complet de la roue, transitions compatibles (+1, -1, même numéro, +7) ou voyage aléatoire. Les accords sont joués en bloc ou en arpège. Le résultat est disponible en MIDI et en audio, sur deux sorties distinctes. La sortie Image peut être branchée sur un Rendu image ou un Export SVG.", en: "Travels the Camelot wheel to illustrate harmonic transitions used by DJs. Each slot (4B, 7A, 12B…) maps to a key (ring A = minor, B = major). The node generates an audio/MIDI journey plus an SVG visualization: full circle, compatible moves (+1, -1, same number, +7) or random walk. Chords are played as block or arpeggio. Connect the MIDI output to a MIDI output node to listen, or use the direct Audio output. The Image output can be connected to an Image Renderer or SVG Export." },
  "gestion-nodes": { fr: "Exporte un node existant en archive .zip ou importe un node depuis un .zip. Pour exporter : saisissez l'ID du node (ex : gpt2-paroles), le système extrait le manifest, le code executer, la notice et détecte les dépendances externes, puis génère un .zip. À l'import d'un .zip, le système décompresse, contrôle les dépendances et installe le composant dans le catalogue. Les nodes installés sont persistés et survivent aux redémarrages.", en: "Exports an existing node as a .zip archive or imports a node from a .zip. To export: enter the node ID, the system extracts the manifest, executer code, notice and detects dependencies, then generates a .zip. To import: select a .zip, the system decompresses, checks dependencies and installs the node in the catalog. Installed nodes are persisted and survive restarts." },
  "classification-pistes": { fr: "Charge un dossier de pistes audio, réduit chacune à un vecteur de 40 features (tempo, centroïde spectral, chroma, MFCC), les standardise puis les projette par PCA. Un KMeans (k fixé ou recherche automatique par indice de Calinski-Harabasz) regroupe les pistes dans l'espace réduit, puis un mélange de gaussiennes (GMM) estime la probabilité d'appartenance de chaque piste à chaque groupe. Cinq sorties : trois flux texte structurés (JSON) — le rapport de classification (groupe + probabilités par piste), les coordonnées 2D et les 3 plus proches voisins de chaque piste (distance euclidienne dans l'espace PCA du clustering) — réutilisables par un autre composant ou logiciel (ex. Coordonnées sur carte) — et deux sorties image SVG : un nuage de points (2 premiers axes PCA, survol = nom de la piste) et un tableau lisible des moyennes par groupe sur les variables de départ (variables en ligne, groupes en colonne), coloré par écart à la moyenne inter-groupes de chaque ligne pour repérer d'un coup d'œil ce qui distingue les groupes. Nécessite au moins 3 pistes décodables. Nécessite Electron.", en: "Loads a folder of audio tracks, reduces each to a 40-feature vector (tempo, spectral centroid, chroma, MFCC), standardizes them, then projects them via PCA. A KMeans (fixed k or automatic search via the Calinski-Harabasz index) groups the tracks in the reduced space, then a Gaussian mixture (GMM) estimates each track's probability of belonging to each group. Five outputs: three structured text (JSON) streams — the classification report (group + probabilities per track), the 2D coordinates, and each track's 3 nearest neighbors (Euclidean distance in the clustering's PCA space) — reusable by another node or software (e.g. Coordinates on Map) — and two SVG image outputs: a scatter plot (first 2 PCA axes, hover = track name) and a readable table of per-group averages on the original variables (variables as rows, groups as columns), colored by deviation from each row's cross-group average to spot at a glance what distinguishes the groups. Requires at least 3 decodable tracks. Requires Electron." },
  "alignement-dtw": { fr: "Aligne deux pistes qui diffèrent en tempo ou en durée (une reprise plus lente, un remix, deux prises d'un même morceau) par Dynamic Time Warping sur leur chromagramme (trame par trame, ~11.6 ms). Le calcul du chemin optimal se fait par damiers (mémoire en O(√n·m) plutôt que O(n·m)) : la mémoire n'est plus le facteur limitant, seul le temps de calcul reste quadratique — le paramètre « Durée max analysée » (extrait central par piste, 3 min par défaut) sert donc à borner le temps, pas la mémoire. Deux sorties texte : « Similarité », un score normalisé dans [0, 1] (1 = identiques, 0 = sans rapport — coût cumulé du chemin optimal divisé par sa longueur, indépendant de la durée des pistes), et « Chemin d'alignement », en JSON : `{ chemin: [{i, j}, ...], debutEchantillonA }` — la correspondance trame par trame entre les deux pistes, plus le décalage (en échantillons) où l'extrait de la Piste A a été pris dans son buffer d'origine, pour qu'un composant consommateur (Étirement temporel (DTW)) puisse s'y repérer sans redemander la même « Durée max analysée ». Ne produit pas d'audio réétiré : la sortie « Chemin d'alignement » porte le résultat, que l'étirement temporel consomme.", en: "Aligns two tracks that differ in tempo or duration (a slower cover, a remix, two takes of the same piece) via Dynamic Time Warping on their chromagram (frame by frame, ~11.6 ms). The optimal path is computed using checkpointed blocks (O(√n·m) memory instead of O(n·m)): memory is no longer the limiting factor, only compute time stays quadratic — the « Max analyzed duration » parameter (centered excerpt per track, 3 min by default) therefore bounds time, not memory. Two text outputs: « Similarity », a normalized [0, 1] score (1 = identical, 0 = unrelated — the optimal path's cumulative cost divided by its length, independent of track duration), and « Alignment path », as JSON: `{ chemin: [{i, j}, ...], debutEchantillonA }` — the frame-by-frame correspondence between the two tracks, plus the offset (in samples) where Track A's excerpt was taken from its original buffer, so a downstream node (Time Stretch (DTW)) can locate itself without needing the same « Max analyzed duration » again. Does not produce re-stretched audio: this is deliberately a separate node — connect « Alignment path » (and the same Track A) to Time Stretch (DTW) for that." },
  "etirement-dtw": { fr: "[expérimental — résultat très discutable] Réétire l'audio de la Piste A le long d'un chemin d'alignement reçu sur l'entrée du même nom, la Piste A devant être celle qui a servi à le calculer. Rééchantillonnage simple par interpolation linéaire le long de la correspondance de trames — pas un vocodeur de phase : la hauteur dérive localement partout où le débit change (comme une lecture à vitesse variable), une limite connue plutôt qu'un défaut caché. La sortie prend le débit et le nombre de canaux de la Piste A, mais sa durée suit le nombre de trames de la piste étalon (déduit du chemin) — jamais besoin de l'audio de l'étalon lui-même. Nécessite que Similarité audio ait tourné en premier sur la même Piste A.", en: "[experimental — very questionable result] Re-stretches Track A's audio along the alignment path produced by Audio Similarity (connect its « Alignment path » output here, and the same Track A to both nodes). Simple linear-interpolation resampling along the frame correspondence — not a phase vocoder: pitch drifts locally wherever the rate changes (like variable-speed playback), a known limitation rather than a hidden defect. The output takes Track A's sample rate and channel count, but its duration follows the reference track's frame count (derived from the path) — never needs the reference track's audio itself. Requires Audio Similarity to have run first on the same Track A." },
  "pca-neuronale": { fr: "PCA neuronale : entraîne un autoencodeur non linéaire sur le spectrogramme de magnitude de la piste d'entrée et resynthétise un audio filtré par l'espace latent. Chaque trame temporelle devient un vecteur de bins fréquentiels (taille FFT fixe, nombre de trames déduit du hop). La magnitude est convertie en échelle dB/log et standardisée avant l'entraînement. L'architecture est un entonnoir progressif : taille d'entrée → couches cachées déduites par interpolation géométrique → espace latent (nombre d'axes). Activation ReLU ou Tanh. L'entraînement se fait à la volée sur les trames de cette piste seule (pas de modèle préentraîné) : l'interface affiche l'époque courante et la perte, et un budget-temps (automatique ou forcé) peut arrêter l'entraînement en conservant les poids de la dernière époque. La phase originale est conservée pour la resynthèse par STFT inverse. Résultat non déterministe sans graine fixée. Un garde-fou compare la perte finale à la base triviale (reconstruire chaque trame par la trame moyenne) et avertit si l'autoencodeur n'a pas fait mieux.", en: "Neural PCA: trains a non-linear autoencoder on the input track's magnitude spectrogram and resynthesizes a latent-filtered audio. Each time frame becomes a vector of frequency bins (fixed FFT size, number of frames derived from hop). The magnitude is converted to dB/log scale and standardized before training. The architecture is a progressive bottleneck: input size → hidden layers derived by geometric interpolation → latent space (number of axes). ReLU or Tanh activation. Training happens on the fly on this track's frames only (no pretrained model): the UI shows the current epoch and loss, and a time budget (automatic or forced) can stop training while keeping the last epoch's weights. The original phase is kept for inverse-STFT resynthesis. Result is non-deterministic without a fixed seed. A guard compares the final loss to the trivial baseline (reconstructing every frame by the mean frame) and warns if the autoencoder did not improve on it." },
  "continuation-spectrale-ar": { fr: "Prolonge une piste audio en prédissant la suite de son spectrogramme. Le modèle autoregressif linéaire (dense) est entraîné à la volée sur les frames de magnitude (en dB) de la piste elle-même : il apprend à prédire une frame à partir des N frames précédentes. Génération autoregressive : les frames prédites sont réinjectées dans l'historique pour prédire la suivante. La phase est propagée de manière cohérente (incrément de phase par bin), puis resynthèse par STFT inverse. C'est l'équivalent audio d'une prédiction de série temporelle (AR/ARIMA) : le résultat est expérimental, plus proche d'une texture que d'une continuation musicale structurée, mais entièrement local et sans modèle préentraîné.", en: "Extends an audio track by predicting the continuation of its spectrogram. A linear autoregressive (dense) model is trained on the fly on the track's own magnitude frames (in dB): it learns to predict a frame from the previous N frames. Autoregressive generation: predicted frames are fed back into the history to predict the next one. Phase is propagated coherently (per-bin phase increment), then resynthesized by inverse STFT. This is the audio equivalent of a time-series prediction (AR/ARIMA): the result is experimental, closer to a texture than to a structured musical continuation, but fully local and without a pretrained model." },
  "continuation-spectrale-lstm": { fr: "Prolonge une piste audio par un petit réseau récurrent (LSTM) entraîné à la volée sur son spectrogramme de magnitude. Même principe que Continuation AR, mais le modèle est non-linéaire et séquentiel : la couche LSTM mémorise le contexte des frames passées pour prédire la frame future. La phase est propagée de manière cohérente et le résultat est resynthétisé par STFT inverse. Qualité expérimentale, entièrement locale, sans modèle préentraîné.", en: "Extends an audio track with a small recurrent network (LSTM) trained on the fly on its magnitude spectrogram. Same principle as AR Continuation, but the model is non-linear and sequential: the LSTM layer memorizes the context of past frames to predict the future frame. Phase is propagated coherently and the result is resynthesized by inverse STFT. Experimental quality, fully local, no pretrained model." },
  "python-processor": { fr: "Éditeur de code Python avec coloration syntaxique pour traiter l'audio. L'audio d'entrée est converti en WAV temporaire et passé au script via sys.argv[1]. Le script doit écrire le résultat dans le chemin donné par os.environ['attic_output_path']. Variables disponibles : Attic_sample_rate, Attic_channels. Le code par défaut lit le WAV, double le volume et écrit le résultat. Nécessite Python + numpy installés sur la machine. La détection de Python est automatique (python, python3, py) ou via la variable d'environnement Attic_Python. Timeout réglable (5-120s).", en: "Python code editor with syntax highlighting for audio processing. Input audio is converted to a temporary WAV and passed to the script via sys.argv[1]. The script must write the result to the path given by os.environ['attic_output_path']. Available variables: Attic_sample_rate, Attic_channels. The default code reads the WAV, doubles the volume and writes the result. Requires Python + numpy installed on the machine. Python detection is automatic (python, python3, py) or via the Attic_Python environment variable. Adjustable timeout (5-120s)." },
  "julia-processor": { fr: "Éditeur de code Julia avec coloration syntaxique pour traiter l'audio, le MIDI et le texte. Même architecture que le Python Processor. Variables : ARGS[2] = WAV d'entrée, ENV[\"Attic_output_path\"] = WAV de sortie, ENV[\"Attic_sample_rate\"], ENV[\"Attic_channels\"]. Nécessite Julia + le package WAV.jl installés sur la machine.", en: "Julia code editor with syntax highlighting for audio, MIDI and text processing. Same architecture as the Python Processor. Variables: ARGS[2] = input WAV, ENV[\"Attic_output_path\"] = output WAV, ENV[\"Attic_sample_rate\"], ENV[\"Attic_channels\"]. Requires Julia + WAV.jl package installed." },
  "couleur-suno-ia": { fr: "Génère un script Suno/Udio par IA en combinant la psychologie des couleurs et un LLM (DistilGPT-2). Réglages : une ou deux couleurs — chaque couleur est mappée vers un profil musical (émotion, mode, tempo, instruments, styles, voix). Le profil structuré est ensuite enrichi par le LLM qui génère un prompt créatif et unique. La variabilité (0-100%) contrôle la température du LLM : élevée = scripts très créatifs et différents à chaque fois ; basse = scripts proches du template. La graine assure la reproductibilité. Le script final combine le profil structuré + le prompt IA + les tags. Dépendance : @huggingface/transformers (téléchargement du modèle au premier usage, ~330 MB, mis en cache).", en: "Generates a Suno/Udio script via AI by combining color psychology and a LLM (DistilGPT-2). Settings: one or two colours — each color is mapped to a musical profile (emotion, mode, tempo, instruments, styles, vocals). The structured profile is then enriched by the LLM which generates a creative and unique prompt. Variability (0-100%) controls the LLM temperature: high = very creative and different scripts each time; low = scripts close to the template. The seed ensures reproducibility. The final script combines the structured profile + AI prompt + tags. Dependency: @huggingface/transformers (model download on first use, ~330 MB, cached)." },
  "transposeur-quantiseur-midi": { fr: "Reçoit un fichier MIDI et le transforme : transposition (±24 demi-tons) et/ou quantification rythmique (alignement des départs de notes sur une grille : 1/4, 1/8, 1/16, 1/32, triplets). Option pour quantifier aussi les fins de notes. Le fichier transformé est émis sur la sortie MIDI. Utile pour corriger un enregistrement humain imprécis ou adapter une mélodie à une autre tonalité.", en: "Takes a MIDI file and transforms it: transposition (±24 semitones) and/or rhythmic quantization (snapping note onsets to a grid: 1/4, 1/8, 1/16, 1/32, triplets). Option to also quantize note ends. The transformed file is output on the MIDI port. Useful for correcting imprecise human recordings or adapting a melody to another key." },
  "arpegiateur-midi": { fr: "Transforme les accords d'un fichier MIDI en arpèges. Détecte les notes simultanées (accords) et les réarpège selon une direction (montant, descendant, aller-retour, aléatoire), un motif de répétition intra-accord (1232, 1321…), une vitesse (1/8, 1/16, 1/32, triplets) et une amplitude en octaves (1-4, chaque octave ajoute +12 demi-tons). La durée des notes est réglable (staccato à legato). Le fichier transformé est émis sur la sortie MIDI.", en: "Turns chords from a MIDI file into arpeggios. Detects simultaneous notes (chords) and arpeggiates them according to a direction (up, down, up-down, random), an intra-chord repetition pattern (1232, 1321…), a speed (1/8, 1/16, 1/32, triplets) and an octave span (1-4, each octave adds +12 semitones). Note length is adjustable (staccato to legato). The transformed file is output on the MIDI port." },
  "jointure-midi": { fr: "Concatène deux fichiers MIDI bout à bout. Le deuxième fichier démarre à la fin du premier (chevauchement = 0) ou avant (chevauchement > 0), ce qui superpose les notes. Les événements de chaque fichier sont conservés, y compris les changements de programme/instrument. Le fichier joint est émis sur la sortie MIDI.", en: "Concatenates two MIDI files end-to-end. The second file starts at the end of the first (overlap = 0) or before (overlap > 0), superimposing the notes. Events from each file are preserved, including program/instrument changes. The joined file is output on the MIDI port." },
  "boucle-midi": { fr: "Répète un fichier MIDI plusieurs fois à la suite. Le paramètre Fondu règle le chevauchement entre deux répétitions (en ms) : 0 = raccord sec, les répétitions se succèdent sans superposition ; une valeur positive fait démarrer la répétition suivante avant la fin de la précédente, créant un effet de superposition. La boucle résultante est émise sur la sortie MIDI.", en: "Repeats a MIDI file several times in a row. The Fade parameter sets the overlap between two repetitions (in ms): 0 = hard join, repetitions follow each other without overlap; a positive value starts the next repetition before the previous one ends, creating an overlapping effect. The resulting loop is output on the MIDI port." },
  "visualiseur-forme-onde": { fr: "Affiche la forme d'onde du signal reçu, avec zoom à la molette, et le retransmet inchangé.", en: "Displays the waveform of the received signal, with wheel zoom, and passes it through unchanged." },
  "visualisation-songsee": { fr: "Génère une image de visualisation audio via le moteur Songsee (spectrogram, mel, chroma, hpss, selfsim, loudness, tempogram, mfcc, flux). Réglages :\n• le mode de visualisation\n• la palette\n• les dimensions\n• la zone temporelle.\nLe node émet l'image sur sa sortie 'Image'. Nécessite Electron et le binaire Songsee embarqué.", en: "Generates an audio visualization image using the Songsee engine (spectrogram, mel, chroma, hpss, selfsim, loudness, tempogram, mfcc, flux). Settings:\n• the visualization mode\n• palette\n• dimensions\n• time range.\nThe node emits the image on its 'Image' output. Requires Electron and the bundled Songsee binary." },
  "export-image": { fr: "Sauvegarde une image (fichier) dans le répertoire de travail. L'entrée reçoit l'image de n'importe quelle sortie image du graphe. Le chemin du fichier sauvegardé est émis sur la sortie 'Chemin'. Nécessite Electron.", en: "Saves an image file to the working directory. Connect the 'Image' output of a Songsee node or any other image-producing node. The saved file path is emitted on the 'Path' output. Requires Electron." },
  "rendu-image": { fr: "Affiche une image reçue sur son entrée et la transmet inchangée sur sa sortie. Utile pour visualiser n'importe quelle image intermédiaire dans le graphe (spectrogramme, attracteur, etc.) sans couper la chaîne. La sortie peut être branchée vers un Export image, un Pixeltone ou un autre traitement.", en: "Displays an image received on its input and passes it through unchanged on its output. Useful for previewing any intermediate image in the graph (spectrogram, attractor, etc.) without breaking the chain. The output can be connected to an Image Export, a Pixeltone, or another processing node." },
  "pixeltone": { fr: "Convertit une image en son selon le principe de pixeltone.js : chaque pixel devient une tranche sonore dont les canaux rouge, vert et bleu sont mappés à trois plages de fréquences. Réglages : la durée par pixel et les plages RGB pour sculpter le résultat. L'entrée reçoit une image, générée ou importée ; l'audio sort sur le port de sortie. Nécessite un environnement navigateur pour décoder l'image.", en: "Converts an image to sound following the pixeltone.js principle: each pixel becomes a short sound slice whose red, green and blue channels are mapped to three frequency ranges. Settings: the duration per pixel and the RGB ranges to sculpt the result. Connect an image (generated or imported) to the input and get the audio on the output. Requires a browser environment to decode the image." },
  "palette-harmonique": { fr: "Extrait les couleurs dominantes d'une image et les transforme en une séquence musicale. La teinte détermine le degré dans la gamme choisie, la luminosité choisit l'octave, la saturation influe sur la vélocité, et la position horizontale de la couleur détermine le moment où elle joue. Le composant sort une sortie audio et une sortie MIDI. Deux modes : Mélodie (une note par couleur) et Harmonie (accord triadique par couleur). Paramètres : clé, gamme, mode, octave, portée (octaves de variation), durée totale, nombre de couleurs, ordre de lecture, synthèse (FM ou SoundFont), instrument, volume et tempo MIDI.", en: "Extracts the dominant colors of an image and turns them into a musical sequence. Hue determines the scale degree, lightness chooses the octave, saturation affects velocity, and the horizontal position of the color determines when it plays. The node outputs audio and MIDI. Two modes: Melody (one note per color) and Harmony (triad chord per color). Parameters: key, scale, mode, octave, range (variation octaves), total duration, number of colors, reading order, synthesis (FM or SoundFont), instrument, volume and MIDI tempo." },
  "dessin-sonore": { fr: "Sonifie les formes colorées d'une image de dessin (style Kandinsky). Le composant extrait d'abord une palette de couleurs dominantes, puis détecte les régions connexes de chaque couleur. Chaque forme devient une note (mode Mélodie), un accord (mode Harmonie) ou un accord décomposé en notes successives (mode Arpège). La position horizontale de la forme détermine le moment de jeu, la position verticale et la couleur influencent la hauteur, et la taille de la forme contrôle la durée et la vélocité. Sortie audio + sortie MIDI. Paramètres : clé, gamme, mode, octave, portée, durée, nombre de couleurs, taille minimale des formes, synthèse, instrument, volume et tempo.", en: "Sonifies the colored shapes of a drawing image (Kandinsky style). The node first extracts a palette of dominant colors, then detects connected regions of each color. Each shape becomes a note (Melody mode), a chord (Harmony mode) or a broken chord played one note after another (Arpeggio mode). Horizontal position determines timing, vertical position and color affect pitch, and shape size controls duration and velocity. Audio output + MIDI output. Parameters: key, scale, mode, octave, range, duration, number of colors, minimum shape size, synthesis, instrument, volume and tempo." },
  "couleur-rgb": { fr: "Synthétise une couleur RGB en trois oscillateurs sinusoïdaux. Chaque canal (rouge, vert, bleu) contrôle la fréquence d'un oscillateur dans une plage réglable. Fait entendre une couleur comme un timbre composite : gris = trois fréquences proches, couleur pure = un canal dominant. Paramètres : Rouge/Vert/Bleu (0-255), plages de fréquences pour chaque canal, durée, volume et nombre de canaux de sortie.", en: "Synthesizes an RGB color into three sine-wave oscillators. Each channel (red, green, blue) controls the frequency of one oscillator within an adjustable range. Renders a colour as a composite timbre: gray = three close frequencies, pure colour = one dominant channel. Parameters: Red/Green/Blue (0-255), frequency ranges for each channel, duration, volume and output channels." },
  "spectre-visible": { fr: "Transpose une couleur visible (longueur d'onde) dans le domaine audible. La couleur est convertie en longueur d'onde approximative, puis la fréquence de la lumière est divisée par des puissances de 2 jusqu'à devenir audible. Le résultat est un drone dont la hauteur dépend de la couleur : rouge = fréquence grave, violet = fréquence aiguë. Paramètres : Rouge/Vert/Bleu (0-255), couleur hexadécimale optionnelle, octave de transposition, durée, volume et canaux de sortie.", en: "Transposes a visible color (wavelength) into the audible range. The color is converted to an approximate wavelength, then the frequency of light is divided by powers of 2 until it becomes audible. The result is a drone whose pitch depends on the color: red = low frequency, violet = high frequency. Parameters: Red/Green/Blue (0-255), optional hex color, transposition octave, duration, volume and output channels." },
  "color-looper": { fr: "Séquenceur pas-à-pas où chaque pas est une couleur. Saisissez une liste de couleurs (hex ou rgb) séparées par des virgules ; le composant boucle sur ces couleurs et génère une note (ou un accord) par pas. La teinte détermine le degré de la gamme, la luminosité l'octave, la saturation la vélocité. Paramètres : liste de couleurs, clé, gamme, mode, octave, portée, tempo, durée de note, nombre de mesures, synthèse, instrument et volume. Sortie audio + MIDI.", en: "Step sequencer where each step is a color. Enter a list of colors (hex or rgb), comma-separated; the node loops over the colors and generates a note (or chord) per step. Hue determines the scale degree, lightness the octave, saturation the velocity. Parameters: color list, key, scale, mode, octave, range, tempo, note duration, number of bars, synthesis, instrument and volume. Audio output + MIDI output." },
  "analyseur-spectre": { fr: "Décompose le signal en ses fréquences (transformée de Fourier rapide) et en affiche le spectre : niveau (dB) par fréquence, moyenné sur toute la piste. Réglages : la taille de fenêtre FFT (résolution) et l'échelle (log/linéaire). Le signal est retransmis inchangé.", en: "Decomposes the signal into its frequencies (fast Fourier transform) and displays the spectrum: level (dB) per frequency, averaged over the whole track. Settings: the FFT window size (resolution) and axis scale (log/linear). The signal is passed through unchanged." },
  "spectrogramme": { fr: "Affiche l'évolution du spectre dans le temps : axe horizontal = temps, axe vertical = fréquence, couleur = intensité (sombre → clair). On y voit apparaître les notes, harmoniques et transitoires. Réglages : la fenêtre FFT (compromis temps/fréquence) et l'échelle. Le signal est retransmis inchangé.", en: "Shows how the spectrum evolves over time: horizontal = time, vertical = frequency, color = intensity (dark → bright). Notes, harmonics and transients appear. Settings: the FFT window (time/frequency trade-off) and scale. The signal is passed through unchanged." },
  "oscillateur": { fr: "Génère une forme d'onde pure par synthèse additive (somme d'harmoniques, sans repliement). La vue montre en haut quelques périodes de l'onde et en bas ses harmoniques : un sinus = une seule barre ; carré/triangle = harmoniques impaires ; dent de scie = toutes. Illustre le lien timbre ↔ harmoniques.", en: "Generates a pure waveform by additive synthesis (sum of harmonics, alias-free). The view shows a few periods of the wave on top and its harmonics below: a sine = a single bar; square/triangle = odd harmonics; sawtooth = all of them. Illustrates the timbre ↔ harmonics link." },
  "comparateur-ab": { fr: "Compare deux sources (A et B) en basculant l'écoute d'un bouton, à niveau égalisé pour une comparaison honnête (le plus fort semble sinon meilleur). L'entrée A tient le signal d'origine, l'entrée B le signal traité.", en: "Compares two sources (A and B) by toggling which one you hear, at matched level for a fair comparison (the louder one otherwise seems better). Ideal to judge the effect of a process: connect the original signal to A and the processed one to B." },
  // ── Conversion / Sorties ──
  "convertisseur-audio": { fr: "Encode le signal en MP3 téléchargeable à la qualité choisie, tout en le laissant passer sur la sortie audio.", en: "Encodes the signal into a downloadable MP3 at the chosen quality, while passing it through on the audio output." },
  "convertisseur-mp3-wav": { fr: "Met le signal à disposition en WAV téléchargeable, tout en le laissant passer sur la sortie audio.", en: "Makes the signal available as a downloadable WAV, while passing it through on the audio output." },
  "point-ecoute": { fr: "Point d'écoute intermédiaire : permet d'auditionner le signal à un endroit de la chaîne sans l'interrompre.", en: "Intermediate listening point: lets you audition the signal at a spot in the chain without interrupting it." },
  "sortie-audio": { fr: "Point d'écoute final : joue le signal reçu, applique le volume et permet l'export. Fournit aussi la durée de la piste.", en: "Final output: plays the received signal, applies the volume and enables export. Also provides the track duration." },
  "modifier-texte": { fr: "Se place derrière n'importe quelle sortie texte — transcription Sherpa, extraction PDF, sortie d'un LLM, paroles générées — pour l'adapter avant ce qui suit : un prompt MusicGen, une synthèse vocale, un Texte → MIDI. C'était le maillon manquant entre les composants qui produisent du texte et ceux qui en consomment, et qui obligeait à passer par un Processeur Python pour un simple remplacement. Une seule opération à la fois, choisie dans la liste : remplacement littéral, remplacement par expression régulière (où $1 et $2 reprennent les groupes capturés), passage en majuscules ou minuscules, nettoyage des espaces, ou encadrement par un préfixe et un suffixe. Pour en combiner plusieurs, chaînez plusieurs exemplaires du composant — c'est ce que le graphe rend naturel, et cela évite un composant par opération dans un catalogue qui en compte déjà 245. À savoir : un motif d'expression régulière invalide ne fait pas échouer le composant ; le texte ressort inchangé et le message donne la cause, parce qu'on écrit ces motifs en tâtonnant et qu'interrompre tout le graphe à chaque parenthèse oubliée serait insupportable. Le nettoyage des espaces préserve les sauts de ligne : un texte de paroles garde sa structure.", en: "Sits behind any text output — Sherpa transcription, PDF extraction, LLM output, generated lyrics — to adapt it before whatever comes next: a MusicGen prompt, speech synthesis, a Text to MIDI. It links nodes that produce text to nodes that consume it, without a detour through a script for a simple replacement. One operation at a time, picked from the list: literal replace, regular-expression replace (where $1 and $2 refer to captured groups), upper or lower case, whitespace tidying, or wrapping with a prefix and a suffix. To combine several, chain several copies of the node — which is what a graph makes natural, and avoids one node per operation in a catalogue that already holds 245. Note: an invalid regular expression does not fail the node; the text passes through unchanged and the message gives the reason, because these patterns are written by trial and error and halting the whole graph on every missing bracket would be unbearable. Whitespace tidying preserves line breaks: lyrics keep their structure." },
  "sortie-texte": { fr: "Affiche le texte reçu sur son entrée (port bleu). Le texte s'affiche dans le composant avec un bouton de copie (⧉) pour le coller ailleurs. L'entrée reçoit le texte de n'importe quelle sortie texte du graphe.", en: "Displays the text received on its input (blue port). The text is shown in the node with a copy button (⧉) to paste elsewhere. Connect the output of an AI script generator, translator, chord detector, AI-generated lyrics or any other text-producing node." },
  "sortie-midi": { fr: "Reçoit un fichier MIDI, le synthétise en audio (FM ou SoundFont) et transmet à la fois l'audio, le MIDI et la durée.", en: "Receives a MIDI file, synthesizes it to audio (FM or SoundFont) and passes along the audio, the MIDI and the duration." },
  // ── Collections ──
  "collection-vers-mp3": { fr: "Traite par lot un dossier : convertit tous les fichiers audio (WAV, OGG…) en MP3 dans le dossier de sortie (Electron).", en: "Batch-processes a folder: converts all audio files (WAV, OGG…) to MP3 in the output folder (Electron)." },
  "collection-mp3-vers-wav": { fr: "Traite par lot un dossier : convertit tous les MP3 en WAV dans le dossier de sortie (Electron).", en: "Batch-processes a folder: converts all MP3 files to WAV in the output folder (Electron)." },
  "collection-midi-vers-mp3": { fr: "Traite par lot un dossier : synthétise tous les fichiers MIDI et les exporte en MP3 dans le dossier de sortie (Electron).", en: "Batch-processes a folder: synthesizes all MIDI files and exports them as MP3 in the output folder (Electron)." },
  "collection-lecteur-musique": { fr: "Lecteur simple sans entrée ni sortie. La lecture demande un dossier de musique, un titre, puis le bouton ▶. Inclut lecture aléatoire, lecture en boucle, volume et barre de progression. Nécessite Electron.", en: "Simple player with no input or output. Playback takes a music folder, a track, then the ▶ button. Includes shuffle, loop, volume and a progress bar. Requires Electron." },
  // ── Derniers composants livrés ──
  "tts-piper": { fr: "Synthèse vocale locale multilingue via Piper TTS (ONNX). L'entrée texte (port bleu) reçoit le texte à dire. Réglages : une voix (russe, anglais, français, allemand, espagnol). Le modèle ONNX de la voix est téléchargé depuis HuggingFace la première fois, puis mis en cache.", en: "Local multilingual text-to-speech using Piper TTS (ONNX). Connect a « Text Source » node to the text input (blue port). Settings: a voice (Russian, English, French, German, Spanish). The ONNX voice model is downloaded from HuggingFace the first time, then cached." },
  "tts-kokoro": { fr: "Synthèse vocale locale en anglais via Kokoro-82M (ONNX, Transformers.js). L'entrée texte (port bleu) reçoit le texte à dire. Réglages : la voix, en anglais américain ou britannique, et la vitesse. Le modèle se télécharge depuis HuggingFace au premier usage (~80 MB en q8, mis en cache). Tourne dans un Web Worker.", en: "Local English text-to-speech using Kokoro-82M (ONNX, Transformers.js). Connect a « Text Source » node to the text input (blue port). Pick a voice (US or British English) and adjust the speed. The model downloads from HuggingFace on first use (~80 MB in q8, cached). Runs in a Web Worker." },
  "tts-francais": { fr: "Synthèse vocale en français via Kokoro-82M (ONNX, Transformers.js) avec la voix Siwis. La phonémisation française est faite par ephone (eSpeak-NG WASM). L'entrée texte (port bleu) reçoit le texte à dire. Réglages : la vitesse. Le modèle se télécharge depuis HuggingFace au premier usage (~80 MB en q8, mis en cache). Tourne dans un Web Worker.", en: "French text-to-speech using Kokoro-82M (ONNX, Transformers.js) with the Siwis voice. French phonemization is handled by ephone (eSpeak-NG WASM). Connect a « Text Source » node to the text input (blue port). Settings: the speed. The model downloads from HuggingFace on first use (~80 MB in q8, cached). Runs in a Web Worker." },
  "export-svg": { fr: "Sauvegarde un fichier SVG sur disque et retourne son chemin. L'entrée reçoit une image au format SVG. Le chemin du fichier sauvegardé est émis sur la sortie 'Chemin'. L'extension de sortie est forcée à .svg. Nécessite Electron.", en: "Saves an SVG file to disk and returns its path. Connect an 'Image' output producing an SVG (e.g. the « SVG Reader ») to the input. The saved file path is emitted on the 'Path' output. The output extension is forced to .svg. Requires Electron." },
  "ocr": { fr: "Reconnaissance optique de caractères (OCR) avec Tesseract.js (WASM). L'entrée reçoit une image (PNG, JPEG…). Le node reconnaît du texte dans plusieurs alphabets (latin, cyrillique, grec, arabe, hébreu par défaut). Chaque langue télécharge son modèle (~2-10 Mo) depuis le CDN Tesseract au premier usage. Le texte reconnu est émis sur la sortie 'Texte'.", en: "Optical character recognition (OCR) using Tesseract.js (WASM). Connect an image (PNG, JPEG…) to the input. The node recognizes text in multiple alphabets (Latin, Cyrillic, Greek, Arabic, Hebrew by default). Each language downloads its model (~2-10 MB) from the Tesseract CDN on first use. The recognized text is emitted on the 'Text' output." },
  "entree-pdf": { fr: "Charge un fichier PDF depuis l'inspecteur et le transmet sur sa sortie « Fichier » — à brancher sur Extraction PDF.", en: "Loads a PDF file from the inspector and passes it to its « File » output — connect to PDF Extraction." },
  "extraction-pdf": { fr: "Extrait le texte déjà numérique d'un PDF avec pdf-inspector (Rust/WASM, https://github.com/firecrawl/pdf-inspector), 100% local. Ce n'est pas de l'OCR : seul le texte déjà présent dans le fichier (pas une image de texte) est récupéré, en quelques dizaines à centaines de ms. Détecte aussi le type de PDF (texte, scanné, image, mixte) et le signale clairement dans le message si tout ou partie des pages n'ont pas de texte récupérable — dans ce cas il faudrait rasteriser ces pages puis les passer au composant OCR séparément (non géré ici). Paramètre Format : Texte brut (contenu seul) ou Markdown (titres, listes, tableaux reconstruits depuis la mise en page).", en: "Extracts already-digital text from a PDF using pdf-inspector (Rust/WASM, https://github.com/firecrawl/pdf-inspector), fully local. This is not OCR: only text already embedded in the file (not a text image) is recovered, in tens to hundreds of ms. Also detects the PDF type (text, scanned, image, mixed) and clearly flags it in the message if some or all pages have no recoverable text — in that case those pages would need to be rasterized and passed to the OCR node separately (not handled here). Format parameter: Plain text (content only) or Markdown (headings, lists, tables reconstructed from the layout)." },
};

